diff --git a/apps/gooseforum/app/bundles/domainpolicy/domainpolicy.go b/apps/gooseforum/app/bundles/domainpolicy/domainpolicy.go
new file mode 100644
index 000000000..e64585c0c
--- /dev/null
+++ b/apps/gooseforum/app/bundles/domainpolicy/domainpolicy.go
@@ -0,0 +1,115 @@
+// Package domainpolicy canonicalizes the trusted-external-domain whitelist
+// (issue #1200): the admin-configurable list of hostnames whose normal-risk
+// external links skip the "leaving the site" confirmation on Web and Flutter.
+//
+// Entries are stored as plain lower-cased hostnames — no scheme, path, port,
+// wildcard or IP literal — so the browser-side matcher can compare them with
+// URL.hostname verbatim. An entry also covers its subdomains
+// ("bilibili.com" matches "live.bilibili.com"); the reverse never holds.
+// Entries that are themselves a public suffix ("com", "co.uk", "github.io")
+// are rejected: they would exempt every tenant / every domain below them.
+package domainpolicy
+
+import (
+	"net/netip"
+	"strings"
+
+	"golang.org/x/net/idna"
+	"golang.org/x/net/publicsuffix"
+)
+
+// MaxEntries caps the stored whitelist. Entries beyond the cap are reported
+// as dropped so the save path rejects the submission instead of truncating.
+const MaxEntries = 200
+
+// maxDomainLength is the DNS name limit (RFC 1035 §3.1) including labels.
+const maxDomainLength = 253
+
+// maxLabelLength is the DNS label limit (RFC 1035 §3.1).
+const maxLabelLength = 63
+
+// CanonicalizeList trims, lower-cases, de-duplicates and validates every
+// entry while preserving submission order. Blank entries are skipped silently
+// (paste noise) and duplicates collapse onto the first occurrence; invalid
+// entries and entries beyond MaxEntries are returned in dropped so callers can
+// reject the whole submission (save path) or filter stored values (read path).
+func CanonicalizeList(entries []string) (kept []string, dropped []string) {
+	kept = make([]string, 0, len(entries))
+	seen := make(map[string]struct{}, len(entries))
+	for _, raw := range entries {
+		value, ok := Canonicalize(raw)
+		if !ok {
+			dropped = append(dropped, raw)
+			continue
+		}
+		if value == "" {
+			continue
+		}
+		if _, exists := seen[value]; exists {
+			continue
+		}
+		if len(kept) >= MaxEntries {
+			dropped = append(dropped, raw)
+			continue
+		}
+		seen[value] = struct{}{}
+		kept = append(kept, value)
+	}
+	return kept, dropped
+}
+
+// Canonicalize validates one whitelist entry and returns its stored form.
+// Empty entries are valid and yield "". The stored form is ASCII lower-case
+// with a trailing root dot removed; IDN input is converted to its punycode
+// form so it compares equal to the browser's URL.hostname.
+func Canonicalize(raw string) (string, bool) {
+	value := strings.TrimSpace(raw)
+	if value == "" {
+		return "", true
+	}
+	if len(value) > maxDomainLength {
+		return value, false
+	}
+	lowered := strings.ToLower(strings.TrimSuffix(value, "."))
+	if lowered == "" {
+		return value, false
+	}
+	// Reject anything outside the hostname alphabet before IDNA mapping so
+	// "github.com/path", "github.com:443", "*.github.com" and control
+	// characters fail here instead of relying on the mapper's leniency.
+	for _, r := range lowered {
+		switch {
+		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-', r == '.', r > 0x7f:
+		default:
+			return value, false
+		}
+	}
+	ascii, err := idna.Lookup.ToASCII(lowered)
+	if err != nil {
+		return value, false
+	}
+	ascii = strings.ToLower(ascii)
+	if len(ascii) > maxDomainLength {
+		return value, false
+	}
+	// A single label (localhost, an intranet short name) is not a public site.
+	if !strings.Contains(ascii, ".") {
+		return value, false
+	}
+	// IP literals are not domains: the whitelist targets public sites, and the
+	// client-side registrable-domain logic cannot reason about addresses.
+	if _, err := netip.ParseAddr(ascii); err == nil {
+		return value, false
+	}
+	for _, label := range strings.Split(ascii, ".") {
+		if label == "" || len(label) > maxLabelLength || strings.HasPrefix(label, "-") || strings.HasSuffix(label, "-") {
+			return value, false
+		}
+	}
+	// An entry that is a public suffix would exempt every domain under it
+	// (e.g. "github.io" exempts all GitHub Pages tenants, "com" everything).
+	if suffix, _ := publicsuffix.PublicSuffix(ascii); suffix == ascii {
+		return value, false
+	}
+	return ascii, true
+}

diff --git a/apps/gooseforum/app/bundles/domainpolicy/domainpolicy_test.go b/apps/gooseforum/app/bundles/domainpolicy/domainpolicy_test.go
new file mode 100644
index 000000000..0b4896f3b
--- /dev/null
+++ b/apps/gooseforum/app/bundles/domainpolicy/domainpolicy_test.go
@@ -0,0 +1,113 @@
+package domainpolicy
+
+import (
+	"fmt"
+	"strings"
+	"testing"
+)
+
+func TestCanonicalizeEntry(t *testing.T) {
+	valid := map[string]string{
+		"github.com":        "github.com",
+		"  GitHub.COM  ":    "github.com",
+		"bilibili.com.":     "bilibili.com",
+		"mp.weixin.qq.com":  "mp.weixin.qq.com",
+		"中国.com":            "xn--fiqs8s.com",
+		"xn--fiqs8s.com":    "xn--fiqs8s.com",
+		"a-b.example.co.uk": "a-b.example.co.uk",
+		"zh.wikipedia.org":  "zh.wikipedia.org",
+	}
+	for raw, want := range valid {
+		got, ok := Canonicalize(raw)
+		if !ok {
+			t.Errorf("Canonicalize(%q) = invalid, want valid", raw)
+			continue
+		}
+		if got != want {
+			t.Errorf("Canonicalize(%q) = %q, want %q", raw, got, want)
+		}
+	}
+
+	// Blank entries are valid and collapse to "" (paste noise is skipped, not
+	// rejected).
+	if got, ok := Canonicalize("   "); !ok || got != "" {
+		t.Errorf("Canonicalize(blank) = (%q, %v), want (\"\", true)", got, ok)
+	}
+
+	invalid := []string{
+		"https://github.com",
+		"http://github.com",
+		"github.com/path",
+		"github.com:443",
+		"github.com?q=1",
+		"github.com#frag",
+		"*.github.com",
+		"github .com",
+		"user@github.com",
+		"github,com",
+		"github\u0000.com",
+		"java\nscript:alert(1)",
+		"localhost",
+		"com",
+		"co.uk",
+		"github.io",
+		"192.168.1.1",
+		"[::1]",
+		"-github.com",
+		"github-.com",
+		"github..com",
+		".github.com",
+		strings.Repeat("a", maxLabelLength+1) + ".com",
+		strings.Repeat("a", maxDomainLength) + ".com",
+	}
+	for _, raw := range invalid {
+		if got, ok := Canonicalize(raw); ok {
+			t.Errorf("Canonicalize(%q) = (%q, valid), want invalid", raw, got)
+		}
+	}
+}
+
+func TestCanonicalizeListKeepsOrderAndReportsInvalid(t *testing.T) {
+	kept, dropped := CanonicalizeList([]string{
+		"GitHub.com",
+		"",
+		"  ",
+		"github.com",
+		"https://bilibili.com",
+		"bilibili.com",
+		"mp.weixin.qq.com",
+	})
+	want := []string{"github.com", "bilibili.com", "mp.weixin.qq.com"}
+	if len(kept) != len(want) {
+		t.Fatalf("kept = %q, want %q", kept, want)
+	}
+	for i := range want {
+		if kept[i] != want[i] {
+			t.Fatalf("kept = %q, want %q", kept, want)
+		}
+	}
+	if len(dropped) != 1 || dropped[0] != "https://bilibili.com" {
+		t.Fatalf("dropped = %q, want the scheme-carrying entry", dropped)
+	}
+}
+
+func TestCanonicalizeListCapsEntries(t *testing.T) {
+	entries := make([]string, 0, MaxEntries+1)
+	for i := 0; i <= MaxEntries; i++ {
+		entries = append(entries, fmt.Sprintf("site%d.example.com", i))
+	}
+	kept, dropped := CanonicalizeList(entries)
+	if len(kept) != MaxEntries {
+		t.Fatalf("kept %d entries, want %d", len(kept), MaxEntries)
+	}
+	if len(dropped) != 1 || dropped[0] != entries[MaxEntries] {
+		t.Fatalf("dropped = %q, want the entry beyond the cap", dropped)
+	}
+}
+
+func TestCanonicalizeListEmptyInput(t *testing.T) {
+	kept, dropped := CanonicalizeList(nil)
+	if len(kept) != 0 || len(dropped) != 0 {
+		t.Fatalf("CanonicalizeList(nil) = (%q, %q), want empty", kept, dropped)
+	}
+}

diff --git a/apps/gooseforum/app/bundles/feedconfig/config.go b/apps/gooseforum/app/bundles/feedconfig/config.go
new file mode 100644
index 000000000..769a31862
--- /dev/null
+++ b/apps/gooseforum/app/bundles/feedconfig/config.go
@@ -0,0 +1,286 @@
+// Package feedconfig owns the immutable, non-secret feed parameter contract.
+package feedconfig
+
+import (
+	"crypto/sha256"
+	"encoding/hex"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"math"
+	"sync"
+	"sync/atomic"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/preferences"
+	"github.com/spf13/cast"
+)
+
+const CandidateCap = 240
+const FallbackCap = 60
+const SnapshotSize = 120
+const PageSize = 20
+const RawRetentionDays = 30
+
+type Weights struct {
+	Follow   float64 `json:"follow"`
+	Recency  float64 `json:"recency"`
+	Quality  float64 `json:"quality"`
+	Daily    float64 `json:"daily"`
+	Category float64 `json:"category"`
+	Author   float64 `json:"author"`
+	NewReply float64 `json:"newReply"`
+}
+
+type Config struct {
+	Personalization FixedPolicy       `json:"personalization"`
+	Rules           MaterializedRules `json:"rules"`
+	Limits          ResourceLimits    `json:"limits"`
+	RankHash        string            `json:"rankHash"`
+	Algorithm       string            `json:"algorithm"`
+	Enabled         bool              `json:"enabled"`
+	Ranking         bool              `json:"ranking"`
+	Metrics         bool              `json:"metrics"`
+	Rollout         int               `json:"rollout"`
+	RetentionDays   int               `json:"retentionDays"`
+	JobsPerSecond   int               `json:"jobsPerSecond"`
+	QueryTimeoutMS  int               `json:"queryTimeoutMs"`
+	SampleRate      float64           `json:"sampleRate"`
+	Experiment      string            `json:"experiment"`
+	Salt            string            `json:"salt"`
+	Weights         Weights           `json:"weights"`
+	Comparison      bool              `json:"comparison"`
+	Interleaving    bool              `json:"interleaving"`
+	Alternative     Weights           `json:"alternative"`
+	Hash            string            `json:"-"`
+}
+
+func Default() Config {
+	w := Weights{1, .8, 1, .5, .6, .5, .4}
+	return Config{Personalization: DefaultPolicy(), Rules: DefaultRules(), Limits: HardLimits(), Algorithm: "rules-v4-hot-daily-v1-seen", Rollout: 20, RetentionDays: 30, JobsPerSecond: 20, QueryTimeoutMS: 250, SampleRate: .05, Experiment: "default-entry-v1", Salt: "default-entry-v1", Weights: w, Alternative: w}
+}
+
+func Decode(settings map[string]any) (Config, error) {
+	c := Default()
+	var decodeErr error
+	get := func(path ...string) (any, bool) {
+		var cur any = settings
+		for _, key := range path {
+			m, ok := cur.(map[string]any)
+			if !ok {
+				return nil, false
+			}
+			cur, ok = m[key]
+			if !ok {
+				return nil, false
+			}
+		}
+		return cur, true
+	}
+	b := func(dst *bool, path ...string) {
+		if v, ok := get(path...); ok {
+			value, err := cast.ToBoolE(v)
+			if err != nil {
+				decodeErr = errors.Join(decodeErr, err)
+			}
+			*dst = value
+		}
+	}
+	i := func(dst *int, path ...string) {
+		if v, ok := get(path...); ok {
+			value, err := cast.ToIntE(v)
+			if err != nil {
+				decodeErr = errors.Join(decodeErr, err)
+			}
+			*dst = value
+		}
+	}
+	f := func(dst *float64, path ...string) {
+		if v, ok := get(path...); ok {
+			value, err := cast.ToFloat64E(v)
+			if err != nil {
+				decodeErr = errors.Join(decodeErr, err)
+			}
+			*dst = value
+		}
+	}
+	s := func(dst *string, path ...string) {
+		if v, ok := get(path...); ok {
+			value, err := cast.ToStringE(v)
+			if err != nil {
+				decodeErr = errors.Join(decodeErr, err)
+			}
+			*dst = value
+		}
+	}
+	b(&c.Enabled, "feed", "for_you", "enabled")
+	b(&c.Ranking, "ranking", "enabled")
+	b(&c.Metrics, "feed", "metrics", "enabled")
+	i(&c.Rollout, "feed", "for_you", "rollout_percent")
+	i(&c.RetentionDays, "feed", "metrics", "raw_retention_days")
+	i(&c.JobsPerSecond, "ranking", "jobs_per_second")
+	i(&c.QueryTimeoutMS, "ranking", "query_timeout_ms")
+	f(&c.SampleRate, "feed", "metrics", "candidate_sample_rate")
+	s(&c.Experiment, "feed", "experiments", "period")
+	s(&c.Salt, "feed", "experiments", "salt")
+	b(&c.Comparison, "feed", "experiments", "weight_comparison_enabled")
+	b(&c.Interleaving, "feed", "experiments", "interleaving_enabled")
+	weights := func(w *Weights, key string) {
+		for name, dst := range map[string]*float64{"follow": &w.Follow, "recency": &w.Recency, "quality": &w.Quality, "daily": &w.Daily, "category": &w.Category, "author": &w.Author, "new_reply": &w.NewReply} {
+			f(dst, "feed", key, name)
+		}
+	}
+	weights(&c.Weights, "weights")
+	weights(&c.Alternative, "alternative_weights")
+	f(&c.Rules.HotLikeWeight, "ranking", "hot", "like_weight")
+	f(&c.Rules.HotReplyWeight, "ranking", "hot", "reply_weight")
+	for key, dst := range map[string]*float64{"view_weight": &c.Rules.DailyWeights[0], "replier_weight": &c.Rules.DailyWeights[1], "reply_weight": &c.Rules.DailyWeights[2], "like_weight": &c.Rules.DailyWeights[3], "bookmark_weight": &c.Rules.DailyWeights[4]} {
+		f(dst, "ranking", "daily", key)
+	}
+	if decodeErr != nil {
+		return Config{}, decodeErr
+	}
+	if math.IsNaN(c.SampleRate) || math.IsInf(c.SampleRate, 0) {
+		return Config{}, fmt.Errorf("sample rate must be finite")
+	}
+	if c.Rollout < 0 || c.Rollout > 100 || c.RetentionDays < 1 || c.RetentionDays > 30 || c.JobsPerSecond < 1 || c.JobsPerSecond > 20 || c.QueryTimeoutMS < 1 || c.QueryTimeoutMS > 250 || c.SampleRate < 0 || c.SampleRate > .05 || len(c.Experiment) > 64 || c.Experiment == "" || len(c.Salt) > 128 || c.Salt == "" {
+		return Config{}, fmt.Errorf("feed parameters exceed supported bounds")
+	}
+	for _, w := range []Weights{c.Weights, c.Alternative} {
+		for _, v := range []float64{w.Follow, w.Recency, w.Quality, w.Daily, w.Category, w.Author, w.NewReply} {
+			if math.IsNaN(v) || math.IsInf(v, 0) || v < 0 || v > 10 {
+				return Config{}, fmt.Errorf("feed weights must be between zero and ten")
+			}
+		}
+	}
+	if c.Enabled && c.Metrics && c.Rollout > 0 && c.RetentionDays != 30 {
+		return Config{}, fmt.Errorf("default-entry experiment requires 30-day retention")
+	}
+	if c.Comparison && c.Interleaving {
+		return Config{}, fmt.Errorf("only one weight comparison mode may be active")
+	}
+	sum := 0.
+	for _, v := range c.Rules.DailyWeights {
+		if math.IsNaN(v) || math.IsInf(v, 0) || v < 0 || v > 1 {
+			return Config{}, fmt.Errorf("daily weights must be finite in [0,1]")
+		}
+		sum += v
+	}
+	if math.Abs(sum-1) > 1e-8 {
+		return Config{}, fmt.Errorf("daily weights must sum to one")
+	}
+	for _, v := range []float64{c.Rules.HotLikeWeight, c.Rules.HotReplyWeight} {
+		if math.IsNaN(v) || math.IsInf(v, 0) || v < 0 || v > 50 {
+			return Config{}, fmt.Errorf("hot weights must be finite in [0,50]")
+		}
+	}
+	rankData, err := json.Marshal(c.Rules)
+	if err != nil {
+		return Config{}, err
+	}
+	rankDigest := sha256.Sum256(rankData)
+	c.RankHash = hex.EncodeToString(rankDigest[:16])
+	data, err := json.Marshal(c)
+	if err != nil {
+		return Config{}, err
+	}
+	hash := sha256.Sum256(data)
+	c.Hash = hex.EncodeToString(hash[:16])
+	return c, nil
+}
+
+var mu sync.Mutex
+var previous = Default()
+var previousRevision uint64
+var rankGeneration atomic.Uint64
+
+// RankGeneration fences an observed pause/resume, including changes made while
+// no ranking invalidation was written. It is independent of scoring parameters.
+func RankGeneration() uint64 { return rankGeneration.Load() }
+
+func init() {
+	preferences.AddValidator(func(settings map[string]any) error { _, err := Decode(settings); return err })
+}
+
+// Current captures all settings from one published preferences snapshot. Invalid
+// edits retain the last valid feed parameters, including enable/disable state.
+func Current() Config {
+	revision := preferences.Revision()
+	mu.Lock()
+	defer mu.Unlock()
+	if revision == previousRevision {
+		return previous
+	}
+	c, err := Decode(preferences.All())
+	if err == nil {
+		if previousRevision != 0 && previous.Ranking != c.Ranking {
+			rankReady.Store(nil)
+			rankGeneration.Add(1)
+		}
+		previous = c
+	}
+	previousRevision = revision
+	return previous
+}
+
+var rankReady atomic.Pointer[string]
+
+func SetRankReady(ready bool) {
+	if !ready {
+		rankReady.Store(nil)
+		return
+	}
+	h := Current().RankHash
+	rankReady.Store(&h)
+}
+func RankReady() bool {
+	c := Current()
+	h := rankReady.Load()
+	return c.Ranking && h != nil && *h == c.RankHash
+}
+
+// Versioned defaults capture every fixed coefficient and boundary in parameter
+// history. Hot/Daily weights may change only through a controlled full rebuild.
+type MaterializedRules struct {
+	Version           string     `json:"version"`
+	HotLikeWeight     float64    `json:"hotLikeWeight"`
+	HotReplyWeight    float64    `json:"hotReplyWeight"`
+	HotCaps           [2]float64 `json:"hotCaps"`
+	ReplyPerUser      uint32     `json:"replyPerUser"`
+	FreshHours        [6]int     `json:"freshHours"`
+	FreshValues       [6]float64 `json:"freshValues"`
+	ActiveHours       [4]int     `json:"activeHours"`
+	ActiveValues      [4]float64 `json:"activeValues"`
+	DailyHours        [3]int     `json:"dailyHours"`
+	AgeWeights        [3]float64 `json:"ageWeights"`
+	DailyCaps         [5]float64 `json:"dailyCaps"`
+	DailyWeights      [5]float64 `json:"dailyWeights"`
+	EngagementMinimum int        `json:"engagementMinimum"`
+	ViewMinimum       int        `json:"viewMinimum"`
+}
+
+func DefaultRules() MaterializedRules {
+	return MaterializedRules{"hot-daily-v1", 6, 14, [2]float64{50, 100}, 3, [6]int{6, 12, 24, 48, 72, 168}, [6]float64{30, 24, 18, 12, 8, 4}, [4]int{1, 6, 12, 24}, [4]float64{20, 12, 6, 2}, [3]int{3, 12, 24}, [3]float64{1, .7, .4}, [5]float64{300, 20, 50, 40, 15}, [5]float64{.30, .25, .15, .20, .10}, 2, 10}
+}
+func (r MaterializedRules) HotMax() float64 {
+	return r.HotLikeWeight + r.HotReplyWeight + r.FreshValues[0] + r.ActiveValues[0]
+}
+
+type ResourceLimits struct{ Candidates, Fallback, Snapshot, Page, ConcurrentBuilds, BackgroundConnections, SnapshotBytes, ProfileBytes, PublicPoolBytes, RepeatBytes, InferredBytes, ViewBytes, LogBytes, SampleBytes, DayBytes int }
+
+func HardLimits() ResourceLimits {
+	return ResourceLimits{240, 60, 120, 20, 2, 1, 32 << 20, 4 << 20, 1 << 20, 4 << 20, 2 << 20, 2 << 20, 8 << 20, 2 << 20, 2 << 20}
+}
+
+// These rules are versioned in the full parameter snapshot for exact replay.
+// Changing one is an algorithm change, rather than an independent live knob.
+type FixedPolicy struct {
+	OutOfNetwork, AuthorDiversity, AuthorFloor, Repeat, RecencyHalfLifeHours            float64
+	ProfileDays, ProfileLimit, ProfileHalfLifeDays, MinimumProfile, Categories, Authors int
+	ProfileLike, ProfileBookmark, ProfileReply                                          float64
+	SnapshotTTLMinutes, ReuseSeconds, HardDeadlineMS, TraceHours, ViewCooldownMinutes   int
+	ExplorationPositions                                                                [2]int
+}
+
+func DefaultPolicy() FixedPolicy {
+	return FixedPolicy{.75, .5, .25, .7, 12, 60, 100, 14, 5, 5, 50, 1, 1.5, 2, 30, 30, 200, 6, 5, [2]int{4, 11}}
+}

