diff --git a/apps/gooseforum/app/http/controllers/forum/feed.go b/apps/gooseforum/app/http/controllers/forum/feed.go
new file mode 100644
index 000000000..420822937
--- /dev/null
+++ b/apps/gooseforum/app/http/controllers/forum/feed.go
@@ -0,0 +1,186 @@
+package forum
+
+import (
+	"errors"
+	"net/http"
+	"net/url"
+	"strconv"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/feedconfig"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/i18n"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/http/controllers/component"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/http/controllers/transform"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/hotdataserve"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/feedservice"
+	"github.com/gin-gonic/gin"
+)
+
+func feedCapable(c *gin.Context) bool {
+	return !isPageRequest(c) || c.GetHeader("X-Goose-Feed-Version") == "2"
+}
+func foregroundPage(c *gin.Context) bool {
+	return c.GetHeader("X-Goose-Prefetch") != "1" && c.GetHeader("Sec-Purpose") != "prefetch"
+}
+
+func personalizeDefault(c *gin.Context, sort string) string {
+	uid := component.LoginUserId(c)
+	if uid > 0 {
+		c.Header("Cache-Control", "private, no-store")
+		c.Header("Vary", "X-Goose-Page, X-Goose-Feed-Version, Accept")
+		if foregroundPage(c) {
+			feedservice.CaptureActivity(uid)
+		}
+	}
+	if !feedCapable(c) {
+		if sort == "for_you" {
+			return "latest"
+		}
+		return sort
+	}
+	if uid > 0 && foregroundPage(c) {
+		treatment, variant, err := feedservice.AssignDefault(c.Request.Context(), uid)
+		if err == nil {
+			c.Set("feed.entryVariant", variant)
+			if treatment && sort == "" {
+				return "for_you"
+			}
+		}
+	}
+	if sort == "for_you" && !feedconfig.Current().Enabled {
+		c.Set("feed.degradeReason", "disabled")
+		return "latest"
+	}
+	return sort
+}
+
+func decorateFeedProps(c *gin.Context, props *HomeProps, items []feedservice.Candidate, hash string, versions ...feedconfig.Config) {
+	if !feedCapable(c) {
+		if foregroundPage(c) {
+			feedservice.CaptureLegacyServe(component.LoginUserId(c), props.Sort, items)
+		}
+		return
+	}
+	props.ActualSort = props.Sort
+	if reason, ok := c.Get("feed.degradeReason"); ok {
+		props.DegradeReason, _ = reason.(string)
+	}
+	for i := range props.Tabs {
+		if props.Tabs[i].Key == "latest" {
+			props.Tabs[i].URL = "/?sort=latest"
+		}
+	}
+	if component.LoginUserId(c) > 0 && feedconfig.Current().Enabled && feedconfig.RankReady() {
+		props.Tabs = append([]TabPayload{{Key: "for_you", Label: i18n.T(requestLang(c), "forYouFeed"), URL: "/?sort=for_you", Active: props.Sort == "for_you"}}, props.Tabs...)
+	}
+	if props.Sort == "latest" && props.Pagination.NextURL != "" {
+		u, _ := url.Parse(props.Pagination.NextURL)
+		q := u.Query()
+		q.Set("sort", "latest")
+		u.RawQuery = q.Encode()
+		props.Pagination.NextURL = u.String()
+	}
+	if !foregroundPage(c) {
+		return
+	}
+	if uid := component.LoginUserId(c); uid > 0 && feedconfig.Current().Enabled {
+		contentAt, _ := c.Get("feed.contentAt")
+		if at, ok := contentAt.(time.Time); ok {
+			ids := []uint64{}
+			for _, item := range items {
+				ids = append(ids, item.ID)
+			}
+			// Pending/private cards added for their author are never signed.
+			public, err := topics.RankTopics(c.Request.Context(), ids)
+			if err == nil {
+				ids = ids[:0]
+				for _, row := range public {
+					ids = append(ids, row.Id)
+				}
+				props.SeenProofs = feedservice.MintSeenProof(uid, ids, at)
+			}
+		}
+	}
+	variant := "unassigned"
+	if v, ok := c.Get("feed.entryVariant"); ok {
+		variant, _ = v.(string)
+	}
+	props.FeedTrace = feedservice.CaptureServeVersion(component.LoginUserId(c), props.Sort, items, variant, "v2", hash, versions...)
+	if props.FeedTrace != "" {
+		positions := map[uint64]int{}
+		for i, item := range items {
+			positions[item.ID] = i
+		}
+		for i := range props.Topics {
+			if pos, ok := positions[props.Topics[i].ID]; ok {
+				p := pos
+				props.Topics[i].FeedTrace = props.FeedTrace
+				props.Topics[i].FeedPosition = &p
+			}
+		}
+	}
+}
+
+func forYouHome(c *gin.Context, page int) {
+	uid := component.LoginUserId(c)
+	if uid == 0 {
+		if isPageRequest(c) {
+			c.JSON(http.StatusUnauthorized, component.FailDataCode(component.MessageAuthRequired, nil))
+		} else {
+			c.Redirect(http.StatusFound, "/login?"+url.Values{"redirect": {"/?sort=for_you"}}.Encode())
+		}
+		return
+	}
+	result, err := feedservice.ForYou(c.Request.Context(), uid, c.Query("cursor"))
+	if errors.Is(err, feedservice.ErrSnapshotExpired) {
+		c.JSON(http.StatusConflict, gin.H{"code": 1, "errorCode": "feed_snapshot_expired", "restartUrl": "/?sort=for_you"})
+		return
+	}
+	if errors.Is(err, feedservice.ErrInvalidCursor) {
+		c.JSON(http.StatusBadRequest, component.FailDataCode(component.MessageRequestInvalidParams, nil))
+		return
+	}
+	degraded := false
+	if err != nil {
+		c.Set("feed.degradeReason", "warming_or_busy")
+		result, err = feedservice.Fallback(c.Request.Context(), uid)
+		degraded = true
+		if err != nil {
+			renderInternalError(c)
+			return
+		}
+	}
+	entities := make([]*topics.Entity, len(result.Topics))
+	for i := range result.Topics {
+		entities[i] = &result.Topics[i]
+	}
+	props := buildHomeProps(c, page, "for_you", transform.Topics2Vo(entities, hotdataserve.CategoryMap()), result.NextCursor != "")
+	if result.NextCursor != "" {
+		props.Pagination.NextURL = "/?" + url.Values{"sort": {"for_you"}, "page": {strconv.Itoa(page + 1)}, "cursor": {result.NextCursor}}.Encode()
+	}
+	if degraded {
+		props.Sort = "latest"
+		props.Pagination.NextURL = "/?sort=latest"
+		props.Pagination.HasNext = false
+	}
+	props.SnapshotID = result.SnapshotID
+	c.Set("feed.contentAt", result.ContentAt)
+	if result.EntryVariant != "" {
+		c.Set("feed.entryVariant", result.EntryVariant)
+	}
+	decorateFeedProps(c, &props, result.Items, result.Hash, result.Config)
+	reasons := map[uint64]string{}
+	for _, i := range result.Items {
+		reasons[i.ID] = i.Reason
+	}
+	for i := range props.Topics {
+		props.Topics[i].FeedReason = reasons[props.Topics[i].ID]
+	}
+	meta := buildHomeMeta(c, page, "for_you", false)
+	meta.Robots = "noindex, nofollow"
+	meta.Canonical = ""
+	meta.PrevURL = ""
+	meta.NextURL = props.Pagination.NextURL
+	renderPage(c, "home.gohtml", PagePayload{Component: PageComponentHome, Props: props, Meta: meta, Layout: buildLayout(c, activeKeyForHome("for_you")), URL: buildPageURL(c), Version: payloadVersion})
+}

diff --git a/apps/gooseforum/app/http/controllers/forum/feed_session.go b/apps/gooseforum/app/http/controllers/forum/feed_session.go
new file mode 100644
index 000000000..ba35be0a2
--- /dev/null
+++ b/apps/gooseforum/app/http/controllers/forum/feed_session.go
@@ -0,0 +1,157 @@
+package forum
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"net/http"
+	"net/url"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/feedconfig"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/http/controllers/component"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/http/controllers/transform"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/hotdataserve"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/feedservice"
+	"github.com/gin-gonic/gin"
+)
+
+type FeedSessionResponse struct {
+	ViewerID      uint64                  `json:"viewerId"`
+	Topics        []TopicPayload          `json:"topics"`
+	RemovedIDs    []uint64                `json:"removedIds"`
+	SeenProofs    []feedservice.SeenProof `json:"seenProofs"`
+	SnapshotID    string                  `json:"snapshotId"`
+	Pagination    *PaginationPayload      `json:"pagination,omitempty"`
+	Available     bool                    `json:"available"`
+	SeenConfirmed bool                    `json:"seenConfirmed"`
+}
+
+func feedSessionCards(ctx context.Context, uid uint64, rows []topics.Entity) []TopicPayload {
+	entities := make([]*topics.Entity, len(rows))
+	for i := range rows {
+		entities[i] = &rows[i]
+	}
+	return buildTrackedTopicPayloadsContext(ctx, uid, transform.Topics2VoContext(ctx, entities, hotdataserve.CategoryMap()))
+}
+func feedSessionFailure(c *gin.Context, err error) {
+	status := http.StatusServiceUnavailable
+	message := component.MessageOperationFailed
+	if errors.Is(err, feedservice.ErrInvalidTrace) || errors.Is(err, feedservice.ErrInvalidCursor) {
+		status = http.StatusBadRequest
+		message = component.MessageRequestInvalidParams
+	}
+	if errors.Is(err, feedservice.ErrRateLimited) {
+		status = http.StatusTooManyRequests
+		c.Header("Retry-After", "5")
+	}
+	c.JSON(status, component.FailDataCode(message, nil))
+}
+
+func FeedRefresh(c *gin.Context) {
+	c.Header("Cache-Control", "private, no-store")
+	c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 32<<10)
+	var req struct {
+		SeenPatches       []feedservice.SeenPatch `json:"seenPatches"`
+		ReplaceSnapshotID string                  `json:"replaceSnapshotId"`
+	}
+	if c.ShouldBindJSON(&req) != nil || len(req.ReplaceSnapshotID) > 128 {
+		feedSessionFailure(c, feedservice.ErrInvalidTrace)
+		return
+	}
+	uid := component.LoginUserId(c)
+	ctx, cancel := context.WithTimeout(c.Request.Context(), 200*time.Millisecond)
+	defer cancel()
+	c.Request = c.Request.WithContext(ctx)
+	if _, err := feedservice.CaptureEvents(ctx, uid, nil, req.SeenPatches); err != nil {
+		feedSessionFailure(c, err)
+		return
+	}
+	var response []byte
+	_, err := feedservice.RefreshForYou(ctx, uid, req.ReplaceSnapshotID, func(page feedservice.Page) error {
+		props := HomeProps{Sort: "for_you", Topics: feedSessionCards(ctx, uid, page.Topics)}
+		c.Set("feed.contentAt", page.ContentAt)
+		c.Set("feed.entryVariant", page.EntryVariant)
+		if err := ctx.Err(); err != nil {
+			return err
+		}
+		decorateFeedProps(c, &props, page.Items, page.Hash, page.Config)
+		for i := range props.Topics {
+			for _, item := range page.Items {
+				if item.ID == props.Topics[i].ID {
+					props.Topics[i].FeedReason = item.Reason
+				}
+			}
+		}
+		pagination := PaginationPayload{Page: 1, NextPage: 2, HasNext: page.NextCursor != ""}
+		if pagination.HasNext {
+			pagination.NextURL = "/?" + url.Values{"sort": {"for_you"}, "page": {"2"}, "cursor": {page.NextCursor}}.Encode()
+		}
+		if props.SeenProofs == nil {
+			props.SeenProofs = []feedservice.SeenProof{}
+		}
+		var err error
+		response, err = json.Marshal(component.SuccessData(FeedSessionResponse{ViewerID: uid, Topics: props.Topics, RemovedIDs: []uint64{}, SeenProofs: props.SeenProofs, SnapshotID: page.SnapshotID, Pagination: &pagination, Available: true, SeenConfirmed: true}))
+		if err != nil {
+			return err
+		}
+		return ctx.Err()
+	})
+	if err != nil {
+		feedSessionFailure(c, err)
+		return
+	}
+	c.Data(http.StatusOK, "application/json; charset=utf-8", response)
+}
+
+func FeedReconcile(c *gin.Context) {
+	c.Header("Cache-Control", "private, no-store")
+	c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 4<<10)
+	var req struct {
+		TopicIDs []uint64 `json:"topicIds"`
+	}
+	if c.ShouldBindJSON(&req) != nil || len(req.TopicIDs) > 120 || len(req.TopicIDs) == 0 {
+		feedSessionFailure(c, feedservice.ErrInvalidCursor)
+		return
+	}
+	unique := map[uint64]bool{}
+	for _, id := range req.TopicIDs {
+		if id == 0 || unique[id] {
+			feedSessionFailure(c, feedservice.ErrInvalidCursor)
+			return
+		}
+		unique[id] = true
+	}
+	uid := component.LoginUserId(c)
+	ctx, cancel := context.WithTimeout(c.Request.Context(), 200*time.Millisecond)
+	defer cancel()
+	c.Request = c.Request.WithContext(ctx)
+	// Reconciliation shares the bounded transport quota without recording a serve.
+	if _, err := feedservice.CaptureEvents(ctx, uid, nil, nil); err != nil {
+		feedSessionFailure(c, err)
+		return
+	}
+	rows, removed, at, err := feedservice.Reconcile(ctx, uid, req.TopicIDs)
+	if err != nil {
+		feedSessionFailure(c, err)
+		return
+	}
+	ids := make([]uint64, 0, len(rows))
+	for _, row := range rows {
+		ids = append(ids, row.Id)
+	}
+	var proofs []feedservice.SeenProof
+	if feedconfig.Current().Enabled {
+		proofs = feedservice.MintSeenProof(uid, ids, at)
+	}
+	if proofs == nil {
+		proofs = []feedservice.SeenProof{}
+	}
+	cards := feedSessionCards(ctx, uid, rows)
+	if ctx.Err() != nil {
+		feedSessionFailure(c, ctx.Err())
+		return
+	}
+	c.JSON(http.StatusOK, component.SuccessData(FeedSessionResponse{ViewerID: uid, Topics: cards, RemovedIDs: removed, SeenProofs: proofs, Available: feedconfig.Current().Enabled && feedconfig.RankReady()}))
+}

