+func preserveOAuthProviders(t *testing.T) {
+	t.Helper()
+	providers := make([]goth.Provider, 0, len(goth.GetProviders()))
+	for _, provider := range goth.GetProviders() {
+		providers = append(providers, provider)
+	}
+	store := gothic.Store
+	goth.ClearProviders()
+	t.Cleanup(func() {
+		goth.ClearProviders()
+		goth.UseProviders(providers...)
+		gothic.Store = store
+	})
+}
