+		t.Fatalf("parse OAuth redirect: %v", err)
+	}
+	if location.Host != "github.com" || location.Path != "/login/oauth/authorize" || location.Query().Get("state") == "" {
+		t.Fatalf("OAuth redirect = %q, want GitHub authorization URL with state", location)
+	}
+}

