@@ -0,0 +1,230 @@
+package agentEvents
+
+import (
+	"fmt"
+	"net/url"
+	"os"
+	"testing"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/agents"
+	"github.com/glebarez/sqlite"
+	"gorm.io/driver/postgres"
+	"gorm.io/gorm"
+)
+
+func schemaCheck(t *testing.T, conn *gorm.DB) {
+	t.Helper()
+	if err := conn.AutoMigrate(&ReplayState{}, &Publication{}, &Intent{}, &Entity{}, &agents.Entity{}); err != nil {
+		t.Fatal(err)
+	}
+	now := time.Now().UTC()
+	e := Entity{ID: "evt_one", InstanceID: "schema", AgentID: 41, Seq: 1, SourceIntentID: "src_one", Type: "agent.mentioned", Reasons: []string{"mention"}, OccurredAt: now, ExpiresAt: now.Add(time.Hour)}
+	if err := conn.Create(&e).Error; err != nil {
+		t.Fatal(err)
+	}
+	dup := e
+	dup.ID = "evt_duplicate"
+	dup.SourceIntentID = "src_other"
+	if err := conn.Create(&dup).Error; err == nil {
+		t.Fatal("duplicate per-Agent seq accepted")
+	}
+	dup.Seq = 2
+	dup.SourceIntentID = e.SourceIntentID
+	if err := conn.Create(&dup).Error; err == nil {
+		t.Fatal("duplicate source Agent accepted")
+	}
+	dup.ID = "evt_other_instance"
+	dup.InstanceID = "other"
+	if err := conn.Create(&dup).Error; err != nil {
+		t.Fatalf("instance namespace not independent %v", err)
+	}
+	intent := Intent{ID: "src_list", InstanceID: "schema", PostID: 3, Version: 1, Recipients: []Recipient{{AgentID: 41, Reasons: []string{"mention"}, SubscriptionGeneration: 1}}, Status: "failed", ExpiresAt: now.Add(time.Hour)}
+	if err := conn.Create(&intent).Error; err != nil {
+		t.Fatal(err)
+	}
+	rows, total, err := PageIntentsForAgentTx(conn, "schema", 41, 1, 10)
+	if err != nil || len(rows) != 1 || total != 1 {
+		t.Fatalf("recipient page %#v %d %v", rows, total, err)
+	}
+	_, total, err = PageIntentsForAgentTx(conn, "schema", 42, 1, 10)
+	if err != nil || total != 0 {
+		t.Fatalf("recipient isolation %d %v", total, err)
+	}
+}
+func TestSchemaNamespaceAndUniqueSQLite(t *testing.T) {
+	conn, err := gorm.Open(sqlite.Open(":memory:"), &gorm.Config{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	schemaCheck(t, conn)
+}
+func pgDB(t *testing.T) *gorm.DB {
+	t.Helper()
+	dsn := os.Getenv("YOURTJ_TEST_PG_URL")
+	if dsn == "" {
+		dsn = os.Getenv("TEST_PG_DSN")
+	}
+	if dsn == "" {
+		t.Skip("PostgreSQL DSN not configured")
+	}
+	admin, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	schema := fmt.Sprintf("agent_events_%d", time.Now().UnixNano())
+	if err := admin.Exec("CREATE SCHEMA " + schema).Error; err != nil {
+		t.Fatal(err)
+	}
+	if parsed, err := url.Parse(dsn); err == nil && (parsed.Scheme == "postgres" || parsed.Scheme == "postgresql") {
+		q := parsed.Query()
+		q.Set("search_path", schema)
+		parsed.RawQuery = q.Encode()
+		dsn = parsed.String()
+	} else {
+		dsn += " search_path=" + schema
+	}
+	conn, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() {
+		sqlDB, _ := conn.DB()
+		_ = sqlDB.Close()
+		_ = admin.Exec("DROP SCHEMA " + schema + " CASCADE").Error
+		adminDB, _ := admin.DB()
+		_ = adminDB.Close()
+	})
+	return conn
+}
+func TestPostgreSQLAgentEventSchemaIsolation(t *testing.T) { schemaCheck(t, pgDB(t)) }
+func TestPostgreSQLEventSequenceHoldsCommitOrder(t *testing.T) {
+	conn := pgDB(t)
+	if err := conn.AutoMigrate(&agents.Entity{}, &Entity{}); err != nil {
+		t.Fatal(err)
+	}
+	agent := agents.Entity{UserId: 51, TokenPrefix: "seq-agent", Enabled: 1}
+	if err := conn.Create(&agent).Error; err != nil {
+		t.Fatal(err)
+	}
+	first := conn.Begin()
+	defer first.Rollback()
+	seq, err := agents.ReserveEventSeqTx(first, agent.UserId)
+	if err != nil || seq != 1 {
+		t.Fatalf("first %d %v", seq, err)
+	}
+	now := time.Now().UTC()
+	one := Entity{ID: "evt_first", InstanceID: "commit-order", AgentID: agent.UserId, Seq: seq, SourceIntentID: "src_first", Reasons: []string{}, OccurredAt: now, ExpiresAt: now.Add(time.Hour)}
+	if err := CreateEventTx(first, &one); err != nil {
+		t.Fatal(err)
+	}
+	started := make(chan struct{})
+	secondReserved := make(chan uint64, 1)
+	done := make(chan error, 1)
+	go func() {
+		done <- conn.Transaction(func(tx *gorm.DB) error {
+			close(started)
+			seq, err := agents.ReserveEventSeqTx(tx, agent.UserId)
+			if err != nil {
+				return err
+			}
+			secondReserved <- seq
+			two := one
+			two.ID = "evt_second"
+			two.SourceIntentID = "src_second"
+			two.Seq = seq
+			return CreateEventTx(tx, &two)
+		})
+	}()
+	<-started
+	select {
+	case seq := <-secondReserved:
+		t.Fatalf("later commit allocated %d before first commit", seq)
+	case <-time.After(100 * time.Millisecond):
+	}
+	rows, err := ListTx(conn, "commit-order", agent.UserId, 0, 10)
+	if err != nil || len(rows) != 0 {
+		t.Fatalf("uncommitted source visible %#v %v", rows, err)
+	}
+	if err := first.Commit().Error; err != nil {
+		t.Fatal(err)
+	}
+	select {
+	case err := <-done:
+		if err != nil {
+			t.Fatal(err)
+		}
+	case <-time.After(5 * time.Second):
+		t.Fatal("second writer stuck")
+	}
+	rows, err = ListTx(conn, "commit-order", agent.UserId, 0, 10)
+	if err != nil || len(rows) != 2 || rows[0].Seq != 1 || rows[1].Seq != 2 {
+		t.Fatalf("committed stream %#v %v", rows, err)
+	}
+}
+
+func TestExpiredIntentCleanupDoesNotCollide(t *testing.T) {
+	conn, err := gorm.Open(sqlite.Open(":memory:"), &gorm.Config{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := conn.AutoMigrate(&Intent{}); err != nil {
+		t.Fatal(err)
+	}
+	now := time.Now()
+	for index := 1; index <= 2; index++ {
+		row := Intent{ID: fmt.Sprintf("expired-%d", index), InstanceID: "expiry", PostID: uint64(index), Version: 1, Recipients: []Recipient{}, ExpiresAt: now.Add(-time.Hour)}
+		if err := conn.Create(&row).Error; err != nil {
+			t.Fatal(err)
+		}
+	}
+	if err := ExpireIntentsTx(conn, "expiry", now, 500); err != nil {
+		t.Fatalf("cleanup failed for multiple expired source occurrences: %v", err)
+	}
+	var count int64
+	if err := conn.Model(&Intent{}).Where("status = ?", "expired").Count(&count).Error; err != nil || count != 2 {
+		t.Fatalf("expired count %d, %v", count, err)
+	}
+}
+
+func TestPurgedDiagnosticsKeepNamespacedReplayFloor(t *testing.T) {
+	conn, err := gorm.Open(sqlite.Open(":memory:"), &gorm.Config{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	if err := conn.AutoMigrate(&Entity{}, &Intent{}, &ReplayState{}); err != nil {
+		t.Fatal(err)
+	}
+	now := time.Now()
+	for seq := uint64(1); seq <= 2; seq++ {
+		expiry := now.Add(-40 * 24 * time.Hour)
+		if seq == 1 {
+			expiry = now.Add(time.Hour)
+		}
+		e := Entity{ID: fmt.Sprintf("floor-%d", seq), InstanceID: "floor", AgentID: 1, Seq: seq, SourceIntentID: fmt.Sprintf("src-%d", seq), Reasons: []string{}, OccurredAt: now, ExpiresAt: expiry}
+		if err := conn.Create(&e).Error; err != nil {
+			t.Fatal(err)
+		}
+	}
+	if err := conn.Transaction(func(tx *gorm.DB) error { return PurgeMetadataTx(tx, "floor", now.Add(-30*24*time.Hour), 500) }); err != nil {
+		t.Fatal(err)
+	}
+	floor, err := ReplayFloorTx(conn, "floor", 1, now)
+	if err != nil || floor != 0 {
+		t.Fatalf("purged higher sequence skipped retained earlier event: %d %v", floor, err)
+	}
+	if err := conn.Model(&Entity{}).Where("id = ?", "floor-1").Update("expires_at", now.Add(-40*24*time.Hour)).Error; err != nil {
+		t.Fatal(err)
+	}
+	if err := conn.Transaction(func(tx *gorm.DB) error { return PurgeMetadataTx(tx, "floor", now.Add(-30*24*time.Hour), 500) }); err != nil {
+		t.Fatal(err)
+	}
+	floor, err = ReplayFloorTx(conn, "floor", 1, now)
+	if err != nil || floor != 2 {
+		t.Fatalf("purged floor went backwards: %d %v", floor, err)
+	}
+	foreign, err := ReplayFloorTx(conn, "other", 1, now)
+	if err != nil || foreign != 0 {
+		t.Fatalf("foreign instance floor leaked: %d %v", foreign, err)
+	}
+}

diff --git a/apps/gooseforum/app/models/forum/agentWebhook/delivery.go b/apps/gooseforum/app/models/forum/agentWebhook/delivery.go
new file mode 100644
index 000000000..d371358ab
--- /dev/null
+++ b/apps/gooseforum/app/models/forum/agentWebhook/delivery.go
@@ -0,0 +1,170 @@
+package agentWebhook
+
+import (
+	"gorm.io/gorm"
+	"gorm.io/gorm/clause"
+	"time"
+)
+
+const (
+	Pending   = "pending"
+	Running   = "running"
+	Accepted  = "accepted"
+	RetryWait = "retry_wait"
+	Dead      = "dead"
+	Cancelled = "cancelled"
+)
+
+type Delivery struct {
+	ID                 uint64     `gorm:"primaryKey;autoIncrement" json:"id"`
+	InstanceID         string     `gorm:"type:varchar(128);not null;uniqueIndex:uniq_agent_delivery,priority:1;index:idx_agent_delivery_list,priority:1" json:"instanceId"`
+	EventID            string     `gorm:"type:varchar(96);not null;uniqueIndex:uniq_agent_delivery,priority:2" json:"eventId"`
+	AgentID            uint64     `gorm:"not null;index:idx_agent_delivery_list,priority:2" json:"agentId"`
+	EndpointGeneration uint64     `gorm:"not null;uniqueIndex:uniq_agent_delivery,priority:3" json:"endpointGeneration"`
+	SchemaVersion      uint32     `gorm:"not null;default:1" json:"schemaVersion"`
+	Status             string     `gorm:"type:varchar(16);not null;default:'pending';index" json:"status"`
+	Reason             string     `gorm:"type:varchar(64);not null;default:''" json:"reason"`
+	TaskID             uint64     `gorm:"not null;default:0" json:"taskId"`
+	Body               string     `gorm:"type:text;not null" json:"-"`
+	Round              uint32     `gorm:"not null;default:1" json:"round"`
+	AttemptCount       uint32     `gorm:"not null;default:0" json:"attemptCount"`
+	TotalAttempts      uint32     `gorm:"not null;default:0" json:"totalAttempts"`
+	Deadline           time.Time  `gorm:"not null" json:"deadline"`
+	ExpiresAt          time.Time  `gorm:"not null;index" json:"expiresAt"`
+	NextRunAt          *time.Time `json:"nextRunAt"`
+	PermitExpiresAt    *time.Time `json:"-"`
+	LastAttemptID      string     `gorm:"type:varchar(36);not null;default:''" json:"-"`
+	CreatedBy          uint64     `gorm:"not null;default:0" json:"createdBy"`
+	LastRedeliveredBy  uint64     `gorm:"not null;default:0" json:"lastRedeliveredBy"`
+	AcceptedAt         *time.Time `json:"acceptedAt"`
+	CreatedAt          time.Time  `gorm:"autoCreateTime;index" json:"createdAt"`
+	UpdatedAt          time.Time  `gorm:"autoUpdateTime" json:"updatedAt"`
+}
+
+func (*Delivery) TableName() string { return "agent_webhook_deliveries" }
+
+type Attempt struct {
+	ID           string     `gorm:"primaryKey;type:varchar(36)" json:"id"`
+	InstanceID   string     `gorm:"type:varchar(128);not null;index:idx_agent_attempt,priority:1" json:"instanceId"`
+	DeliveryID   uint64     `gorm:"not null;index:idx_agent_attempt,priority:2" json:"deliveryId"`
+	Round        uint32     `gorm:"not null" json:"round"`
+	Number       uint32     `gorm:"not null" json:"number"`
+	HTTPStatus   int        `gorm:"not null;default:0" json:"httpStatus"`
+	ErrorClass   string     `gorm:"type:varchar(64);not null;default:''" json:"errorClass"`
+	DurationMS   int64      `gorm:"not null;default:0" json:"durationMs"`
+	AuthorizedAt time.Time  `gorm:"not null" json:"authorizedAt"`
+	CompletedAt  *time.Time `json:"completedAt"`
+}
+
+func (*Attempt) TableName() string { return "agent_webhook_attempts" }
+func CreateTx(tx *gorm.DB, row *Delivery) (bool, error) {
+	r := tx.Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "instance_id"}, {Name: "event_id"}, {Name: "endpoint_generation"}}, DoNothing: true}).Create(row)
+	return r.RowsAffected == 1, r.Error
+}
+func GetTx(tx *gorm.DB, instanceID string, id uint64, lock bool) (*Delivery, error) {
+	var row Delivery
+	q := tx.Where("instance_id = ? AND id = ?", instanceID, id)
+	if lock {
+		q = q.Clauses(clause.Locking{Strength: "UPDATE"})
+	}
+	err := q.First(&row).Error
+	return &row, err
+}
+func UpdateTx(tx *gorm.DB, instanceID string, id uint64, values map[string]any) error {
+	return tx.Model(&Delivery{}).Where("instance_id = ? AND id = ?", instanceID, id).Updates(values).Error
+}
+func AddAttemptTx(tx *gorm.DB, row *Attempt) error { return tx.Create(row).Error }
+func CompleteAttemptTx(tx *gorm.DB, instanceID, id string, values map[string]any) error {
+	return tx.Model(&Attempt{}).Where("instance_id = ? AND id = ?", instanceID, id).Updates(values).Error
+}
+func ListTx(tx *gorm.DB, instanceID string, agentID uint64, offset, limit int) ([]Delivery, int64, error) {
+	var rows []Delivery
+	var n int64
+	q := tx.Model(&Delivery{}).Where("instance_id = ? AND agent_id = ?", instanceID, agentID)
+	if err := q.Count(&n).Error; err != nil {
+		return nil, 0, err
+	}
+	err := q.Order("id desc").Offset(offset).Limit(limit).Find(&rows).Error
+	return rows, n, err
+}
+func AttemptsTx(tx *gorm.DB, instanceID string, id uint64) ([]Attempt, error) {
+	var rows []Attempt
+	err := tx.Where("instance_id = ? AND delivery_id = ?", instanceID, id).Order("authorized_at asc").Limit(100).Find(&rows).Error
+	return rows, err
+}
+func CancelGenerationTx(tx *gorm.DB, instanceID string, agentID, generation uint64, reason string) error {
+	return tx.Model(&Delivery{}).Where("instance_id = ? AND agent_id = ? AND endpoint_generation <> ? AND status IN ?", instanceID, agentID, generation, []string{Pending, RetryWait}).Updates(map[string]any{"status": Cancelled, "reason": reason, "body": ""}).Error
+}
+
+// RedactBySourceEventsTx removes all retained payload copies, including accepted deliveries.
+func RedactBySourceEventsTx(tx *gorm.DB, instanceID string, eventIDs []string) error {
+	return redactBySourceEventsTx(tx, instanceID, eventIDs, "withdrawn")
+}
+
+// RedactExpiredSourceEventsTx preserves retention's diagnostic reason even
+// when an already authorized send completes after the retained copy is erased.
+func RedactExpiredSourceEventsTx(tx *gorm.DB, instanceID string, eventIDs []string) error {
+	return redactBySourceEventsTx(tx, instanceID, eventIDs, "expired")
+}
+
+func redactBySourceEventsTx(tx *gorm.DB, instanceID string, eventIDs []string, reason string) error {
+	if len(eventIDs) == 0 {
+		return nil
+	}
+	q := tx.Model(&Delivery{}).Where("instance_id = ? AND event_id IN ?", instanceID, eventIDs)
+	if err := q.Updates(map[string]any{"reason": reason, "body": ""}).Error; err != nil {
+		return err
+	}
+	return tx.Model(&Delivery{}).Where("instance_id = ? AND event_id IN ? AND status IN ?", instanceID, eventIDs, []string{Pending, RetryWait, Dead}).Update("status", Cancelled).Error
+}
+func TasksForEventsTx(tx *gorm.DB, instanceID string, eventIDs []string) ([]uint64, error) {
+	var ids []uint64
+	if len(eventIDs) == 0 {
+		return ids, nil
+	}
+	err := tx.Model(&Delivery{}).Where("instance_id = ? AND event_id IN ?", instanceID, eventIDs).Pluck("task_id", &ids).Error
+	return ids, err
+}
+
+func ExpireTx(tx *gorm.DB, instanceID string, now time.Time) error {
+	var ids []uint64
+	if err := tx.Model(&Delivery{}).Where("instance_id = ? AND expires_at <= ? AND body <> ''", instanceID, now).Order("id asc").Limit(500).Pluck("id", &ids).Error; err != nil {
+		return err
+	}
+	if len(ids) == 0 {
+		return nil
+	}
+	return tx.Model(&Delivery{}).Where("instance_id = ? AND id IN ?", instanceID, ids).Updates(map[string]any{"status": Cancelled, "reason": "expired", "body": ""}).Error
+}
+
+func PendingCountTx(tx *gorm.DB, instanceID string, agentID uint64) (int64, error) {
+	var n int64
+	err := tx.Model(&Delivery{}).Where("instance_id = ? AND agent_id = ? AND status IN ?", instanceID, agentID, []string{Pending, Running, RetryWait}).Count(&n).Error
+	return n, err
+}
+func PurgeAttemptsTx(tx *gorm.DB, instanceID string, before time.Time, batch int) error {
+	var ids []string
+	if err := tx.Model(&Attempt{}).Where("instance_id = ? AND authorized_at < ?", instanceID, before).Order("authorized_at asc").Limit(batch).Pluck("id", &ids).Error; err != nil {
+		return err
+	}
+	if len(ids) == 0 {
+		return nil
+	}
+	return tx.Where("instance_id = ? AND id IN ?", instanceID, ids).Delete(&Attempt{}).Error
+}
+
+// PurgeMetadataTx bounds retained delivery diagnostics after their expiry.
+// Running permits remain fenced until their own completion/recovery.
+func PurgeMetadataTx(tx *gorm.DB, instanceID string, before time.Time, batch int) error {
+	var ids []uint64
+	if err := tx.Model(&Delivery{}).Where("instance_id = ? AND expires_at < ? AND body = '' AND status <> ?", instanceID, before, Running).Order("id ASC").Limit(batch).Pluck("id", &ids).Error; err != nil {
+		return err
+	}
+	if len(ids) == 0 {
+		return nil
+	}
+	if err := tx.Where("instance_id = ? AND delivery_id IN ?", instanceID, ids).Delete(&Attempt{}).Error; err != nil {
+		return err
+	}
+	return tx.Where("instance_id = ? AND id IN ?", instanceID, ids).Delete(&Delivery{}).Error
+}

diff --git a/apps/gooseforum/app/models/forum/agentWrites/agent_writes.go b/apps/gooseforum/app/models/forum/agentWrites/agent_writes.go
new file mode 100644
index 000000000..6bb40c205
--- /dev/null
+++ b/apps/gooseforum/app/models/forum/agentWrites/agent_writes.go
@@ -0,0 +1,98 @@
+// Package agentWrites owns transactional Agent creation deduplication. It stores
+// resource references rather than rendered content, so retries use live visibility.
+package agentWrites
+
+import (
+	"errors"
+	"time"
+
+	"gorm.io/gorm"
+	"gorm.io/gorm/clause"
+)
+
+var ErrConflict = errors.New("agent write idempotency conflict")
+var ErrIncomplete = errors.New("agent write result unavailable")
+
+type Entry struct {
+	ID            uint64    `gorm:"primaryKey;autoIncrement" json:"-"`
+	InstanceID    string    `gorm:"size:128;not null;uniqueIndex:uniq_agent_write,priority:1;check:chk_agent_write_instance,instance_id <> ''" json:"-"`
+	AgentID       uint64    `gorm:"not null;uniqueIndex:uniq_agent_write,priority:2" json:"-"`
+	Operation     string    `gorm:"size:32;not null;uniqueIndex:uniq_agent_write,priority:3" json:"-"`
+	TargetID      uint64    `gorm:"not null;uniqueIndex:uniq_agent_write,priority:4" json:"-"`
+	RequestKey    string    `gorm:"size:256;not null;uniqueIndex:uniq_agent_write,priority:5;check:chk_agent_write_key,request_key <> ''" json:"-"`
+	Digest        string    `gorm:"size:64;not null;check:chk_agent_write_digest,digest <> ''" json:"-"`
+	SourceEventID string    `gorm:"size:80;not null;default:'';index" json:"-"`
+	TopicID       uint64    `gorm:"not null;default:0" json:"-"`
+	PostID        uint64    `gorm:"not null;default:0" json:"-"`
+	CreatedAt     time.Time `gorm:"not null;autoCreateTime" json:"-"`
+	ExpiresAt     time.Time `gorm:"not null;index" json:"-"`
+}
+
+func (Entry) TableName() string { return "agent_write_idempotency" }
+
+func scope(tx *gorm.DB, e Entry) *gorm.DB {
+	return tx.Where("instance_id = ? AND agent_id = ? AND operation = ? AND target_id = ? AND request_key = ?", e.InstanceID, e.AgentID, e.Operation, e.TargetID, e.RequestKey)
+}
+
+func LookupTx(tx *gorm.DB, e Entry, now time.Time) (*Entry, error) {
+	var found Entry
+	err := scope(tx, e).Where("expires_at > ?", now).Take(&found).Error
+	if errors.Is(err, gorm.ErrRecordNotFound) {
+		return nil, nil
+	}
+	if err != nil {
+		return nil, err
+	}
+	if found.Digest != e.Digest {
+		return nil, ErrConflict
+	}
+	if found.TopicID == 0 || found.PostID == 0 {
+		return nil, ErrIncomplete
+	}
+	return &found, nil
+}
+
+// ReserveTx waits on the unique constraint for an in-flight creator. The winner
+// reserves, writes content and completes the reference in this same transaction;
+// rollback releases the key. A committed reservation is never left incomplete.
+func ReserveTx(tx *gorm.DB, e *Entry, now time.Time) (replay *Entry, err error) {
+	if err = scope(tx, *e).Where("expires_at <= ?", now).Delete(&Entry{}).Error; err != nil {
+		return nil, err
+	}
+	result := tx.Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "instance_id"}, {Name: "agent_id"}, {Name: "operation"}, {Name: "target_id"}, {Name: "request_key"}}, DoNothing: true}).Create(e)
+	if result.Error != nil {
+		return nil, result.Error
+	}
+	if result.RowsAffected == 1 {
+		return nil, nil
+	}
+	return LookupTx(tx, *e, now)
+}
+
+func CompleteTx(tx *gorm.DB, e *Entry, topicID, postID uint64) error {
+	if e == nil {
+		return nil
+	}
+	result := tx.Model(&Entry{}).Where("id = ? AND instance_id = ? AND topic_id = 0 AND post_id = 0", e.ID, e.InstanceID).Updates(map[string]any{"topic_id": topicID, "post_id": postID})
+	if result.Error != nil {
+		return result.Error
+	}
+	if result.RowsAffected != 1 {
+		return ErrIncomplete
+	}
+	return nil
+}
+
+func PurgeExpiredTx(tx *gorm.DB, instanceID string, now time.Time, limit int) error {
+	var ids []uint64
+	if limit < 1 || limit > 500 {
+		limit = 500
+	}
+	if err := tx.Model(&Entry{}).Where("instance_id = ? AND expires_at <= ?", instanceID, now).Order("id").Limit(limit).Pluck("id", &ids).Error; err != nil {
+		return err
+	}
+	if len(ids) == 0 {
+		return nil
+	}
+	return tx.Where("instance_id = ? AND id IN ?", instanceID, ids).Delete(&Entry{}).Error
+}

diff --git a/apps/gooseforum/app/models/forum/agentWrites/agent_writes_pg_test.go b/apps/gooseforum/app/models/forum/agentWrites/agent_writes_pg_test.go
