+		t.Fatalf("human ranking total = %+v, want one account with estimated=true", human)
+	}
+	agent, err := userRankingTotal(conn, scope, users.ActorTypeBot)
+	if err != nil {
+		t.Fatalf("agent ranking total: %v", err)
