+	post := posts.Entity{Id: 902, TopicId: 901, PostNo: 1, UserId: 900, Content: "public source"}
+	topic := topics.Entity{Id: post.TopicId, UserId: post.UserId, FirstPostId: post.Id, Status: 1}
