+
+func testPostgreSQLBroadcastWriters(t *testing.T, linked bool) {
+	dsn := os.Getenv("YOURTJ_TEST_PG_URL")
+	if dsn == "" {
+		t.Skip("PostgreSQL DSN not configured")
+	}
+	admin, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
+	if err != nil {
