+	"github.com/glebarez/sqlite"
+	"gorm.io/gorm"
+)
+
+func writeFixture(t *testing.T) (*gorm.DB, context.Context) {
+	t.Helper()
+	t.Setenv("YOURTJ_AGENT_INSTANCE_ID", "write-policy")
+	t.Setenv("YOURTJ_AGENT_STREAM_EPOCH", "epoch")
+	t.Setenv("YOURTJ_AGENT_API_ENABLED", "true")
+	t.Setenv("YOURTJ_AGENT_PRODUCER_ENABLED", "true")
+	conn, err := gorm.Open(sqlite.Open(fmt.Sprintf("file:%s?mode=memory&cache=shared", t.Name())), &gorm.Config{})
+	if err != nil {
+		t.Fatal(err)
+	}
+	pool, _ := conn.DB()
+	pool.SetMaxOpenConns(1)
+	t.Cleanup(func() { _ = pool.Close() })
+	if err := conn.AutoMigrate(&users.EntityComplete{}, &users.BlockEntity{}, &agents.Entity{}, &topics.Entity{}, &posts.Entity{}, &agentWrites.Entry{}, &agentEvents.Entity{}, &pageConfig.Entity{}); err != nil {
+		t.Fatal(err)
+	}
+	for _, row := range []any{
+		&users.EntityComplete{Id: 1, Username: "policybot", ActorType: users.ActorTypeBot},
+		&agents.Entity{UserId: 1, TokenPrefix: "policy", TokenHash: "hash", Enabled: agents.StatusEnabled},
+		&topics.Entity{Id: 10, UserId: 1, Status: 1},
+	} {
+		if err := conn.Create(row).Error; err != nil {
+			t.Fatal(err)
+		}
+	}
+	return conn, WithOptions(context.Background(), Options{Operation: "post", TargetID: 10, Key: "reply", Digest: "one", CredentialHash: "hash"})
+}
+
+func TestBeginTxRechecksCommentPolicyAfterPreflight(t *testing.T) {
+	for _, scope := range []string{"topic", "global"} {
+		t.Run(scope, func(t *testing.T) {
+			conn, ctx := writeFixture(t)
+			// A request has passed controller preflight; an administrator commits a ban
+			// while moderation is still in flight, before the content transaction begins.
+			if scope == "topic" {
+				if err := conn.Model(&topics.Entity{}).Where("id = ?", 10).Update("agent_comment_disabled", true).Error; err != nil {
+					t.Fatal(err)
+				}
+			} else {
+				if err := conn.Create(&pageConfig.Entity{PageType: pageConfig.AgentCommentPolicy, Config: `{"allowAgentComments":false}`}).Error; err != nil {
+					t.Fatal(err)
+				}
+			}
+			err := conn.Transaction(func(tx *gorm.DB) error { _, _, err := BeginTx(ctx, tx, 1); return err })
+			if !errors.Is(err, agentcommentservice.ErrAgentCommentDisabled) {
+				t.Fatalf("new write after %s policy ban: %v", scope, err)
+			}
+			var count int64
+			conn.Model(&agentWrites.Entry{}).Count(&count)
+			if count != 0 {
+				t.Fatal("refused write consumed its idempotency key")
+			}
+		})
+	}
+}
+
+func TestCommittedReplayIgnoresLaterCommentBan(t *testing.T) {
+	conn, ctx := writeFixture(t)
+	if err := conn.Transaction(func(tx *gorm.DB) error {
+		reservation, _, err := BeginTx(ctx, tx, 1)
+		if err != nil {
+			return err
+		}
+		return agentWrites.CompleteTx(tx, reservation.Entry, 10, 20)
+	}); err != nil {
+		t.Fatal(err)
+	}
+	if err := conn.Model(&topics.Entity{}).Where("id = 10").Update("agent_comment_disabled", true).Error; err != nil {
+		t.Fatal(err)
+	}
+	if err := conn.Transaction(func(tx *gorm.DB) error {
+		_, replay, err := BeginTx(ctx, tx, 1)
+		if !errors.Is(err, ErrReplay) || replay == nil || replay.PostID != 20 {
+			return fmt.Errorf("committed replay changed: %#v %w", replay, err)
+		}
+		return nil
+	}); err != nil {
+		t.Fatal(err)
+	}
+}
+
+func TestFinishTxPreservesEachPendingReplyDepth(t *testing.T) {
+	conn, _ := writeFixture(t)
+	now := time.Now().Add(-time.Minute)
+	if err := conn.Model(&agents.Entity{}).Where("user_id = 1").Updates(map[string]any{"events_enabled": true, "events_enabled_at": now, "subscription_generation": 1}).Error; err != nil {
+		t.Fatal(err)
+	}
+	for _, row := range []any{
+		&users.EntityComplete{Id: 2, Username: "sourcebot", ActorType: users.ActorTypeBot},
+		&posts.Entity{Id: 100, TopicId: 10, PostNo: 1, UserId: 2, Content: "source", AgentEventDepth: 3},
+		&agentEvents.Entity{ID: "source", InstanceID: "write-policy", AgentID: 1, Seq: 1, SourceIntentID: "intent", SubscriptionGeneration: 1, Type: "forum.topic_created", TopicID: 10, PostID: 100, PostNo: 1, ActorID: 2, ActorType: "bot", Reasons: []string{"topic_created"}, ExpiresAt: time.Now().Add(time.Hour)},
+	} {
+		if err := conn.Create(row).Error; err != nil {
+			t.Fatal(err)
+		}
+	}
+	for n := uint64(2); n <= 3; n++ {
+		ctx := WithOptions(context.Background(), Options{Operation: "post", TargetID: 10, Key: fmt.Sprintf("reply%d", n), Digest: "one", CredentialHash: "hash", SourceEventID: "source"})
+		err := conn.Transaction(func(tx *gorm.DB) error {
+			reservation, _, err := BeginTx(ctx, tx, 1)
+			if err != nil {
+				return err
+			}
+			p := posts.Entity{Id: 100 + n, TopicId: 10, PostNo: n, UserId: 1, Content: "pending reply", ProcessStatus: posts.ProcessStatusPending}
+			if err := tx.Create(&p).Error; err != nil {
+				return err
+			}
+			return FinishTx(ctx, tx, 1, reservation, 10, p.Id)
+		})
+		if err != nil {
+			t.Fatal(err)
+		}
+	}
+	var reply posts.Entity
+	if err := conn.First(&reply, 102).Error; err != nil {
+		t.Fatal(err)
+	}
+	if reply.AgentEventDepth != 4 {
+		t.Fatalf("first pending reply lost depth after second response: %d", reply.AgentEventDepth)
+	}
+	var event agentEvents.Entity
+	if err := conn.Where("id = ?", "source").Take(&event).Error; err != nil {
+		t.Fatal(err)
+	}
+	if event.ResultingPostID != 103 {
+		t.Fatalf("latest result not replaced: %#v", event)
+	}
+}

diff --git a/apps/gooseforum/app/service/anonymousidentityservice/admin.go b/apps/gooseforum/app/service/anonymousidentityservice/admin.go
new file mode 100644
index 000000000..06f235bc8
--- /dev/null
+++ b/apps/gooseforum/app/service/anonymousidentityservice/admin.go
@@ -0,0 +1,158 @@
+package anonymousidentityservice
+
+import (
+	"strings"
+	"time"
+
+	identity "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/anonymousIdentity"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/rolePermissionRs"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/users"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/permission"
+	"gorm.io/gorm"
+)
+
+type AdminListQuery struct {
+	Page     int    `json:"page" validate:"min=1,max=100000"`
+	PageSize int    `json:"pageSize" validate:"min=1,max=50"`
+	Search   string `json:"search" validate:"max=128"`
+	Status   string `json:"status" validate:"oneof=all active disabled banned"`
+	Reason   string `json:"reason" validate:"required,max=512"`
+}
+
+type AdminOwner struct {
+	UserID   uint64 `json:"userId"`
+	Username string `json:"username"`
+	Closed   bool   `json:"closed"`
+	Frozen   bool   `json:"frozen"`
+}
+
+type AdminIdentity struct {
+	PublicPersona
+	Owner              AdminOwner `json:"owner"`
+	Disabled           bool       `json:"disabled"`
+	GovernanceDisabled bool       `json:"governanceDisabled"`
+	SelectedAt         time.Time  `json:"selectedAt"`
+}
+
+type AdminList struct {
+	Items    []AdminIdentity `json:"items"`
+	Total    int64           `json:"total"`
+	Page     int             `json:"page"`
+	PageSize int             `json:"pageSize"`
+}
+
+// Both capabilities are read from the current role inside the transaction.
+// Admin's wildcard never substitutes for the explicit private-binding grant.
+func authorizeAdminTx(tx *gorm.DB, actor uint64) error {
+	current, err := users.LockAnonymousOwnerTx(tx, actor)
+	if err != nil {
+		return err
+	}
+	for _, capability := range []permission.Enum{permission.RevealAnonymousIdentity, permission.UserManager} {
+		allowed, err := rolePermissionRs.HasExplicitTx(tx, current.RoleId, capability.Id())
+		if err != nil {
+			return err
+		}
+		if !allowed && capability == permission.UserManager {
+			allowed, err = rolePermissionRs.HasExplicitTx(tx, current.RoleId, permission.Admin.Id())
+			if err != nil {
+				return err
+			}
+		}
+		if !allowed {
+			return ErrUnavailable
+		}
+	}
+	return nil
+}
+
+// ListAdmin releases each page of private mappings only after its restricted
+// audit commits. Closed owners remain available for historical governance.
+func (s Service) ListAdmin(actor uint64, q AdminListQuery) (AdminList, error) {
+	if !ValidateReason(q.Reason) || q.Page < 1 || q.Page > 100000 || q.PageSize < 1 || q.PageSize > 50 || len([]rune(q.Search)) > 128 {
+		return AdminList{}, ErrUnavailable
+	}
+	if q.Status != "all" && q.Status != "active" && q.Status != "disabled" && q.Status != "banned" {
+		return AdminList{}, ErrUnavailable
+	}
+	trace, err := randomID()
+	if err != nil {
+		return AdminList{}, err
+	}
+	result := AdminList{Items: []AdminIdentity{}, Page: q.Page, PageSize: q.PageSize}
+	err = s.DB.Transaction(func(tx *gorm.DB) error {
+		if err := authorizeAdminTx(tx, actor); err != nil {
+			return err
+		}
+		query := tx.Table("anonymous_personas AS p").Joins("JOIN anonymous_bindings AS b ON b.persona_uid = p.uid").Joins("JOIN users AS u ON u.id = b.owner_id")
+		if search := strings.TrimSpace(q.Search); search != "" {
+			like := "%" + strings.ToLower(search) + "%"
+			query = query.Where("LOWER(p.name) LIKE ? OR LOWER(p.uid) LIKE ? OR LOWER(u.username) LIKE ? OR CAST(u.id AS TEXT) = ?", like, like, like, search)
+		}
+		switch q.Status {
+		case "active":
+			query = query.Where("p.disabled = ? AND p.governance_disabled = ?", false, false)
+		case "disabled":
+			query = query.Where("p.disabled = ? AND p.governance_disabled = ?", true, false)
+		case "banned":
+			query = query.Where("p.governance_disabled = ?", true)
+		}
+		if err := query.Count(&result.Total).Error; err != nil {
+			return err
+		}
+		var rows []struct {
+			UID, Name, Username          string
+			OwnerID                      uint64
+			Disabled, GovernanceDisabled bool
+			NameSelectedAt               time.Time
+			DeletedAt                    gorm.DeletedAt
+			IsFrozen                     int8
+		}
+		if err := query.Select("p.uid, p.name, p.disabled, p.governance_disabled, p.name_selected_at, b.owner_id, u.username, u.deleted_at, u.is_frozen").Order("p.name_selected_at DESC, p.uid ASC").Limit(q.PageSize).Offset((q.Page - 1) * q.PageSize).Scan(&rows).Error; err != nil {
+			return err
+		}
+		audits := make([]identity.RevealAudit, 0, len(rows))
+		for _, row := range rows {
+			result.Items = append(result.Items, AdminIdentity{
+				PublicPersona: Public(identity.Persona{UID: row.UID, Name: row.Name}),
+				Owner:         AdminOwner{UserID: row.OwnerID, Username: row.Username, Closed: row.DeletedAt.Valid, Frozen: row.IsFrozen != users.StatusNormal},
+				Disabled:      row.Disabled, GovernanceDisabled: row.GovernanceDisabled, SelectedAt: row.NameSelectedAt,
+			})
+			audits = append(audits, identity.RevealAudit{Action: "admin.list", ActorID: actor, PersonaUID: row.UID, OwnerID: row.OwnerID, Reason: strings.TrimSpace(q.Reason), TraceID: trace, CreatedAt: s.Now()})
+		}
+		if len(audits) == 0 {
+			audits = append(audits, identity.RevealAudit{Action: "admin.list", ActorID: actor, Reason: strings.TrimSpace(q.Reason), TraceID: trace, CreatedAt: s.Now()})
+		}
+		return tx.Create(&audits).Error
+	})
+	if err != nil {
+		return AdminList{}, err
+	}
+	return result, nil
+}
+
+// GovernAdmin allows governance without an existing post, with the same audit
+// and owner-wide publishing restriction as scoped moderation.
+func (s Service) GovernAdmin(actor uint64, uid, reason string, disabled bool) (uint64, error) {
+	if !ValidateReason(reason) || !ValidatePublicUID(uid) {
+		return 0, ErrUnavailable
+	}
+	var binding identity.Binding
+	err := s.DB.Transaction(func(tx *gorm.DB) error {
+		if err := authorizeAdminTx(tx, actor); err != nil {
+			return err
+		}
+		if err := tx.First(&binding, "persona_uid = ?", uid).Error; err != nil {
+			return err
+		}
+		trace, err := randomID()
+		if err != nil {
+			return err
+		}
+		return governTx(tx, actor, uid, reason, disabled, trace, s.Now)
+	})
+	if err != nil {
+		return 0, err
+	}
+	return binding.OwnerID, nil
+}

diff --git a/apps/gooseforum/app/service/anonymousidentityservice/admin_test.go b/apps/gooseforum/app/service/anonymousidentityservice/admin_test.go
