+func TestSchoolRegistrationUsernameCollisionOnPostgreSQL(t *testing.T) {
+	conn := loginPostgres(t)
+	s := New(Config{EncryptionKey: strings.Repeat("e", 32), IdentityKey: strings.Repeat("i", 32)}, campus.Store{DB: conn}, nil)
