+		if err := conn.Create(&users.EntityComplete{Id: id, Username: fmt.Sprintf("forward-push-%d", id)}).Error; err != nil {
+			t.Fatal(err)
+		}
+	}
+	preferences.Set("push.jpush.app_key", "test")
+	preferences.Set("push.jpush.master_secret", "test")
