+		t.Fatal("expected failing outer forward transaction")
+	}
+	conn.Model(&taskQueue.Entity{}).Where("type LIKE ?", "nativepush.%").Count(&count)
+	if count != 3 {
+		t.Fatalf("rollback leaked tasks: %d", count)
+	}
+}

