+	if id == 0 {
+		return
+	}
+	courseDetailCache.Delete(strconv.FormatUint(id, 10))
+	c := course.GetCourse(id)
+	if c.TeamKey != "" {
+		InvalidateCourseTeamCache(c.TeamKey)
+	}
