+func ContentType(filename string) (string, bool) {
+	switch strings.ToLower(path.Ext(filename)) {
+	case ".svg":
+		return "image/svg+xml", true
+	case ".png", ".webp", ".gif":
+		return imagepolicy.ContentTypeForFilename(filename)
+	default:
