+	contentType, ok := ContentType(filename)
+	if !ok || len(data) == 0 || len(data) > MaxArtworkBytes {
+		return nil, "", ErrInvalid
+	}
+	if contentType == "image/svg+xml" {
+		rendered, err := renderSVG(ctx, data, frame)
+		if err != nil {
+			return nil, "", err
+		}
+		if len(rendered) > MaxArtworkBytes {
+			return nil, "", ErrInvalid
+		}
+		data = rendered
+		filename = strings.TrimSuffix(filename, path.Ext(filename)) + ".png"
+		contentType = "image/png"
+	}
+	if err := validateRaster(data, contentType, frame); err != nil {
+		return nil, "", err
+	}
+	if !frame {
+		normalized, name, err := normalizeBadge(ctx, data, filename, contentType)
+		if err != nil {
+			return nil, "", err
+		}
+		if len(normalized) > MaxArtworkBytes {
+			return nil, "", ErrInvalid
+		}
+		return normalized, name, nil
+	}
+	return data, filename, nil
+}
+
+// Both clients contain artwork in a square, so mildly rectangular exports need no stretching.
+func nearSquare(width, height float64) bool {
+	return min(width, height) >= max(width, height)*0.85
+}
+
+func validateRaster(data []byte, contentType string, frame bool) error {
+	if contentType != "image/png" && contentType != "image/webp" && contentType != "image/gif" {
+		return ErrInvalid
+	}
+	if imagepolicy.ValidateContent(bytes.NewReader(data), contentType) != nil {
+		return ErrInvalid
+	}
+	config, _, err := image.DecodeConfig(bytes.NewReader(data))
+	if err != nil || config.Width < 1 || config.Height < 1 || config.Width > 4096 || config.Height > 4096 || (frame && !nearSquare(float64(config.Width), float64(config.Height))) {
+		return ErrInvalid
+	}
+	if contentType == "image/png" && frame {
+		for pos := 8; pos+12 <= len(data); {
+			size := int(binary.BigEndian.Uint32(data[pos:]))
+			if size > len(data)-pos-12 {
+				return ErrInvalid
+			}
+			if string(data[pos+4:pos+8]) == "acTL" {
+				return ErrInvalid
+			}
+			pos += 12 + size
+		}
+	}
+	if contentType == "image/gif" {
+		return validateGIF(data, frame)
+	}
+	img, _, err := image.Decode(bytes.NewReader(data))
+	if err != nil {
+		return ErrInvalid
+	}
+	if frame && !usableOpening(img) {
+		return ErrInvalid
+	}
+	return nil
+}
+
+// Check the whole circular opening: directional samples can miss opaque pixels between rays.
+func usableOpening(img image.Image) bool {
+	b := img.Bounds()
+	radius := float64(min(b.Dx(), b.Dy())) * minArtworkOpeningRatio / 2
+	cx, cy := float64(b.Min.X+b.Dx()/2), float64(b.Min.Y+b.Dy()/2)
+	for y := max(b.Min.Y, int(math.Ceil(cy-radius))); y <= min(b.Max.Y-1, int(math.Floor(cy+radius))); y++ {
+		for x := max(b.Min.X, int(math.Ceil(cx-radius))); x <= min(b.Max.X-1, int(math.Floor(cx+radius))); x++ {
+			dx, dy := float64(x)-cx, float64(y)-cy
+			if dx*dx+dy*dy >= radius*radius {
+				continue
+			}
+			if _, _, _, a := img.At(x, y).RGBA(); a > 257 {
+				return false
+			}
+		}
+	}
+	return true
+}
+
+// Bound frame allocations before gif.DecodeAll expands attacker-controlled LZW data.
+func gifBudget(data []byte) bool {
+	if len(data) < 13 {
+		return false
+	}
+	pos := 13
+	if data[10]&128 != 0 {
+		pos += 3 * (1 << ((data[10] & 7) + 1))
+	}
+	frames, pixels := 0, 0
+	canvasPixels := int(binary.LittleEndian.Uint16(data[6:])) * int(binary.LittleEndian.Uint16(data[8:]))
+	skipBlocks := func() bool {
+		for pos < len(data) {
+			n := int(data[pos])
+			pos++
+			if n == 0 {
+				return true
+			}
+			pos += n
+		}
+		return false
+	}
+	for pos < len(data) {
+		tag := data[pos]
+		pos++
+		switch tag {
+		case 0x3b:
+			return frames > 0 && pos == len(data)
+		case 0x21:
+			pos++
+			if !skipBlocks() {
+				return false
+			}
+		case 0x2c:
+			if pos+9 > len(data) {
+				return false
+			}
+			w := int(binary.LittleEndian.Uint16(data[pos+4:]))
+			h := int(binary.LittleEndian.Uint16(data[pos+6:]))
+			packed := data[pos+8]
+			pos += 9
+			frames++
+			pixels += w * h
+			if frames > animatedArtworkMaxFrames || pixels > animatedArtworkMaxPixels || frames*canvasPixels > animatedArtworkMaxPixels {
+				return false
+			}
+			if packed&128 != 0 {
+				pos += 3 * (1 << ((packed & 7) + 1))
+			}
+			pos++
+			if !skipBlocks() {
+				return false
+			}
+		default:
+			return false
+		}
+	}
+	return false
+}
+
+func validateGIF(data []byte, frame bool) error {
+	if !gifBudget(data) {
+		return ErrInvalid
+	}
+	animation, err := gif.DecodeAll(bytes.NewReader(data))
+	if err != nil {
+		return ErrInvalid
+	}
+	return visitGIF(animation, func(img image.Image) error {
+		if frame && !usableOpening(img) {
+			return ErrInvalid
+		}
+		return nil
+	})
+}
+
+func visitGIF(animation *gif.GIF, visit func(image.Image) error) error {
+	canvas := image.NewNRGBA(image.Rect(0, 0, animation.Config.Width, animation.Config.Height))
+	draw.Draw(canvas, canvas.Bounds(), image.NewUniform(gifBackground(animation, animation.Image[0])), image.Point{}, draw.Src)
+	for i, img := range animation.Image {
+		if !img.Bounds().In(canvas.Bounds()) {
+			return ErrInvalid
+		}
+		var previous *image.NRGBA
+		disposal := byte(0)
+		if i < len(animation.Disposal) {
+			disposal = animation.Disposal[i]
+		}
+		if disposal == gif.DisposalPrevious {
+			previous = image.NewNRGBA(canvas.Bounds())
+			copy(previous.Pix, canvas.Pix)
+		}
+		draw.Draw(canvas, img.Bounds(), img, img.Bounds().Min, draw.Over)
+		if err := visit(canvas); err != nil {
+			return err
+		}
+		switch disposal {
+		case gif.DisposalBackground:
+			draw.Draw(canvas, img.Bounds(), image.NewUniform(gifBackground(animation, img)), image.Point{}, draw.Src)
+		case gif.DisposalPrevious:
+			copy(canvas.Pix, previous.Pix)
+		}
+	}
+	return nil
+}
+
+func gifBackground(animation *gif.GIF, img *image.Paletted) color.Color {
+	for _, c := range img.Palette {
+		if _, _, _, a := c.RGBA(); a == 0 {
+			return color.Transparent
+		}
+	}
+	if palette, ok := animation.Config.ColorModel.(color.Palette); ok && int(animation.BackgroundIndex) < len(palette) {
+		return palette[animation.BackgroundIndex]
+	}
+	return color.Transparent
+}
+
+func renderSVG(ctx context.Context, data []byte, frame bool) ([]byte, error) {
+	// Never give the renderer a path, embedded image, script or external-resource reference.
+	decoder := xml.NewDecoder(bytes.NewReader(data))
+	depth, nodes, styleDepth := 0, 0, 0
+	for {
+		token, err := decoder.Token()
+		if errors.Is(err, io.EOF) {
+			break
+		}
+		if err != nil {
+			return nil, ErrInvalid
+		}
+		switch item := token.(type) {
+		case xml.Directive:
+			return nil, ErrInvalid
+		case xml.StartElement:
+			depth++
+			nodes++
+			if depth > 64 || nodes > 10000 || (nodes == 1 && item.Name.Local != "svg") {
+				return nil, ErrInvalid
+			}
+			if item.Name.Space != "" && item.Name.Space != "http://www.w3.org/2000/svg" {
+				return nil, ErrInvalid
+			}
+			switch strings.ToLower(item.Name.Local) {
+			case "script", "foreignobject", "image", "feimage", "text", "tspan", "animate", "animatetransform", "animatemotion", "set":
+				return nil, ErrInvalid
+			}
+			if item.Name.Local == "style" {
+				styleDepth = depth
+			}
+			for _, attr := range item.Attr {
+				name, value := strings.ToLower(attr.Name.Local), strings.TrimSpace(attr.Value)
+				if strings.HasPrefix(name, "on") || !safeSVGPaint(value) {
+					return nil, ErrInvalid
+				}
+				if name == "href" && !strings.HasPrefix(value, "#") {
+					return nil, ErrInvalid
+				}
+				if attr.Name.Space == "http://www.w3.org/XML/1998/namespace" && name == "base" {
+					return nil, ErrInvalid
+				}
+			}
+		case xml.CharData:
+			if styleDepth != 0 && !safeSVGPaint(string(item)) {
+				return nil, ErrInvalid
+			}
+		case xml.ProcInst:
+			if item.Target != "xml" {
+				return nil, ErrInvalid
+			}
+		case xml.EndElement:
+			if styleDepth == depth {
+				styleDepth = 0
+			}
+			depth--
+		}
+	}
+	if nodes == 0 || depth != 0 {
+		return nil, ErrInvalid
+	}
+	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
+	defer cancel()
+	select {
+	case svgRenderSlots <- struct{}{}:
+		defer func() { <-svgRenderSlots }()
+	case <-ctx.Done():
+		return nil, ctx.Err()
+	}
+	worker, err := resvg.NewWorker(ctx, wazero.NewRuntimeConfig().WithMemoryLimitPages(4096).WithCloseOnContextDone(true).WithCompilationCache(svgCompilationCache))
+	if err != nil {
+		return nil, err
+	}
+	defer func() { _ = worker.Close() }()
+	tree, err := worker.NewTreeFromData(data, &resvg.Options{})
+	if err != nil {
+		return nil, ErrInvalid
+	}
+	defer func() { _ = tree.Close() }()
+	w, h, err := tree.GetSize()
+	if err != nil || math.IsNaN(float64(w)) || math.IsNaN(float64(h)) || w < 1 || h < 1 || w > 4096 || h > 4096 || (frame && !nearSquare(float64(w), float64(h))) {
+		return nil, ErrInvalid
+	}
+	edge := float32(512)
+	if frame {
+		edge = 1024
+	}
+	scale := edge / max(w, h)
+	pixmap, err := worker.NewPixmap(uint32(math.Ceil(float64(w*scale))), uint32(math.Ceil(float64(h*scale))))
+	if err != nil {
+		return nil, ErrInvalid
+	}
+	defer func() { _ = pixmap.Close() }()
+	if err := tree.Render(resvg.TransformFromScale(scale, scale), pixmap); err != nil {
+		return nil, ErrInvalid
+	}
+	png, err := pixmap.EncodePNG()
+	if err != nil {
+		return nil, ErrInvalid
+	}
+	return png, nil
+}
+
+// CSS paint servers may refer only to local fragments; external imports and escapes are not accepted.
+func safeSVGPaint(value string) bool {
+	if strings.ContainsAny(value, "\\@") {
+		return false
+	}
+	for rest := strings.ToLower(value); strings.Contains(rest, "url("); {
+		_, rest, _ = strings.Cut(rest, "url(")
+		ref, tail, ok := strings.Cut(rest, ")")
+		if !ok || !strings.HasPrefix(strings.Trim(ref, " \t\r\n'\""), "#") {
+			return false
+		}
+		rest = tail
+	}
+	return true
+}

diff --git a/apps/gooseforum/app/service/decorationassetservice/assets.go b/apps/gooseforum/app/service/decorationassetservice/assets.go
new file mode 100644
index 000000000..982fc9f15
--- /dev/null
+++ b/apps/gooseforum/app/service/decorationassetservice/assets.go
@@ -0,0 +1,131 @@
+package decorationassetservice
+
+import (
+	"context"
+	"errors"
+	"io/fs"
+	"path"
+	"strings"
+	"time"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/filemodel/filedata"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/fileUsage"
+	"gorm.io/gorm"
+	"gorm.io/gorm/clause"
+)
+
+var ErrInvalid = errors.New("invalid decoration asset")
+
+// ValidateArtwork requires a centered transparent circle spanning 30% of the shorter side in every frame.
+func ValidateArtwork(data []byte, contentType string) error {
+	return validateRaster(data, contentType, true)
+}
+
+// UploadAsset gives an unsaved draft 24 hours to use its preview URL. A saved
+// definition clears the expiry; CleanupAssets reclaims abandoned/replaced files.
+func UploadAsset(ctx context.Context, actorID uint64, data []byte, filename string) (string, error) {
+	return uploadAsset(ctx, actorID, data, filename, "decorations")
+}
+
+func UploadBadgeAsset(ctx context.Context, actorID uint64, data []byte, filename string) (string, error) {
+	return uploadAsset(ctx, actorID, data, filename, "badges")
+}
+
+func uploadAsset(ctx context.Context, actorID uint64, data []byte, filename, prefix string) (string, error) {
+	if err := ctx.Err(); err != nil {
+		return "", err
+	}
+	data, filename, err := prepareArtwork(ctx, data, filename, prefix == "decorations")
+	if err != nil {
+		return "", err
+	}
+	storagePrefix := prefix
+	if prefix == "badges" {
+		storagePrefix = "badges/normalized"
+	}
+	file, err := filedata.SaveFileFromUploadWithLimit(actorID, data, strings.ToLower(path.Base(filename)), storagePrefix, MaxArtworkBytes)
+	if err != nil {
+		return "", err
+	}
+	if err := ctx.Err(); err != nil {
+		_ = filedata.DeleteByName(file.Name)
+		return "", err
+	}
+	expires := time.Now().Add(24 * time.Hour)
+	err = db.ConnectContext(ctx).Create(&fileUsage.Entity{FileName: file.Name, TargetType: assetTarget(prefix), TargetId: file.Id, UsageType: assetTarget(prefix), UserId: actorID, Status: fileUsage.UsageStatusActive, ExpiresAt: &expires}).Error
+	if err != nil {
+		_ = filedata.DeleteByName(file.Name)
+		return "", err
+	}
+	return "/static/" + file.Name, nil
+}
+
+// ReadAsset serves only generated names with a live reference. Embedded assets
+// are resolved separately by the static mount.
+func ReadAsset(name string) ([]byte, time.Time, error) {
+	if !fileUsage.IsManagedAssetName(name) {
+		return nil, time.Time{}, fs.ErrNotExist
+	}
+	var usage fileUsage.Entity
+	err := db.Connect().Where("file_name = ? AND target_type = ? AND status = ? AND (expires_at IS NULL OR expires_at > ?)", name, assetTarget(strings.SplitN(name, "/", 2)[0]), fileUsage.UsageStatusActive, time.Now()).First(&usage).Error
+	if err != nil {
+		return nil, time.Time{}, fs.ErrNotExist
+	}
+	file, err := filedata.GetFileByName(name)
+	if err != nil {
+		return nil, time.Time{}, fs.ErrNotExist
+	}
+	return file.Data, file.CreatedAt, nil
+}
+
+// CleanupAssets is safe to retry after an interrupted file deletion. It uses
+// the existing reference row as the GC queue and never deletes a live definition.
+func CleanupAssets(ctx context.Context, before time.Time, limit int) (int, error) {
+	var expired []fileUsage.Entity
+	if err := db.ConnectContext(ctx).Where("target_type IN ? AND expires_at IS NOT NULL AND expires_at <= ?", []string{fileUsage.TargetDecorationAsset, fileUsage.TargetBadgeAsset}, before).Limit(limit).Find(&expired).Error; err != nil {
+		return 0, err
+	}
+	removed := 0
+	for _, candidate := range expired {
+		name := ""
+		err := db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+			var usage fileUsage.Entity
+			if err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).Where("id = ? AND expires_at IS NOT NULL AND expires_at <= ?", candidate.Id, before).First(&usage).Error; errors.Is(err, gorm.ErrRecordNotFound) {
+				return nil
+			} else if err != nil {
+				return err
+			}
+			var count int64
+			if err := fileUsage.ManagedAssetReferenceCount(tx, usage.FileName, &count); err != nil {
+				return err
+			}
+			if count != 0 {
+				return tx.Model(&usage).Updates(map[string]any{"status": fileUsage.UsageStatusActive, "expires_at": nil}).Error
+			}
+			name = usage.FileName
+			return tx.Model(&usage).Update("status", fileUsage.UsageStatusPurged).Error
+		})
+		if err != nil {
+			return removed, err
+		}
+		if name == "" {
+			continue
+		}
+		if err := filedata.DeleteByName(name); err != nil {
+			return removed, err
+		}
+		if err := db.ConnectContext(ctx).Where("id = ? AND status = ? AND expires_at IS NOT NULL", candidate.Id, fileUsage.UsageStatusPurged).Delete(&fileUsage.Entity{}).Error; err != nil {
+			return removed, err
+		}
+		removed++
+	}
+	return removed, nil
+}
+
+func assetTarget(prefix string) string {
+	if prefix == "badges" {
+		return fileUsage.TargetBadgeAsset
+	}
+	return fileUsage.TargetDecorationAsset
+}

diff --git a/apps/gooseforum/app/service/decorationassetservice/assets_test.go b/apps/gooseforum/app/service/decorationassetservice/assets_test.go
new file mode 100644
index 000000000..9685ca3ad
--- /dev/null
+++ b/apps/gooseforum/app/service/decorationassetservice/assets_test.go
@@ -0,0 +1,193 @@
+package decorationassetservice
+
+import (
+	"bytes"
+	"image"
+	"image/color"
+	"image/gif"
+	"image/png"
+	"testing"
+)
+
+func TestValidateArtwork(t *testing.T) {
+	makePNG := func(width, height int, centerOpaque bool) []byte {
+		img := image.NewNRGBA(image.Rect(0, 0, width, height))
+		if centerOpaque {
+			img.Set(width/2, height/2, color.NRGBA{R: 255, A: 255})
+		}
+		var out bytes.Buffer
+		if err := png.Encode(&out, img); err != nil {
+			t.Fatal(err)
+		}
+		return out.Bytes()
+	}
+	// thickRing 的开孔直径只占画布 10%，低于 30% 下限。
+	thickRing := func(size int) []byte {
+		img := image.NewNRGBA(image.Rect(0, 0, size, size))
+		c := float64(size) / 2
+		for y := 0; y < size; y++ {
+			for x := 0; x < size; x++ {
+				dx, dy := float64(x)-c, float64(y)-c
+				if dx*dx+dy*dy > (c*0.1)*(c*0.1) {
+					img.Set(x, y, color.NRGBA{R: 30, G: 90, B: 60, A: 255})
+				}
+			}
+		}
+		var out bytes.Buffer
+		if err := png.Encode(&out, img); err != nil {
+			t.Fatal(err)
+		}
+		return out.Bytes()
+	}
+	for _, tc := range []struct {
+		name  string
+		data  []byte
+		valid bool
+	}{
+		{"transparent square", makePNG(20, 20, false), true},
+		// 轻微非方形（±15% 内）放行：渲染端 contain 会把它装进正方框，不会错位。
+		{"near square rectangle", makePNG(21, 20, false), true},
+		{"aspect ratio at limit", makePNG(85, 100, false), true},
+		{"aspect ratio beyond limit", makePNG(100, 84, false), false},
+		{"transparent single pixel", makePNG(1, 1, false), true},
+		{"opaque single pixel", makePNG(1, 1, true), false},
+		{"opaque tiny center", makePNG(2, 2, true), false},
+		{"strongly non-square rectangle", makePNG(20, 40, false), false},
+		{"opaque center", makePNG(20, 20, true), false},
+		{"thick ring without usable opening", thickRing(40), false},
+		{"damaged", []byte("not an image"), false},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			err := ValidateArtwork(tc.data, "image/png")
+			if (err == nil) != tc.valid {
+				t.Fatalf("ValidateArtwork() error = %v, want valid %v", err, tc.valid)
+			}
+		})
+	}
+}
+
+func TestArtworkCircularOpening(t *testing.T) {
+	for _, tc := range []struct {
+		name  string
+		alpha uint8
+		x, y  int
+		valid bool
+	}{
+		{"circular opening with thick ring", 0, 54, 52, true},
+		{"opaque pixel between sampling rays", 255, 54, 52, false},
+		{"opaque center", 255, 50, 50, false},
+		{"allowed opacity", 1, 54, 52, true},
+		{"excess opacity", 2, 54, 52, false},
+		{"ornament outside minimum opening", 255, 67, 50, true},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			img := image.NewNRGBA(image.Rect(0, 0, 100, 100))
+			for y := 0; y < 100; y++ {
+				for x := 0; x < 100; x++ {
+					dx, dy := float64(x)-49.5, float64(y)-49.5
+					if dx*dx+dy*dy >= 19*19 {
+						img.SetNRGBA(x, y, color.NRGBA{A: 255})
+					}
+				}
+			}
+			img.SetNRGBA(tc.x, tc.y, color.NRGBA{A: tc.alpha})
+			var data bytes.Buffer
+			if err := png.Encode(&data, img); err != nil {
+				t.Fatal(err)
+			}
+			if err := ValidateArtwork(data.Bytes(), "image/png"); (err == nil) != tc.valid {
+				t.Fatalf("ValidateArtwork() = %v, want valid %v", err, tc.valid)
+			}
+		})
+	}
+}
+
+func TestAnimatedFrameValidatesEveryCompositedFrame(t *testing.T) {
+	palette := color.Palette{color.Transparent, color.White}
+	first := image.NewPaletted(image.Rect(0, 0, 20, 20), palette)
+	second := image.NewPaletted(image.Rect(0, 0, 20, 20), palette)
+	for _, opaque := range []bool{false, true} {
+		if opaque {
+			second.SetColorIndex(10, 10, 1)
+		}
+		var data bytes.Buffer
+		if err := gif.EncodeAll(&data, &gif.GIF{Image: []*image.Paletted{first, second}, Delay: []int{1, 1}}); err != nil {
+			t.Fatal(err)
+		}
+		err := ValidateArtwork(data.Bytes(), "image/gif")
+		if (err == nil) == opaque {
+			t.Fatalf("opaque=%v: %v", opaque, err)
+		}
+	}
+}
+func TestSVGArtworkIsRasterizedBeforeValidation(t *testing.T) {
+	for _, tc := range []struct {
+		svg          string
+		frame, valid bool
+	}{
+		{`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="10" height="10" fill="red"/></svg>`, true, true},
+		{`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 85 100"><rect width="10" height="10" fill="red"/></svg>`, true, true},
+		{`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 84 100"><rect width="10" height="10" fill="red"/></svg>`, true, false},
+		{`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="red"/></svg>`, true, false},
+		{`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="red"/></svg>`, false, true},
+		{`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><style>.ring{fill:red}</style><rect class="ring" width="3" height="3"/></svg>`, true, true},
+		{`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><style>@import url(file:///etc/passwd)</style></svg>`, false, false},
+		{`<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>`, false, false},
+		{`<svg xmlns="http://www.w3.org/2000/svg"><image href="file:///etc/passwd"/></svg>`, false, false},
+	} {
+		data, name, err := prepareArtwork(t.Context(), []byte(tc.svg), "art.svg", tc.frame)
+		if (err == nil) != tc.valid {
+			t.Fatalf("valid=%v frame=%v: %v", tc.valid, tc.frame, err)
+		}
+		if err == nil {
+			if name != "art.png" {
+				t.Fatal(name)
+			}
+			if _, err := png.Decode(bytes.NewReader(data)); err != nil {
+				t.Fatal(err)
+			}
+		}
+	}
+}
+
+func TestGIFDisposalAndBudget(t *testing.T) {
+	palette := color.Palette{color.Transparent, color.White}
+	first := image.NewPaletted(image.Rect(0, 0, 20, 20), palette)
+	// A later sub-frame must be positioned on the logical canvas, not checked in isolation.
+	second := image.NewPaletted(image.Rect(9, 9, 11, 11), palette)
+	second.SetColorIndex(9, 9, 1)
+	var out bytes.Buffer
+	if err := gif.EncodeAll(&out, &gif.GIF{Image: []*image.Paletted{first, second}, Delay: []int{1, 1}, Disposal: []byte{gif.DisposalPrevious, gif.DisposalBackground}, Config: image.Config{Width: 20, Height: 20, ColorModel: palette}}); err != nil {
+		t.Fatal(err)
+	}
+	if ValidateArtwork(out.Bytes(), "image/gif") == nil {
+		t.Fatal("accepted off-center opaque animation sub-frame")
+	}
+	if validateRaster(out.Bytes(), "image/gif", false) != nil {
+		t.Fatal("badge inherited transparent-center requirement")
+	}
+	images := make([]*image.Paletted, 301)
+	delays := make([]int, 301)
+	for i := range images {
+		images[i] = first
+	}
+	out.Reset()
+	if err := gif.EncodeAll(&out, &gif.GIF{Image: images, Delay: delays}); err != nil {
+		t.Fatal(err)
+	}
+	if validateRaster(out.Bytes(), "image/gif", false) == nil {
+		t.Fatal("accepted excessive decoded frames")
+	}
+}
+
+func TestGIFLogicalBackgroundCannotCoverAvatar(t *testing.T) {
+	palette := color.Palette{color.White}
+	img := image.NewPaletted(image.Rect(0, 0, 2, 2), palette)
+	var data bytes.Buffer
+	if err := gif.EncodeAll(&data, &gif.GIF{Image: []*image.Paletted{img}, Delay: []int{1}, Config: image.Config{Width: 20, Height: 20, ColorModel: palette}}); err != nil {
+		t.Fatal(err)
+	}
+	if ValidateArtwork(data.Bytes(), "image/gif") == nil {
+		t.Fatal("accepted opaque logical background behind partial frame")
+	}
+}

diff --git a/apps/gooseforum/app/service/decorationassetservice/badge_fit.go b/apps/gooseforum/app/service/decorationassetservice/badge_fit.go
new file mode 100644
index 000000000..495612ffb
--- /dev/null
+++ b/apps/gooseforum/app/service/decorationassetservice/badge_fit.go
@@ -0,0 +1,156 @@
+package decorationassetservice
+
+import (
+	"bytes"
+	"cmp"
+	"context"
+	"image"
+	"image/color"
+	"image/draw"
+	"image/gif"
+	"image/png"
+	"math"
+	"path"
+	"slices"
+	"strings"
+	"time"
+
+	xdraw "golang.org/x/image/draw"
+)
+
+// Uploaded artwork shares the system SVGs' ink radius (MADR 0054), not their source canvas margins.
+const badgeInkRadius = 10.0 / 24
+
+func normalizeBadge(ctx context.Context, data []byte, filename, contentType string) ([]byte, string, error) {
+	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
+	defer cancel()
+	var animation *gif.GIF
+	var still image.Image
+	var err error
+	if contentType == "image/gif" {
+		if !gifBudget(data) {
+			return nil, "", ErrInvalid
+		}
+		animation, err = gif.DecodeAll(bytes.NewReader(data))
+	} else {
+		still, _, err = image.Decode(bytes.NewReader(data))
+	}
+	if err != nil {
+		return nil, "", ErrInvalid
+	}
+	visit := func(fn func(image.Image) error) error {
+		if animation != nil {
+			return visitGIF(animation, fn)
+		}
+		return fn(still)
+	}
+	var ink image.Rectangle
+	if err := visit(func(img image.Image) error {
+		if err := ctx.Err(); err != nil {
+			return err
+		}
+		b := img.Bounds()
+		for y := b.Min.Y; y < b.Max.Y; y++ {
+			for x := b.Min.X; x < b.Max.X; x++ {
+				if _, _, _, a := img.At(x, y).RGBA(); a > 257 {
+					ink = ink.Union(image.Rect(x, y, x+1, y+1))
+				}
+			}
+		}
+		return nil
+	}); err != nil {
+		return nil, "", err
+	}
+	if ink.Empty() {
+		return nil, "", ErrInvalid
+	}
+	cx, cy := float64(ink.Min.X+ink.Max.X)/2, float64(ink.Min.Y+ink.Max.Y)/2
+	radius := 0.0
+	if err := visit(func(img image.Image) error {
+		if err := ctx.Err(); err != nil {
+			return err
+		}
+		b := img.Bounds().Intersect(ink)
+		for y := b.Min.Y; y < b.Max.Y; y++ {
+			for x := b.Min.X; x < b.Max.X; x++ {
+				if _, _, _, a := img.At(x, y).RGBA(); a > 257 {
+					radius = max(radius, math.Hypot(math.Abs(float64(x)+.5-cx)+.5, math.Abs(float64(y)+.5-cy)+.5))
+				}
+			}
+		}
+		return nil
+	}); err != nil {
+		return nil, "", err
+	}
+	edge := 512
+	if animation != nil {
+		edge = min(256, int(math.Sqrt(float64(16*1024*1024/len(animation.Image)))))
+	}
+	scale := float64(edge) * badgeInkRadius / radius
+	// One viewport for the entire animation preserves intentional motion and avoids per-frame zooming.
+	destination := image.Rect(int(math.Round(float64(edge)/2+(float64(ink.Min.X)-cx)*scale)), int(math.Round(float64(edge)/2+(float64(ink.Min.Y)-cy)*scale)), int(math.Round(float64(edge)/2+(float64(ink.Max.X)-cx)*scale)), int(math.Round(float64(edge)/2+(float64(ink.Max.Y)-cy)*scale)))
+	if destination.Dx() < 1 {
+		destination.Max.X = destination.Min.X + 1
+	}
+	if destination.Dy() < 1 {
+		destination.Max.Y = destination.Min.Y + 1
+	}
+	var output bytes.Buffer
+	if animation == nil {
+		canvas := image.NewNRGBA(image.Rect(0, 0, edge, edge))
+		xdraw.CatmullRom.Scale(canvas, destination, still, ink, draw.Src, nil)
+		if err := png.Encode(&output, canvas); err != nil {
+			return nil, "", err
+		}
+		return output.Bytes(), strings.TrimSuffix(filename, path.Ext(filename)) + ".png", nil
+	}
+	fitted := &gif.GIF{Delay: animation.Delay, LoopCount: animation.LoopCount, Config: image.Config{Width: edge, Height: edge}}
+	if err := visit(func(img image.Image) error {
+		if err := ctx.Err(); err != nil {
+			return err
+		}
+		canvas := image.NewNRGBA(image.Rect(0, 0, edge, edge))
+		// Nearest-neighbor preserves the original GIF colors instead of adding interpolation colors.
+		xdraw.NearestNeighbor.Scale(canvas, destination, img, ink, draw.Src, nil)
+		frame := image.NewPaletted(canvas.Bounds(), badgePalette(canvas))
+		draw.FloydSteinberg.Draw(frame, frame.Bounds(), canvas, image.Point{})
+		fitted.Image = append(fitted.Image, frame)
+		fitted.Disposal = append(fitted.Disposal, gif.DisposalBackground)
+		return nil
+	}); err != nil {
+		return nil, "", err
+	}
+	if err := gif.EncodeAll(&output, fitted); err != nil {
+		return nil, "", err
+	}
+	return output.Bytes(), filename, nil
+}
+
+// Preserve the most-used source colors exactly and reserve transparency for the normalized padding.
+func badgePalette(img *image.NRGBA) color.Palette {
+	counts := map[color.NRGBA]int{}
+	for y := 0; y < img.Bounds().Dy(); y++ {
+		for x := 0; x < img.Bounds().Dx(); x++ {
+			c := img.NRGBAAt(x, y)
+			if c.A > 1 {
+				c.A = 255
+				counts[c]++
+			}
+		}
+	}
+	colors := make([]color.NRGBA, 0, len(counts))
+	for c := range counts {
+		colors = append(colors, c)
+	}
+	slices.SortFunc(colors, func(a, b color.NRGBA) int {
+		if counts[a] != counts[b] {
+			return counts[b] - counts[a]
+		}
+		return cmp.Or(cmp.Compare(a.R, b.R), cmp.Compare(a.G, b.G), cmp.Compare(a.B, b.B))
+	})
+	palette := color.Palette{color.Transparent}
+	for _, c := range colors[:min(255, len(colors))] {
+		palette = append(palette, c)
+	}
+	return palette
+}

