+			rank := func() topics.Entity {
+				t.Helper()
+				if worked, err := workRank(ctx, time.Now()); err != nil || !worked {
+					t.Fatalf("rank: worked=%v err=%v", worked, err)
+				}
+				var got topics.Entity
+				if err := conn.First(&got, "id = ?", topicID).Error; err != nil {
+					t.Fatal(err)
+				}
+				return got
+			}
+			mark()
+			before := rank()
+			if !before.RankReady || before.RankEngaged != 1 {
+				t.Fatalf("fixture has no ready peer projection: %+v", before)
+			}
+			// A view/like job is already due. Run it after the reply commits but
+			// before reconcile gets a chance to detect the changed source.
+			mark()
+			replyAt := time.Now().Add(-time.Minute)
+			reply := posts.Entity{TopicId: topicID, UserId: newcomer, Content: "new public reply", FirstPublicAt: &replyAt, IsAnonymous: anonymous, VisibilityStatus: posts.VisibilityActive}
+			if err := postservice.CreateTopicPost(&reply, topic); err != nil {
+				t.Fatal(err)
+			}
+			mark() // Later ordinary dirtiness must preserve the reply invalidation.
+			got := rank()
+			if got.RankEngaged != 2 || got.LastPublicReplyAt == nil || !got.LastPublicReplyAt.Equal(replyAt) {
+				t.Fatalf("queued rank lost the new reply: people=%d last=%v want %v", got.RankEngaged, got.LastPublicReplyAt, replyAt)
+			}
+			if got.RankSource != topics.RankSource(got) {
+				t.Fatal("rank watermark does not match the rebuilt source")
+			}
+			participants, err := topicUserStat.RankParticipants(ctx, topicID)
+			if err != nil {
+				t.Fatal(err)
+			}
+			found := false
+			for _, p := range participants {
+				if p.UserId == newcomer && p.RankReplyCount == 1 {
+					found = true
+				}
+			}
+			if !found {
+				t.Fatal("new reply missing from the stored participant projection")
+			}
+		})
+	}
+}
+
+func TestReplyLifecycleRebuildsRankingWithoutSynchronousProjection(t *testing.T) {
+	conn := telemetryDB(t)
+	if err := conn.AutoMigrate(&topicUserAction.Entity{}, &topicUserStat.Entity{}, &topicUserStat.RankParticipant{}); err != nil {
+		t.Fatal(err)
+	}
+	preferences.Set("ranking.enabled", true)
+	t.Cleanup(func() { feedconfig.SetRankReady(false) })
+	const topicID, author, peer uint64 = 998101, 998111, 998112
+	at := time.Now().Add(-8 * 24 * time.Hour)
+	people := []users.EntityComplete{{Id: author, Username: "rank-life-author", Email: "rank-life-author@example.invalid"}, {Id: peer, Username: "rank-life-peer", Email: "rank-life-peer@example.invalid"}}
+	if err := conn.Create(&people).Error; err != nil {
+		t.Fatal(err)
+	}
+	topic := topics.Entity{Id: topicID, UserId: author, Status: 1, FirstPostId: topicID, FirstPublicAt: &at}
+	if err := conn.Create(&topic).Error; err != nil {
+		t.Fatal(err)
+	}
+	rows := []posts.Entity{{Id: topicID, TopicId: topicID, UserId: author, PostNo: 1, FirstPublicAt: &at}, {Id: topicID + 1, TopicId: topicID, UserId: peer, PostNo: 2, FirstPublicAt: &at}}
+	if err := conn.Create(&rows).Error; err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() {
+		conn.Unscoped().Where("topic_id = ?", topicID).Delete(&posts.Entity{})
+		conn.Unscoped().Delete(&topic)
+		conn.Unscoped().Where("id IN ?", []uint64{author, peer}).Delete(&users.EntityComplete{})
+		conn.Where("topic_id = ?", topicID).Delete(&topicUserStat.Entity{})
+		conn.Where("topic_id = ?", topicID).Delete(&topicUserStat.RankParticipant{})
+	})
+	ctx := context.Background()
+	score := func() int64 {
+		t.Helper()
+		worked, err := workRank(ctx, time.Now())
+		if err != nil || !worked {
+			t.Fatalf("lifecycle not durably queued: worked=%v err=%v", worked, err)
+		}
+		var got topics.Entity
+		if err := conn.First(&got, "id = ?", topicID).Error; err != nil {
+			t.Fatal(err)
+		}
+		if got.RankReady && got.RankSource != topics.RankSource(got) {
+			t.Fatal("rebuilt projection left a stale watermark and would queue another rebuild")
+		}
+		return got.RankScore
+	}
+	if err := conn.Transaction(func(tx *gorm.DB) error { return feed.MarkTx(tx, topicID) }); err != nil {
+		t.Fatal(err)
+	}
+	before := score()
+	if before <= 0 {
+		t.Fatal("fixture has no peer contribution")
+	}
+	if err := posts.UpdateProcessStatus(topicID+1, posts.ProcessStatusBlocked); err != nil {
+		t.Fatal(err)
+	}
+	if err := conn.Transaction(func(tx *gorm.DB) error { return feed.MarkTx(tx, topicID) }); err != nil {
+		t.Fatal(err)
+	}
+	if got := score(); got >= before {
+		t.Fatalf("blocked reply still contributes: %d >= %d", got, before)
+	}
+	if err := posts.UpdateProcessStatus(topicID+1, posts.ProcessStatusNormal); err != nil {
+		t.Fatal(err)
+	}
+	if got := score(); got != before {
+		t.Fatalf("unblocked score=%d want %d", got, before)
+	}
+	if err := conn.Transaction(func(tx *gorm.DB) error { return posts.MarkUserDeletedTx(tx, topicID+1, peer, "") }); err != nil {
+		t.Fatal(err)
+	}
+	if got := score(); got >= before {
+		t.Fatalf("deleted reply still contributes: %d", got)
+	}
+	if err := posts.Restore(topicID + 1); err != nil {
+		t.Fatal(err)
+	}
+	if got := score(); got != before {
+		t.Fatalf("restored score=%d want %d", got, before)
+	}
+	// A hidden parent may consume a reply invalidation before becoming public.
+	if err := conn.Transaction(func(tx *gorm.DB) error { return topics.UpdateProcessStatusTx(tx, topicID, topics.ProcessStatusBlocked) }); err != nil {
+		t.Fatal(err)
+	}
+	if err := posts.UpdateProcessStatus(topicID+1, posts.ProcessStatusBlocked); err != nil {
+		t.Fatal(err)
+	}
+	if got := score(); got != 0 {
+		t.Fatalf("hidden parent score=%d", got)
+	}
+	if err := conn.Transaction(func(tx *gorm.DB) error { return topics.UpdateProcessStatusTx(tx, topicID, topics.ProcessStatusNormal) }); err != nil {
+		t.Fatal(err)
+	}
+	if got := score(); got != 0 {
+		t.Fatalf("parent restoration revived a blocked reply: %d", got)
+	}
+	if err := posts.UpdateProcessStatus(topicID+1, posts.ProcessStatusNormal); err != nil {
+		t.Fatal(err)
+	}
+	if got := score(); got != before {
+		t.Fatalf("peer restoration score=%d want %d", got, before)
+	}
+	// Frozen actors can disappear from the rebuilt projection; unfreezing must
+	// derive their current public replies again, rather than trust that projection.
+	for _, status := range []int8{users.StatusFrozen, users.StatusNormal} {
+		if err := users.UpdateFields(peer, map[string]any{"is_frozen": status}); err != nil {
+			t.Fatal(err)
+		}
+		if status == users.StatusFrozen {
+			for _, state := range []int8{posts.ProcessStatusBlocked, posts.ProcessStatusNormal} {
+				if err := posts.UpdateProcessStatus(topicID+1, state); err != nil {
+					t.Fatal(err)
+				}
+			}
+		}
+		for i := 0; i < 5; i++ {
+			worked, err := workActor(ctx)
+			if err != nil {
+				t.Fatal(err)
+			}
+			if !worked {
+				break
+			}
+		}
+		got := score()
+		if status == users.StatusFrozen && got != 0 {
+			t.Fatalf("frozen peer score=%d", got)
+		}
+		if status == users.StatusNormal && got != before {
+			t.Fatalf("unfreezing lost public peer history: %d want %d", got, before)
+		}
+	}
+	// Pausing ranking skips invalidation writes. Re-enabling must rebuild those
+	// missed public-reply changes before the old scores can become ready again.
+	for key, value := range map[string]string{"desired_rank_hash": feedconfig.Current().RankHash, "promoted_rank_hash": feedconfig.Current().RankHash, "posts_backfilled": "true", "topics_backfilled": "true", "ranking_enabled": "true"} {
+		if err := putState(ctx, key, value); err != nil {
+			t.Fatal(err)
+		}
+	}
+	feedconfig.SetRankReady(true)
+	preferences.Set("ranking.enabled", false)
+	if err := posts.UpdateProcessStatus(topicID+1, posts.ProcessStatusBlocked); err != nil {
+		t.Fatal(err)
+	}
+	preferences.Set("ranking.enabled", true)
+	if feedconfig.RankReady() {
+		t.Fatal("pause/resume promoted stale scores before rebuilding missed changes")
+	}
+	for i := 0; i < 5; i++ {
+		if err := backfillRank(ctx); err != nil {
+			t.Fatal(err)
+		}
+	}
+	if got := score(); got != 0 {
+		t.Fatalf("paused moderation still contributes after rebuilding: %d", got)
+	}
+	if err := posts.UpdateProcessStatus(topicID+1, posts.ProcessStatusNormal); err != nil {
+		t.Fatal(err)
+	}
+	if got := score(); got != before {
+		t.Fatalf("post-resume score=%d want %d", got, before)
+	}
+	failure := errors.New("roll back lifecycle")
+	if err := conn.Transaction(func(tx *gorm.DB) error {
+		if err := posts.UpdateProcessStatusTx(tx, topicID+1, posts.ProcessStatusBlocked); err != nil {
+			return err
+		}
+		return failure
+	}); !errors.Is(err, failure) {
+		t.Fatal(err)
+	}
+	var scheduled int64
+	if err := conn.Model(&feed.Schedule{}).Where("topic_id = ?", topicID).Count(&scheduled).Error; err != nil {
+		t.Fatal(err)
+	}
+	if scheduled != 0 || posts.Get(topicID+1).ProcessStatus != posts.ProcessStatusNormal {
+		t.Fatal("rolled-back moderation left ranking work or changed visibility")
+	}
+	if err := conn.Callback().Create().Before("gorm:create").Register("test_fail_rank_schedule", func(tx *gorm.DB) {
+		if tx.Statement.Table == "topic_rank_schedule" {
+			_ = tx.AddError(failure)
+		}
+	}); err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() {
+		if err := conn.Callback().Create().Remove("test_fail_rank_schedule"); err != nil {
+			t.Error(err)
+		}
+	})
+	if err := posts.UpdateProcessStatus(topicID+1, posts.ProcessStatusBlocked); !errors.Is(err, failure) {
+		t.Fatalf("enqueue failure not propagated: %v", err)
+	}
+	if posts.Get(topicID+1).ProcessStatus != posts.ProcessStatusNormal {
+		t.Fatal("enqueue failure committed moderation without repair work")
+	}
+
+}

diff --git a/apps/gooseforum/app/service/feedservice/memory.go b/apps/gooseforum/app/service/feedservice/memory.go
new file mode 100644
index 000000000..143f716d4
--- /dev/null
+++ b/apps/gooseforum/app/service/feedservice/memory.go
@@ -0,0 +1,184 @@
+package feedservice
+
+import (
+	"context"
+	"sync"
+	"time"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/feedconfig"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/feed"
+	"gorm.io/gorm"
+	"gorm.io/gorm/clause"
+)
+
+type memoryKey struct {
+	User, Topic uint64
+	Name        string
+}
+type memoryEntry struct {
+	At, Expires time.Time
+	Trace       string
+	Position    int
+}
+
+// Each entry is conservatively charged 256 bytes plus string storage, including
+// map overhead. These caches are lossy hints, never authoritative access state.
+type boundedMemory struct {
+	sync.Mutex
+	entries      map[memoryKey]memoryEntry
+	bytes, limit int
+}
+
+func (m *boundedMemory) get(k memoryKey, now time.Time) (memoryEntry, bool) {
+	m.Lock()
+	defer m.Unlock()
+	e, ok := m.entries[k]
+	return e, ok && e.Expires.After(now)
+}
+func (m *boundedMemory) put(k memoryKey, e memoryEntry) bool {
+	m.Lock()
+	defer m.Unlock()
+	if m.entries == nil {
+		m.entries = map[memoryKey]memoryEntry{}
+	}
+	size := 256 + len(k.Name) + len(e.Trace)
+	if m.bytes+size > m.limit {
+		n := 0
+		for key, old := range m.entries {
+			if !old.Expires.After(time.Now()) {
+				m.bytes -= 256 + len(key.Name) + len(old.Trace)
+				delete(m.entries, key)
+			}
+			n++
+			if n >= 64 {
+				break
+			}
+		}
+	}
+	if old, ok := m.entries[k]; ok {
+		m.bytes -= 256 + len(k.Name) + len(old.Trace)
+		delete(m.entries, k)
+	}
+	if m.bytes+size > m.limit {
+		return false
+	}
+	m.entries[k] = e
+	m.bytes += size
+	return true
+}
+func (m *boundedMemory) once(k memoryKey, now time.Time, ttl time.Duration) bool {
+	if _, ok := m.get(k, now); ok {
+		return false
+	}
+	return m.put(k, memoryEntry{At: now, Expires: now.Add(ttl)})
+}
+func (m *boundedMemory) clear(uid uint64) {
+	m.Lock()
+	defer m.Unlock()
+	for k, e := range m.entries {
+		if uid == 0 || k.User == uid {
+			m.bytes -= 256 + len(k.Name) + len(e.Trace)
+			delete(m.entries, k)
+		}
+	}
+}
+
+var dailySeen = boundedMemory{limit: 2 << 20}
+var repeats = boundedMemory{limit: 4 << 20}
+var inferred = boundedMemory{limit: 2 << 20}
+
+func rememberVisible(s feed.Serve, mask uint32) {
+	items, err := decodeServed(s.Items)
+	if err != nil {
+		return
+	}
+	now := time.Now()
+	for pos, c := range items {
+		if mask&(1<<pos) != 0 {
+			repeats.put(memoryKey{User: s.UserID, Topic: c.ID}, memoryEntry{At: now, Expires: now.Add(24 * time.Hour)})
+		}
+	}
+}
+func wasRepeated(uid, topic uint64, lastReply *time.Time, now time.Time) bool {
+	e, ok := repeats.get(memoryKey{User: uid, Topic: topic}, now)
+	return ok && (lastReply == nil || !lastReply.After(e.At))
+}
+func rememberLegacy(uid uint64, items []Candidate, trace string) {
+	now := time.Now()
+	for pos, c := range items {
+		inferred.put(memoryKey{User: uid, Topic: c.ID}, memoryEntry{At: now, Expires: now.Add(6 * time.Hour), Trace: trace, Position: pos})
+	}
+}
+func clearViewerMemory(uid uint64) {
+	dailySeen.clear(uid)
+	repeats.clear(uid)
+	inferred.clear(uid)
+	assignments.clear(uid)
+	viewWritten.clear(uid)
+	viewsMu.Lock()
+	for k := range pendingViews {
+		if uid == 0 || k.User == uid {
+			delete(pendingViews, k)
+		}
+	}
+	viewsMu.Unlock()
+}
+func InvalidateAccount(uid uint64) { invalidateViewer(uid); clearViewerMemory(uid) }
+
+var viewsMu sync.Mutex
+var pendingViews = map[memoryKey]feed.ViewFact{}
+var viewWritten = boundedMemory{limit: 1 << 20}
+
+func captureViewFact(row feed.ViewFact) {
+	k := memoryKey{User: row.UserID, Topic: row.TopicID}
+	if _, ok := viewWritten.get(k, row.ViewedAt); ok {
+		return
+	}
+	viewsMu.Lock()
+	defer viewsMu.Unlock()
+	if len(pendingViews) >= 4096 {
+		dropped.Add(1)
+		return
+	}
+	pendingViews[k] = row
+}
+func flushViews(ctx context.Context, c feedconfig.Config) error {
+	viewsMu.Lock()
+	if !c.Metrics {
+		pendingViews = map[memoryKey]feed.ViewFact{}
+		viewsMu.Unlock()
+		viewWritten.clear(0)
+		return nil
+	}
+	rows := make([]feed.ViewFact, 0, 50)
+	for k, row := range pendingViews {
+		rows = append(rows, row)
+		delete(pendingViews, k)
+		if len(rows) == 50 {
+			break
+		}
+	}
+	viewsMu.Unlock()
+	for _, row := range rows {
+		err := db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+			if err := feed.LockOwnerTx(tx, row.UserID); err != nil {
+				return err
+			}
+			r := tx.Clauses(clause.OnConflict{Columns: []clause.Column{{Name: "topic_id"}, {Name: "user_id"}}, DoUpdates: clause.AssignmentColumns([]string{"viewed_at", "expires_at"}), Where: clause.Where{Exprs: []clause.Expression{clause.Expr{SQL: "topic_view_fact.viewed_at <= ?", Vars: []any{row.ViewedAt.Add(-5 * time.Minute)}}}}}).Create(&row)
+			if r.Error != nil {
+				return r.Error
+			}
+			if r.RowsAffected > 0 {
+				return feed.MarkTx(tx, row.TopicID)
+			}
+			return nil
+		})
+		if err != nil {
+			dropped.Add(1)
+		} else {
+			viewWritten.put(memoryKey{User: row.UserID, Topic: row.TopicID}, memoryEntry{At: row.ViewedAt, Expires: row.ViewedAt.Add(5 * time.Minute)})
+		}
+	}
+	return nil
+}

diff --git a/apps/gooseforum/app/service/feedservice/new_topics.go b/apps/gooseforum/app/service/feedservice/new_topics.go
new file mode 100644
index 000000000..5f6d4b832
--- /dev/null
+++ b/apps/gooseforum/app/service/feedservice/new_topics.go
@@ -0,0 +1,128 @@
+package feedservice
+
+import (
+	"errors"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/feedconfig"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/feed"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/posts"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"gorm.io/gorm"
+	"gorm.io/gorm/clause"
+)
+
+func newTopicMetric(tx *gorm.DB, row feed.NewTopicOutcome, name string, delta int64) error {
+	return addMetric(tx, feed.Serve{CreatedAt: row.PublicAt, Feed: "new_topics", Hash: row.Hash, RankHash: row.RankHash, Variant: "all", WeightVariant: "all", Capability: "all"}, name, delta)
+}
+
+func newTopicCohortTx(tx *gorm.DB, topic topics.Entity) (*feed.NewTopicOutcome, error) {
+	if topic.FirstPublicAt == nil || topic.FirstPublicEstimated || topic.FirstPublicAt.After(time.Now()) || time.Since(*topic.FirstPublicAt) >= 30*24*time.Hour {
+		return nil, nil
+	}
+	if err := feed.LockOwnerTx(tx, topic.UserId); errors.Is(err, feed.ErrClosed) {
+		return nil, nil
+	} else if err != nil {
+		return nil, err
+	}
+	cfg := feedconfig.Current()
+	row := feed.NewTopicOutcome{TopicID: topic.Id, UserID: topic.UserId, PublicAt: *topic.FirstPublicAt, ExpiresAt: topic.FirstPublicAt.Add(30 * 24 * time.Hour), Hash: cfg.Hash, RankHash: cfg.RankHash}
+	r := tx.Clauses(clause.OnConflict{DoNothing: true}).Create(&row)
+	if r.Error != nil {
+		return nil, r.Error
+	}
+	if r.RowsAffected == 1 {
+		if err := newTopicMetric(tx, row, "new_topic_public", 1); err != nil {
+			return nil, err
+		}
+	}
+	if err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).First(&row, "topic_id = ? AND expires_at > ?", topic.Id, time.Now()).Error; err != nil {
+		return nil, err
+	}
+	return &row, nil
+}
+
+// The denominator is actual new publication, never historical estimated time.
+// Unique visibility within 24 hours and first peer response are cohort metrics,
+// independent of entry assignment; they do not assert an experimental effect.
+func captureNewTopicPublicationTx(tx *gorm.DB, event feed.Event) error {
+	rows, err := topics.NewTopicFactsTx(tx, []uint64{event.TopicID})
+	if err != nil {
+		return err
+	}
+	for _, topic := range rows {
+		row, err := newTopicCohortTx(tx, topic)
+		if err != nil {
+			return err
+		}
+		if row == nil || row.Replied || event.Kind != "public_reply" {
+			continue
+		}
+		at, err := posts.FirstPeerReplyTx(tx, topic.Id, topic.UserId)
+		if err != nil {
+			return err
+		}
+		if at == nil || at.Before(row.PublicAt) {
+			continue
+		}
+		if err := newTopicMetric(tx, *row, "new_topic_first_reply", 1); err != nil {
+			return err
+		}
+		if err := newTopicMetric(tx, *row, "first_reply_seconds", int64(at.Sub(row.PublicAt).Seconds())); err != nil {
+			return err
+		}
+		if err := tx.Model(row).UpdateColumn("replied", true).Error; err != nil {
+			return err
+		}
+	}
+	return nil
+}
+
+func captureNewTopicVisibilityTx(tx *gorm.DB, ids []uint64, viewer uint64, visibleAt time.Time) error {
+	if len(ids) == 0 {
+		return nil
+	}
+	// Almost all scrolling rows already have a first visibility watermark.
+	// Batch those checks before any owner lock or publication metadata read.
+	var existing []feed.NewTopicOutcome
+	if err := tx.Where("topic_id IN ? AND visible = ? AND expires_at > ?", ids, true, time.Now()).Find(&existing).Error; err != nil {
+		return err
+	}
+	seen := map[uint64]bool{}
+	for _, row := range existing {
+		seen[row.TopicID] = true
+	}
+	pending := []uint64{}
+	for _, id := range ids {
+		if !seen[id] {
+			pending = append(pending, id)
+		}
+	}
+	if len(pending) == 0 {
+		return nil
+	}
+	rows, err := topics.NewTopicFactsTx(tx, pending)
+	if err != nil {
+		return err
+	}
+	for _, topic := range rows {
+		// Old topics need no cohort lookup or owner lock on a scrolling request.
+		if topic.UserId == viewer || topic.FirstPublicAt == nil || visibleAt.Before(*topic.FirstPublicAt) || visibleAt.Sub(*topic.FirstPublicAt) >= 24*time.Hour {
+			continue
+		}
+		row, err := newTopicCohortTx(tx, topic)
+		if err != nil {
+			return err
+		}
+		if row == nil || row.Visible {
+			continue
+		}
+		if err := newTopicMetric(tx, *row, "new_topic_visible_24h", 1); err != nil {
+			return err
+		}
+		if err := tx.Model(row).UpdateColumn("visible", true).Error; err != nil {
+			return err
+		}
+	}
+	return nil
+}

diff --git a/apps/gooseforum/app/service/feedservice/new_topics_test.go b/apps/gooseforum/app/service/feedservice/new_topics_test.go
