@@ -0,0 +1,67 @@
+package feedservice
+
+import (
+	"context"
+	"reflect"
+	"testing"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topicCategoryIndex"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"gorm.io/gorm"
+)
+
+func TestPublicCategoryPoolReusesIDsWithoutMixingCategoryLimitOrHash(t *testing.T) {
+	conn := telemetryDB(t)
+	if err := conn.AutoMigrate(&topicCategoryIndex.Entity{}); err != nil {
+		t.Fatal(err)
+	}
+	publicPools.clear(0)
+	t.Cleanup(func() { publicPools.clear(0) })
+	now := time.Now()
+	rows := []topics.Entity{
+		{Id: 935001, Status: 1, FirstPublicAt: &now, RankScore: 600},
+		{Id: 935002, Status: 1, FirstPublicAt: &now, RankScore: 500},
+		{Id: 935003, Status: 1, FirstPublicAt: &now, RankScore: 700},
+	}
+	if err := conn.Create(&rows).Error; err != nil {
+		t.Fatal(err)
+	}
+	indices := []topicCategoryIndex.Entity{{TopicId: 935001, CategoryId: 951, Effective: 1}, {TopicId: 935002, CategoryId: 951, Effective: 1}, {TopicId: 935003, CategoryId: 952, Effective: 1}}
+	if err := conn.Create(&indices).Error; err != nil {
+		t.Fatal(err)
+	}
+	queries := 0
+	if err := conn.Callback().Query().After("gorm:query").Register("test_public_pool_count", func(tx *gorm.DB) { queries++ }); err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() {
+		if err := conn.Callback().Query().Remove("test_public_pool_count"); err != nil {
+			t.Error(err)
+		}
+	})
+	check := func(q topics.Recall, want []uint64) {
+		t.Helper()
+		got, err := recallPool(context.Background(), q)
+		if err != nil || !reflect.DeepEqual(got, want) {
+			t.Fatalf("recall(%+v) = %v, %v; want %v", q, got, err, want)
+		}
+	}
+	q := topics.Recall{Source: "category", Hash: "test-v1", Category: 951, Limit: 1}
+	check(q, []uint64{935001})
+	before := queries
+	check(q, []uint64{935001})
+	if queries != before {
+		t.Fatal("same public pool performed another SQL recall")
+	}
+	q.Limit = 2
+	check(q, []uint64{935001, 935002})
+	q.Category = 952
+	check(q, []uint64{935003})
+	if err := conn.Model(&topics.Entity{}).Where("id = ?", 935002).UpdateColumn("rank_score", 800).Error; err != nil {
+		t.Fatal(err)
+	}
+	q.Category = 951
+	q.Hash = "test-v2"
+	check(q, []uint64{935002, 935001})
+}

diff --git a/apps/gooseforum/app/service/feedservice/samples.go b/apps/gooseforum/app/service/feedservice/samples.go
new file mode 100644
index 000000000..e1e5da650
--- /dev/null
+++ b/apps/gooseforum/app/service/feedservice/samples.go
@@ -0,0 +1,117 @@
+package feedservice
+
+import (
+	"bytes"
+	"compress/zlib"
+	"context"
+	"crypto/sha256"
+	"encoding/base64"
+	"encoding/binary"
+	"encoding/json"
+	"errors"
+	"io"
+	"strings"
+	"time"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/feedconfig"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/feed"
+	"gorm.io/gorm"
+)
+
+var sampleQueue []feed.CandidateSample
+var sampleBytes int
+
+func captureCandidateSample(uid uint64, s *snapshot, pool []Candidate, cfg feedconfig.Config) {
+	salted := sha256.Sum256([]byte(cfg.Salt + ":samples:" + s.ID))
+	if !cfg.Metrics || float64(binary.BigEndian.Uint64(salted[:8])%10000)/10000 >= cfg.SampleRate {
+		return
+	}
+	data, err := encodeServed(pool)
+	if err != nil {
+		dropped.Add(1)
+		return
+	}
+	if len(data) > 32<<10 {
+		dropped.Add(1)
+		return
+	}
+	row := feed.CandidateSample{ID: s.ID, UserID: uid, Hash: s.Hash, Candidates: data, Seed: s.Seed, CreatedAt: s.Created, ExpiresAt: s.Created.Add(time.Duration(cfg.RetentionDays) * 24 * time.Hour)}
+	queueMu.Lock()
+	defer queueMu.Unlock()
+	if sampleBytes+len(data) > 2<<20 {
+		dropped.Add(1)
+		return
+	}
+	sampleQueue = append(sampleQueue, row)
+	sampleBytes += len(data)
+}
+func flushSample(ctx context.Context, cfg feedconfig.Config) error {
+	queueMu.Lock()
+	if !cfg.Metrics {
+		sampleQueue = nil
+		sampleBytes = 0
+		queueMu.Unlock()
+		return nil
+	}
+	if len(sampleQueue) == 0 {
+		queueMu.Unlock()
+		return nil
+	}
+	row := sampleQueue[0]
+	sampleQueue[0] = feed.CandidateSample{}
+	sampleQueue = sampleQueue[1:]
+	sampleBytes -= len(row.Candidates)
+	queueMu.Unlock()
+	return db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		if err := feed.LockOwnerTx(tx, row.UserID); err != nil {
+			return err
+		}
+		return tx.Create(&row).Error
+	})
+}
+
+type ReplayResult struct {
+	Items              []Candidate `json:"items"`
+	CompleteCandidates bool        `json:"completeCandidates"`
+	Limitation         string      `json:"limitation"`
+}
+
+func ReplaySample(ctx context.Context, id string, w feedconfig.Weights) (ReplayResult, error) {
+	var row feed.CandidateSample
+	if err := db.ConnectContext(ctx).First(&row, "id = ? AND expires_at > ?", id, time.Now()).Error; err != nil {
+		if !errors.Is(err, gorm.ErrRecordNotFound) {
+			return ReplayResult{}, err
+		}
+		var served feed.Serve
+		if e := db.ConnectContext(ctx).First(&served, "id = ? AND expires_at > ?", id, time.Now()).Error; e != nil {
+			return ReplayResult{}, e
+		}
+		items, e := decodeServed(served.Items)
+		if e != nil {
+			return ReplayResult{}, e
+		}
+		return ReplayResult{Items: items, CompleteCandidates: false, Limitation: "Only the recorded served page is available; no counterfactual recall or full candidate reranking is possible."}, nil
+	}
+	pool := []Candidate{}
+	data := []byte(row.Candidates)
+	if strings.HasPrefix(row.Candidates, "z1:") {
+		encoded, e := base64.RawStdEncoding.DecodeString(row.Candidates[3:])
+		if e != nil {
+			return ReplayResult{}, e
+		}
+		reader, e := zlib.NewReader(bytes.NewReader(encoded))
+		if e != nil {
+			return ReplayResult{}, e
+		}
+		defer func() { _ = reader.Close() }()
+		data, e = io.ReadAll(io.LimitReader(reader, 128<<10))
+		if e != nil {
+			return ReplayResult{}, e
+		}
+	}
+	if err := json.Unmarshal(data, &pool); err != nil {
+		return ReplayResult{}, err
+	}
+	return ReplayResult{Items: SelectCandidates(pool, w, row.Seed), CompleteCandidates: true, Limitation: "Replays the recorded finite candidate pool; historical visibility and causal effects are not recoverable."}, nil
+}

diff --git a/apps/gooseforum/app/service/feedservice/score.go b/apps/gooseforum/app/service/feedservice/score.go
new file mode 100644
index 000000000..0b67c4d5d
--- /dev/null
+++ b/apps/gooseforum/app/service/feedservice/score.go
@@ -0,0 +1,386 @@
+package feedservice
+
+import (
+	"math"
+	"math/rand/v2"
+	"sort"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/feedconfig"
+)
+
+type Participant struct {
+	UserID            uint64
+	Replies           uint32
+	LastPublicReplyAt *time.Time
+	Liked             bool
+}
+type TimedAction struct {
+	UserID uint64
+	Kind   string
+	At     time.Time
+}
+type RankInput struct {
+	Author        uint64
+	FirstPublicAt time.Time
+	Participants  []Participant
+	Actions       []TimedAction
+}
+type RankResult struct {
+	Hot               int64
+	Daily             int64
+	NextDue           time.Time
+	HotPeople         int
+	HotReplyEffective int
+	HotLikers         int
+	Fresh             float64
+	Active            float64
+	Engaged           int
+	Views             float64
+	Replies           float64
+	ReplyPeople       float64
+	Likes             float64
+	Bookmarks         float64
+}
+
+func normalized(x, cap float64) float64 {
+	return math.Log1p(math.Min(math.Max(0, x), cap)) / math.Log1p(cap)
+}
+
+// ScoreRank is the only Hot/Daily scoring implementation, shared by worker,
+// explain and replay. Daily reply caps apply across the entire 24-hour window.
+func ScoreRank(in RankInput, now time.Time) RankResult {
+	return ScoreRankWithRules(in, now, feedconfig.DefaultRules())
+}
+func ScoreRankWithRules(in RankInput, now time.Time, rules feedconfig.MaterializedRules) RankResult {
+	out := RankResult{NextDue: now.Add(time.Hour)}
+	boundary := func(at time.Time, ds ...time.Duration) {
+		for _, d := range ds {
+			b := at.Add(d)
+			if b.After(now) && b.Before(out.NextDue) {
+				out.NextDue = b
+			}
+		}
+	}
+	engaged := map[uint64]bool{}
+	likers := 0
+	effective := 0
+	var last time.Time
+	for _, p := range in.Participants {
+		if p.UserID == 0 || p.UserID == in.Author {
+			continue
+		}
+		if p.Liked {
+			likers++
+			engaged[p.UserID] = true
+		}
+		if p.Replies > 0 {
+			effective += int(min(p.Replies, rules.ReplyPerUser))
+			engaged[p.UserID] = true
+			if p.LastPublicReplyAt != nil && p.LastPublicReplyAt.After(last) && !p.LastPublicReplyAt.After(now) {
+				last = *p.LastPublicReplyAt
+			}
+		}
+	}
+	fresh := 0.
+	age := now.Sub(in.FirstPublicAt)
+	if !in.FirstPublicAt.IsZero() && age >= 0 {
+		for i, hours := range rules.FreshHours {
+			if age < time.Duration(hours)*time.Hour {
+				fresh = rules.FreshValues[i]
+				break
+			}
+		}
+	}
+	for _, hours := range rules.FreshHours {
+		boundary(in.FirstPublicAt, time.Duration(hours)*time.Hour)
+	}
+	active := 0.
+	if effective > 0 && !last.IsZero() {
+		for i, hours := range rules.ActiveHours {
+			if now.Sub(last) < time.Duration(hours)*time.Hour {
+				active = rules.ActiveValues[i]
+				break
+			}
+		}
+		for _, hours := range rules.ActiveHours {
+			boundary(last, time.Duration(hours)*time.Hour)
+		}
+	}
+	out.HotPeople = len(engaged)
+	out.HotReplyEffective = effective
+	out.HotLikers = likers
+	out.Fresh = fresh
+	out.Active = active
+	out.Hot = int64(math.Round(1000 * (rules.HotLikeWeight*normalized(float64(likers), rules.HotCaps[0]) + rules.HotReplyWeight*normalized(float64(effective), rules.HotCaps[1]) + fresh*math.Min(1, .2+.4*float64(len(engaged))) + active)))
+	replies := map[uint64][]time.Time{}
+	dailyEngaged := map[uint64]bool{}
+	viewers := map[uint64]bool{}
+	for _, a := range in.Actions {
+		if a.UserID == 0 || a.UserID == in.Author {
+			continue
+		}
+		weight := ageWeightWithRules(now.Sub(a.At), rules)
+		if weight == 0 {
+			continue
+		}
+		boundary(a.At, 3*time.Hour, 12*time.Hour, 24*time.Hour)
+		switch a.Kind {
+		case "view":
+			out.Views += weight
+			viewers[a.UserID] = true
+		case "reply":
+			replies[a.UserID] = append(replies[a.UserID], a.At)
+			dailyEngaged[a.UserID] = true
+		case "like":
+			out.Likes += weight
+			dailyEngaged[a.UserID] = true
+		case "bookmark":
+			out.Bookmarks += weight
+			dailyEngaged[a.UserID] = true
+		}
+	}
+	for _, times := range replies {
+		sort.Slice(times, func(i, j int) bool { return times[i].Before(times[j]) })
+		times = times[:min(len(times), int(rules.ReplyPerUser))]
+		for _, at := range times {
+			out.Replies += ageWeightWithRules(now.Sub(at), rules)
+		}
+		out.ReplyPeople += ageWeightWithRules(now.Sub(times[len(times)-1]), rules)
+	}
+	out.Engaged = len(dailyEngaged)
+	if len(dailyEngaged) >= rules.EngagementMinimum || len(viewers) >= rules.ViewMinimum {
+		weighted := 0.
+		for i, value := range []float64{out.Views, out.ReplyPeople, out.Replies, out.Likes, out.Bookmarks} {
+			weighted += rules.DailyWeights[i] * normalized(value, rules.DailyCaps[i])
+		}
+		out.Daily = int64(math.Round(100000 * weighted))
+	}
+	// Refresh smooth view/action decay and detect projection drift, but never skip
+	// a discontinuous age boundary. Quiet old topics refresh hourly.
+	refresh := time.Hour
+	if len(dailyEngaged) > 0 || len(viewers) > 0 {
+		refresh = 30 * time.Minute
+	}
+	if !last.IsZero() && now.Sub(last) < time.Hour {
+		refresh = 10 * time.Minute
+	}
+	if now.Add(refresh).Before(out.NextDue) {
+		out.NextDue = now.Add(refresh)
+	}
+	if age >= 7*24*time.Hour && (last.IsZero() || now.Sub(last) >= 24*time.Hour) && len(dailyEngaged) == 0 && len(viewers) == 0 {
+		out.NextDue = time.Time{}
+	}
+	return out
+}
+
+type Features [7]uint16
+type Candidate struct {
+	ID           uint64   `json:"id"`
+	Author       uint64   `json:"author"`
+	Sources      uint8    `json:"sources"`
+	Features     Features `json:"features"`
+	Repeat       bool     `json:"repeat,omitempty"`
+	Reason       string   `json:"reason,omitempty"`
+	Base         int64    `json:"base"`
+	Adjusted     int64    `json:"adjusted"`
+	Explore      bool     `json:"explore,omitempty"`
+	Pool         int      `json:"pool,omitempty"`
+	Team         string   `json:"team,omitempty"`
+	SoftFiltered bool     `json:"softFiltered,omitempty"`
+	Fallback     bool     `json:"fallback,omitempty"`
+}
+
+func Quantize(v float64) uint16 { return uint16(math.Round(math.Min(1, math.Max(0, v)) * 10000)) }
+func ScoreFeatures(f Features, w feedconfig.Weights) int64 {
+	sum := 0.
+	for i, v := range []float64{w.Follow, w.Recency, w.Quality, w.Daily, w.Category, w.Author, w.NewReply} {
+		sum += float64(f[i]) * v
+	}
+	if f[0] == 0 {
+		sum *= .75
+	}
+	return int64(math.Round(sum))
+}
+
+// Rank greedily applies author diversity to bounded candidates. random is a
+// deterministic PRNG whose seed is recorded in the snapshot/sample.
+func Rank(pool []Candidate, w feedconfig.Weights, seed uint64, limit int) []Candidate {
+	if limit > feedconfig.SnapshotSize {
+		limit = feedconfig.SnapshotSize
+	}
+	pool = append([]Candidate(nil), pool...)
+	out := make([]Candidate, 0, min(limit, len(pool)))
+	authors := map[uint64]int{}
+	rng := rand.New(rand.NewPCG(seed, seed^0x9e3779b97f4a7c15))
+	random := rng.IntN
+	for len(pool) > 0 && len(out) < limit {
+		best := -1
+		var value int64
+		for i, c := range pool {
+			base := ScoreFeatures(c.Features, w)
+			factor := math.Max(.25, math.Pow(.5, float64(authors[c.Author])))
+			if c.Repeat {
+				factor *= .7
+			}
+			adjusted := int64(math.Round(float64(base) * factor))
+			pool[i].Base = base
+			pool[i].Adjusted = adjusted
+			if best < 0 || adjusted > value || adjusted == value && c.ID > pool[best].ID {
+				best = i
+				value = adjusted
+			}
+		}
+		if slot := len(out) % 20; slot == 3 || slot == 10 {
+			explore := []int{}
+			for i, c := range pool {
+				if c.Sources&32 != 0 && !c.SoftFiltered {
+					explore = append(explore, i)
+				}
+			}
+			if len(explore) > 0 {
+				best = explore[random(len(explore))]
+				pool[best].Explore = true
+				pool[best].Pool = len(explore)
+			}
+		}
+		chosen := pool[best]
+		out = append(out, chosen)
+		authors[chosen.Author]++
+		pool = append(pool[:best], pool[best+1:]...)
+	}
+	return out
+}
+
+// SelectCandidates preserves the recorded primary/relaxed/fallback phases in
+// live ranking and offline replay. Repeat is relaxed only when a page is short.
+func SelectCandidates(pool []Candidate, w feedconfig.Weights, seed uint64) []Candidate {
+	primary, relaxed, fallback := []Candidate{}, []Candidate{}, []Candidate{}
+	for _, c := range pool {
+		if c.Fallback {
+			fallback = append(fallback, c)
+		} else if c.SoftFiltered {
+			relaxed = append(relaxed, c)
+		} else {
+			primary = append(primary, c)
+		}
+	}
+	out := Rank(primary, w, seed, 120)
+	if len(out) < 20 {
+		combined := append(append([]Candidate{}, primary...), relaxed...)
+		for i := range combined {
+			combined[i].Repeat = false
+		}
+		out = Rank(combined, w, seed, 120)
+	}
+	if len(out) < 20 {
+		combined := append(append(append([]Candidate{}, primary...), relaxed...), fallback...)
+		for i := range combined {
+			combined[i].Repeat = false
+		}
+		out = Rank(combined, w, seed, 120)
+	}
+	return out
+}
+
+// InterleaveCandidates scores both teams against the same selected-author
+// counts. Exploration is selected once from their common pool and is shared.
+func InterleaveCandidates(pool []Candidate, a, b feedconfig.Weights, seed uint64) []Candidate {
+	eligible := []Candidate{}
+	for _, c := range pool {
+		if !c.Fallback && !c.SoftFiltered {
+			eligible = append(eligible, c)
+		}
+	}
+	if len(eligible) < 20 {
+		eligible = nil
+		for _, c := range pool {
+			if !c.Fallback {
+				c.Repeat = false
+				eligible = append(eligible, c)
+			}
+		}
+	}
+	if len(eligible) < 20 {
+		eligible = append([]Candidate(nil), pool...)
+		for i := range eligible {
+			eligible[i].Repeat = false
+		}
+	}
+	out := []Candidate{}
+	authors := map[uint64]int{}
+	rng := rand.New(rand.NewPCG(seed, seed^0x517cc1b727220a95))
+	turn := rng.IntN(2)
+	bestFor := func(w feedconfig.Weights) int {
+		best := -1
+		var score int64
+		for i, c := range eligible {
+			factor := math.Max(.25, math.Pow(.5, float64(authors[c.Author])))
+			if c.Repeat {
+				factor *= .7
+			}
+			v := int64(math.Round(float64(ScoreFeatures(c.Features, w)) * factor))
+			if best < 0 || v > score || v == score && c.ID > eligible[best].ID {
+				best = i
+				score = v
+			}
+		}
+		return best
+	}
+	for len(eligible) > 0 && len(out) < 120 {
+		ai, bi := bestFor(a), bestFor(b)
+		chosen := ai
+		team := "A"
+		if turn == 1 {
+			chosen = bi
+			team = "B"
+		}
+		if ai == bi {
+			team = "shared"
+		} else {
+			turn = 1 - turn
+		}
+		if slot := len(out) % 20; slot == 3 || slot == 10 {
+			indices := []int{}
+			for i, c := range eligible {
+				if c.Sources&32 != 0 && !c.SoftFiltered {
+					indices = append(indices, i)
+				}
+			}
+			if len(indices) > 0 {
+				chosen = indices[rng.IntN(len(indices))]
+				eligible[chosen].Explore = true
+				eligible[chosen].Pool = len(indices)
+				team = "shared"
+			}
+		}
+		c := eligible[chosen]
+		c.Team = team
+		w := a
+		if team == "B" {
+			w = b
+		}
+		c.Base = ScoreFeatures(c.Features, w)
+		factor := math.Max(.25, math.Pow(.5, float64(authors[c.Author])))
+		if c.Repeat {
+			factor *= .7
+		}
+		c.Adjusted = int64(math.Round(float64(c.Base) * factor))
+		authors[c.Author]++
+		out = append(out, c)
+		eligible = append(eligible[:chosen], eligible[chosen+1:]...)
+	}
+	return out
+}
+
+func ageWeightWithRules(age time.Duration, rules feedconfig.MaterializedRules) float64 {
+	if age < 0 {
+		return 0
+	}
+	for i, hours := range rules.DailyHours {
+		if age < time.Duration(hours)*time.Hour {
+			return rules.AgeWeights[i]
+		}
+	}
+	return 0
+}

