+		}
+		if e := tx.Model(&feed.UserDaily{}).Where("user_id = ? AND day = ?", event.UserID, state.Day).UpdateColumn(col, gorm.Expr("CASE WHEN "+col+" + ? < 0 THEN 0 ELSE "+col+" + ? END", delta, delta)).Error; e != nil {
