@@ -0,0 +1,83 @@
+package httpnotifyservice
+
+import (
+	"encoding/json"
+	"errors"
+	"net/http"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/pageConfig"
+)
+
+// notifyChannel 通知通道适配器（issue #1049）：事件生产者只产出领域事件与安全摘要，
+// 通道决定请求体、签名与“对方是否真正接收”的判定。新增 Slack/企业微信等通道只需
+// 实现本接口，不改变事件生产者。
+type notifyChannel interface {
+	// supportsEvent 通道能否投递该事件名（卡片通道只渲染审批事件）。
+	supportsEvent(eventName string) bool
+	// requiresApproval 通道是否只能渲染审批摘要（Message.Approval 为空时跳过）。
+	requiresApproval() bool
+	encode(endpoint pageConfig.HttpNotifyEndpoint, alt Alternative, approval *ApprovalPayload, now time.Time) ([]byte, error)
+	// testBody 管理端「测试发送」的请求体：让管理员在保存前确认地址、签名与展示效果。
+	testBody(endpoint pageConfig.HttpNotifyEndpoint, baseURI string, now time.Time) ([]byte, error)
+	buildRequest(endpoint pageConfig.HttpNotifyEndpoint, eventName string, deliveryID string, timestamp int64, body []byte) (*http.Request, error)
+	// checkResponse 非 nil 即计为失败，进入 failureCount/lastError/异常停用。
+	checkResponse(resp *http.Response) error
+}
+
+func channelFor(endpoint pageConfig.HttpNotifyEndpoint) notifyChannel {
+	switch pageConfig.NormalizeHttpNotifyChannel(endpoint.ChannelType) {
+	case pageConfig.HttpNotifyChannelFeishu:
+		return feishuChannel{}
+	case pageConfig.HttpNotifyChannelAstrBot:
+		return astrbotChannel{}
+	default:
+		return genericChannel{}
+	}
+}
+
+// genericChannel 通用 Webhook：Envelope JSON + X-Goose-* 头 + 可选 HMAC 签名，2xx 即成功。
+type genericChannel struct{}
+
+func (genericChannel) supportsEvent(string) bool { return true }
+
+func (genericChannel) requiresApproval() bool { return false }
+
+func (genericChannel) encode(_ pageConfig.HttpNotifyEndpoint, alt Alternative, _ *ApprovalPayload, now time.Time) ([]byte, error) {
+	return json.Marshal(Envelope{Event: alt.Event, Timestamp: now.Unix(), Data: alt.Data})
+}
+
+// testBody 发送 webhook.test 事件：与正式事件同样带 X-Goose-* 头与签名，接收方可借此验签。
+func (genericChannel) testBody(endpoint pageConfig.HttpNotifyEndpoint, baseURI string, now time.Time) ([]byte, error) {
+	return json.Marshal(Envelope{Event: EventWebhookTest, Timestamp: now.Unix(), Data: WebhookTestData{
+		BaseURI:      baseURI,
+		EndpointID:   endpoint.Id,
+		EndpointName: endpoint.Name,
+		Message:      "This is a test delivery from the HTTP notification settings.",
+	}})
+}
+
+func (genericChannel) buildRequest(endpoint pageConfig.HttpNotifyEndpoint, eventName string, deliveryID string, timestamp int64, body []byte) (*http.Request, error) {
+	return buildRequest(endpoint, eventName, deliveryID, timestamp, body)
+}
+
+func (genericChannel) checkResponse(resp *http.Response) error {
+	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
+		return errors.New(resp.Status)
+	}
+	return nil
+}
+
+// IsApprovalEvent 事件名是否属于版主审批通知（含“全部举报”聚合兼容事件）。
+func IsApprovalEvent(eventName string) bool {
+	switch eventName {
+	case EventReportCreated,
+		EventReviewTopicRequested, EventReviewPostRequested,
+		EventAppealSubmitted,
+		EventReportTopicCreated, EventReportPostCreated,
+		EventReportChatMessageCreated, EventReportCourseReviewCreated:
+		return true
+	default:
+		return false
+	}
+}

diff --git a/apps/gooseforum/app/service/httpnotifyservice/channel_astrbot.go b/apps/gooseforum/app/service/httpnotifyservice/channel_astrbot.go
new file mode 100644
index 000000000..60a7d5954
--- /dev/null
+++ b/apps/gooseforum/app/service/httpnotifyservice/channel_astrbot.go
@@ -0,0 +1,274 @@
+package httpnotifyservice
+
+import (
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"net/http"
+	"strings"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/pageConfig"
+)
+
+// astrbotChannel AstrBot 推送插件 astrbot_plugin_push_lite（issue #1049）：向插件的
+// POST /send 发送 {content, umo, message_type: "text"}，由 AstrBot 转发到 umo 指定的
+// 会话（QQ 群、私聊等，umo 即在目标会话发送 /sid 得到的 SID）。插件无需改动：
+// endpoint.Target 为 umo，endpoint.Secret 为插件配置里的 API token。
+// 插件只把消息放进队列就返回 queued，真正发到聊天平台失败时这里无法得知。
+type astrbotChannel struct{}
+
+func (astrbotChannel) supportsEvent(string) bool { return true }
+
+func (astrbotChannel) requiresApproval() bool { return false }
+
+func (astrbotChannel) encode(endpoint pageConfig.HttpNotifyEndpoint, alt Alternative, approval *ApprovalPayload, _ time.Time) ([]byte, error) {
+	if approval != nil {
+		return astrbotBody(endpoint, astrbotApprovalText(*approval, false))
+	}
+	return astrbotBody(endpoint, astrbotEventText(alt))
+}
+
+// testBody 发送一条示例举报文本，与真实审批消息同一排版，链接只指向版主工作台。
+func (astrbotChannel) testBody(endpoint pageConfig.HttpNotifyEndpoint, baseURI string, now time.Time) ([]byte, error) {
+	sample := sampleApproval(baseURI, now)
+	return astrbotBody(endpoint, astrbotApprovalText(sample, true))
+}
+
+func astrbotBody(endpoint pageConfig.HttpNotifyEndpoint, content string) ([]byte, error) {
+	umo := strings.TrimSpace(endpoint.Target)
+	if umo == "" {
+		return nil, errors.New("target session (SID) is required")
+	}
+	return json.Marshal(map[string]string{
+		"content":      content,
+		"umo":          umo,
+		"message_type": "text",
+	})
+}
+
+// buildRequest 插件按 Authorization 头整串比对 "Bearer <token>"。URL 只填到端口
+// （没有路径）时补上 /send，省去管理员记接口路径。
+func (astrbotChannel) buildRequest(endpoint pageConfig.HttpNotifyEndpoint, _ string, _ string, _ int64, body []byte) (*http.Request, error) {
+	req, err := newJSONPost(endpoint, body)
+	if err != nil {
+		return nil, err
+	}
+	if req.URL.Path == "" || req.URL.Path == "/" {
+		req.URL.Path = "/send"
+	}
+	if endpoint.Secret != "" {
+		req.Header.Set("Authorization", "Bearer "+endpoint.Secret)
+	}
+	return req, nil
+}
+
+// checkResponse 2xx 且返回 {"status":"queued"} 才算成功；插件的 400/403 带
+// {"error","details"}，details 是可读原因（如 "403 Forbidden: 无效令牌"）。
+func (astrbotChannel) checkResponse(resp *http.Response) error {
+	raw, err := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
+	if err != nil {
+		return fmt.Errorf("astrbot response read failed: %w", err)
+	}
+	var result struct {
+		Status  string `json:"status"`
+		Details string `json:"details"`
+	}
+	parsed := json.Unmarshal(raw, &result) == nil
+	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
+		if parsed && result.Details != "" {
+			return errors.New(SafeText(result.Details, 160))
+		}
+		return errors.New(resp.Status)
+	}
+	if !parsed {
+		return errors.New("astrbot response is not JSON (is the URL the push_lite /send endpoint?)")
+	}
+	if result.Status != "queued" {
+		return fmt.Errorf("astrbot response status %q, want \"queued\"", SafeText(result.Status, 40))
+	}
+	return nil
+}
+
+// astrbotApprovalText 审批摘要的纯文本排版：首行【种类 · 目标】+ 标签，随后编号、
+// 标题、摘要、元信息、举报说明与处理链接。用户文本已经 SafeText 折叠为单行，
+// 不会伪造出额外的行或链接说明。
+func astrbotApprovalText(payload ApprovalPayload, test bool) string {
+	a := payload.Approval
+	target := approvalTargetLabels[a.TargetType]
+	if target == "" {
+		target = SafeText(a.TargetType, 20)
+	}
+	kind := "待人工审核"
+	if a.Kind == ApprovalKindReport {
+		kind = "新举报"
+	} else if a.Kind == ApprovalKindAppeal {
+		kind = "新申诉"
+	}
+	tags := make([]string, 0, 4)
+	if reason := approvalReasonLabels[a.Reason]; reason != "" {
+		tags = append(tags, reason)
+	} else if a.Reason != "" {
+		tags = append(tags, SafeText(a.Reason, 20))
+	}
+	if a.Edited {
+		tags = append(tags, "编辑后")
+	}
+	if a.Anonymous {
+		tags = append(tags, "匿名")
+	}
+
+	var b strings.Builder
+	if test {
+		b.WriteString("【测试】")
+	}
+	b.WriteString("【" + kind + " · " + target + "】")
+	b.WriteString(strings.Join(tags, " · "))
+	line := func(label, value string) {
+		if value != "" {
+			b.WriteString("\n" + label + "：" + value)
+		}
+	}
+	line("编号", approvalSubject(a, target))
+	line("标题", SafeText(a.Title, 100))
+	line("摘要", SafeText(a.Excerpt, 200))
+	switch {
+	case a.Anonymous:
+		line("作者", "匿名（不披露身份）")
+	case a.Author != nil:
+		line("作者", SafeText(a.Author.DisplayName, 40))
+	}
+	if len(a.Categories) > 0 {
+		line("分类", SafeText(strings.Join(a.Categories, "、"), 40))
+	}
+	line("时间", approvalTime(a.CreatedAt))
+	line("举报说明", SafeText(a.Note, 300))
+	if a.TargetType == "chat_message" {
+		b.WriteString("\n私信内容不会发到外部，请在版主工作台查看证据并处理。")
+	}
+	if a.Kind == ApprovalKindAppeal {
+		b.WriteString("\n" + appealPrivacyNote)
+	}
+
+	base := strings.TrimRight(payload.BaseURI, "/")
+	if base == "" {
+		b.WriteString("\n\n站点地址未配置，无法生成处理链接，请在版主工作台处理。")
+		return b.String()
+	}
+	// 文本里链接不能像按钮那样区分样式：与工作台同址的动作（如测试消息）只保留工作台一行。
+	links := make([]string, 0, len(a.Actions)+1)
+	for _, action := range a.Actions {
+		if label := approvalActionLabel(a.Kind, action.Action); label != "" && action.URL != "" && action.URL != a.ModerationURL {
+			links = append(links, label+"："+base+action.URL)
+		}
+	}
+	if a.ModerationURL != "" {
+		links = append(links, "版主工作台："+base+a.ModerationURL)
+	}
+	if len(links) > 0 {
+		b.WriteString("\n\n" + strings.Join(links, "\n"))
+	}
+	switch {
+	case test:
+		b.WriteString("\n（测试消息，内容仅为示例；链接只会打开版主工作台）")
+	case len(a.Actions) > 0:
+		b.WriteString("\n（链接会先打开本站确认页，登录且有审核权限才能处理）")
+	}
+	return b.String()
+}
+
+var astrbotEventTitles = map[string]string{
+	EventTopicPublished: "新话题",
+	EventTopicUpdated:   "话题已更新",
+	EventCommentCreated: "新回复",
+	EventUserSignup:     "新用户注册",
+	EventReportCreated:  "新举报",
+}
+
+// astrbotEventData 通用事件负载中用于文本排版的字段（与 eventhandlers 的 JSON 形状一致）。
+type astrbotEventData struct {
+	BaseURI        string `json:"baseUri"`
+	ContentPreview string `json:"contentPreview"`
+	Topic          *struct {
+		Title       string `json:"title"`
+		URL         string `json:"url"`
+		Description string `json:"description"`
+		User        struct {
+			DisplayName string `json:"displayName"`
+		} `json:"user"`
+		Categories []struct {
+			Name string `json:"name"`
+		} `json:"categories"`
+	} `json:"topic"`
+	User *struct {
+		DisplayName string `json:"displayName"`
+		Username    string `json:"username"`
+		URL         string `json:"url"`
+	} `json:"user"`
+	Post *struct {
+		URL string `json:"url"`
+	} `json:"post"`
+}
+
+// astrbotEventText 非审批事件（新话题、新回复、新用户等）的纯文本：标题行 + 关键字段 + 链接。
+func astrbotEventText(alt Alternative) string {
+	title := astrbotEventTitles[alt.Event]
+	if title == "" {
+		title = SafeText(alt.Event, 60)
+	}
+	var data astrbotEventData
+	if raw, err := json.Marshal(alt.Data); err == nil {
+		_ = json.Unmarshal(raw, &data)
+	}
+	base := strings.TrimRight(data.BaseURI, "/")
+	absolute := func(path string) string {
+		if path == "" || base == "" || !strings.HasPrefix(path, "/") {
+			return ""
+		}
+		return base + path
+	}
+
+	var b strings.Builder
+	b.WriteString("【" + title + "】")
+	line := func(label, value string) {
+		if value != "" {
+			b.WriteString("\n" + label + "：" + value)
+		}
+	}
+	link := ""
+	if t := data.Topic; t != nil {
+		b.WriteString(SafeText(t.Title, 100))
+		if alt.Event != EventCommentCreated {
+			line("作者", SafeText(t.User.DisplayName, 40))
+			names := make([]string, 0, len(t.Categories))
+			for _, c := range t.Categories {
+				names = append(names, c.Name)
+			}
+			line("分类", SafeText(strings.Join(names, "、"), 40))
+			line("摘要", SafeText(t.Description, 200))
+		}
+		link = absolute(t.URL)
+	}
+	if u := data.User; u != nil {
+		name := SafeText(u.DisplayName, 40)
+		if username := SafeText(u.Username, 40); username != "" && username != name {
+			name += "（@" + username + "）"
+		}
+		switch alt.Event {
+		case EventCommentCreated:
+			line("回复者", name)
+		case EventUserSignup:
+			b.WriteString(name)
+			link = absolute(u.URL)
+		}
+	}
+	line("内容", SafeText(data.ContentPreview, 200))
+	if p := data.Post; p != nil && absolute(p.URL) != "" {
+		link = absolute(p.URL)
+	}
+	if link != "" {
+		b.WriteString("\n" + link)
+	}
+	return b.String()
+}

diff --git a/apps/gooseforum/app/service/httpnotifyservice/channel_astrbot_test.go b/apps/gooseforum/app/service/httpnotifyservice/channel_astrbot_test.go
new file mode 100644
index 000000000..ed2cc7851
--- /dev/null
+++ b/apps/gooseforum/app/service/httpnotifyservice/channel_astrbot_test.go
@@ -0,0 +1,153 @@
+package httpnotifyservice
+
+import (
+	"encoding/json"
+	"io"
+	"net/http"
+	"net/http/httptest"
+	"strings"
+	"testing"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/pageConfig"
+)
+
+// pushLiteStub 复刻 astrbot_plugin_push_lite v0.2.2 的 /send：Authorization 整串比对，
+// 缺 content/umo 返回 400，成功返回 queued。
+func pushLiteStub(t *testing.T, token string, got chan<- map[string]string) *httptest.Server {
+	t.Helper()
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		w.Header().Set("Content-Type", "application/json")
+		if r.Method != http.MethodPost || r.URL.Path != "/send" {
+			w.WriteHeader(http.StatusNotFound)
+			_, _ = w.Write([]byte("<h1>Not Found</h1>"))
+			return
+		}
+		if r.Header.Get("Authorization") != "Bearer "+token {
+			w.WriteHeader(http.StatusForbidden)
+			_, _ = w.Write([]byte(`{"error":"Forbidden","details":"403 Forbidden: 无效令牌"}`))
+			return
+		}
+		var data map[string]string
+		if err := json.NewDecoder(r.Body).Decode(&data); err != nil || data["content"] == "" || data["umo"] == "" {
+			w.WriteHeader(http.StatusBadRequest)
+			_, _ = w.Write([]byte(`{"error":"Bad Request","details":"400 Bad Request: 缺少字段"}`))
+			return
+		}
+		got <- data
+		_, _ = w.Write([]byte(`{"status":"queued","message_id":"m1","queue_size":1}`))
+	}))
+	t.Cleanup(server.Close)
+	return server
+}
+
+func TestSendTestAstrBotPushesTextToTargetSession(t *testing.T) {
+	got := make(chan map[string]string, 1)
+	server := pushLiteStub(t, "tok", got)
+	endpoint := pageConfig.HttpNotifyEndpoint{
+		ChannelType: pageConfig.HttpNotifyChannelAstrBot,
+		URL:         server.URL, // 只填到端口：自动补 /send
+		Target:      "aiocqhttp:GroupMessage:123456",
+		Secret:      "tok",
+	}
+	if err := SendTest(endpoint, "https://hub.example.test", time.Unix(1_800_000_000, 0)); err != nil {
+		t.Fatal(err)
+	}
+	data := <-got
+	if data["umo"] != "aiocqhttp:GroupMessage:123456" || data["message_type"] != "text" {
+		t.Fatalf("body = %v", data)
+	}
+	content := data["content"]
+	for _, want := range []string{"【测试】【新举报 · 回复】垃圾广告", "举报说明：", "\n\n版主工作台：https://hub.example.test/moderation?tab=reports\n"} {
+		if !strings.Contains(content, want) {
+			t.Fatalf("content missing %q:\n%s", want, content)
+		}
+	}
+	if strings.Count(content, "https://") != 1 {
+		t.Fatalf("sample actions share the workbench URL and must collapse into one link:\n%s", content)
+	}
+
+	endpoint.URL = server.URL + "/send"
+	endpoint.Secret = "wrong"
+	if err := SendTest(endpoint, "", time.Now()); err == nil || !strings.Contains(err.Error(), "无效令牌") {
+		t.Fatalf("bad token = %v", err)
+	}
+	endpoint.Secret = "tok"
+	endpoint.URL = server.URL + "/other"
+	if err := SendTest(endpoint, "", time.Now()); err == nil || err.Error() != "404 Not Found" {
+		t.Fatalf("wrong path = %v", err)
+	}
+	endpoint.URL = server.URL
+	endpoint.Target = " "
+	if err := SendTest(endpoint, "", time.Now()); err == nil || !strings.Contains(err.Error(), "SID") {
+		t.Fatalf("missing target = %v", err)
+	}
+}
+
+func TestAstrBotRejectsResponsesThatAreNotQueued(t *testing.T) {
+	reply := `{"status":"ok","queue_size":0}`
+	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
+		_, _ = io.ReadAll(r.Body)
+		_, _ = w.Write([]byte(reply))
+	}))
+	t.Cleanup(server.Close)
+	endpoint := pageConfig.HttpNotifyEndpoint{ChannelType: pageConfig.HttpNotifyChannelAstrBot, URL: server.URL + "/send", Target: "s", Secret: "t"}
+	if err := SendTest(endpoint, "", time.Now()); err == nil || !strings.Contains(err.Error(), "queued") {
+		t.Fatalf("non-queued status = %v", err)
+	}
+	reply = "<html>AstrBot</html>"
+	if err := SendTest(endpoint, "", time.Now()); err == nil || !strings.Contains(err.Error(), "not JSON") {
+		t.Fatalf("html reply = %v", err)
+	}
+}
+
+func TestNewJSONPostRejectsURLsWithoutHost(t *testing.T) {
+	for _, raw := range []string{"http:///send", "http://:9966/send", "https://"} {
+		_, err := newJSONPost(pageConfig.HttpNotifyEndpoint{URL: raw}, nil)
+		if err == nil || !strings.Contains(err.Error(), "missing a host") {
+			t.Fatalf("%q: err = %v", raw, err)
+		}
+	}
+}
+
+func TestAstrBotTextRendersApprovalsAndEvents(t *testing.T) {
+	endpoint := pageConfig.HttpNotifyEndpoint{ChannelType: pageConfig.HttpNotifyChannelAstrBot, Target: "s"}
+	decode := func(body []byte) string {
+		t.Helper()
+		var data map[string]string
+		if err := json.Unmarshal(body, &data); err != nil {
+			t.Fatal(err)
+		}
+		return data["content"]
+	}
+
+	body, err := astrbotChannel{}.encode(endpoint, Alternative{Event: EventReportPostCreated}, testApproval(), time.Now())
+	if err != nil {
+		t.Fatal(err)
+	}
+	text := decode(body)
+	// 用户文本折叠为单行：换行与控制字符不能伪造出额外的行。
+	for _, want := range []string{"【新举报 · 回复】辱骂/人身攻击 · 匿名", "摘要：line1 line2\n", "作者：匿名（不披露身份）", "时间：2026-10-04 20:00\n", "封禁并结案：https://hub.example.test/moderation/action?token=t1"} {
+		if !strings.Contains(text, want) {
+			t.Fatalf("approval text missing %q:\n%s", want, text)
+		}
+	}
+	if strings.Contains(text, "\x00") {
+		t.Fatalf("control characters must be stripped: %q", text)
+	}
+
+	comment := map[string]any{
+		"baseUri":        "https://hub.example.test",
+		"contentPreview": "同问\n期末考范围",
+		"topic":          map[string]any{"title": "高数复习", "url": "/post/7", "user": map[string]any{"displayName": "楼主"}},
+		"user":           map[string]any{"displayName": "小明", "username": "xm"},
+		"post":           map[string]any{"url": "/post/7#post-3"},
+	}
+	body, err = astrbotChannel{}.encode(endpoint, Alternative{Event: EventCommentCreated, Data: comment}, nil, time.Now())
+	if err != nil {
+		t.Fatal(err)
+	}
+	if text := decode(body); text != "【新回复】高数复习\n回复者：小明（@xm）\n内容：同问 期末考范围\nhttps://hub.example.test/post/7#post-3" {
+		t.Fatalf("comment text:\n%s", text)
+	}
+}

diff --git a/apps/gooseforum/app/service/httpnotifyservice/channel_feishu.go b/apps/gooseforum/app/service/httpnotifyservice/channel_feishu.go
new file mode 100644
index 000000000..69aac0079
--- /dev/null
+++ b/apps/gooseforum/app/service/httpnotifyservice/channel_feishu.go
@@ -0,0 +1,409 @@
+package httpnotifyservice
+
+import (
+	"crypto/hmac"
+	"crypto/sha256"
+	"encoding/base64"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"net/http"
+	"strconv"
+	"strings"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/pageConfig"
+)
+
+// feishuChannel 飞书群自定义机器人（issue #1049）：无需注册飞书应用，直接向群 webhook
+// 发送 schema 2.0 interactive 卡片。自定义机器人卡片只支持 open_url 按钮，因此快捷
+// 动作是指向 Hub 确认页的签名链接，最终处理仍在 Hub 内完成登录与权限复核。
+type feishuChannel struct{}
+
+func (feishuChannel) supportsEvent(eventName string) bool { return IsApprovalEvent(eventName) }
+
+func (feishuChannel) requiresApproval() bool { return true }
+
+func (feishuChannel) encode(endpoint pageConfig.HttpNotifyEndpoint, _ Alternative, approval *ApprovalPayload, now time.Time) ([]byte, error) {
+	if approval == nil {
+		return nil, errors.New("feishu channel requires an approval payload")
+	}
+	return feishuBody(endpoint, feishuCard(*approval, false), now)
+}
+
+// testBody 发送一张示例举报卡片：样式与真实审批卡片一致，按钮只打开版主工作台。
+func (feishuChannel) testBody(endpoint pageConfig.HttpNotifyEndpoint, baseURI string, now time.Time) ([]byte, error) {
+	return feishuBody(endpoint, feishuCard(sampleApproval(baseURI, now), true), now)
+}
+
+// sampleApproval 「测试发送」用的示例举报：不对应站内真实内容，动作只指向版主工作台。
+func sampleApproval(baseURI string, now time.Time) ApprovalPayload {
+	sample := ApprovalPayload{BaseURI: baseURI, Approval: Approval{
+		ID: "test", Kind: ApprovalKindReport, TargetType: "post", TargetID: 1, ReportID: 1,
+		Reason: "spam", Title: "示例话题：期中复习资料汇总",
+		Excerpt:       "这是一条示例回复，用来预览审批卡片在群里的样子，不对应站内的真实内容。",
+		Author:        &ApprovalAuthor{DisplayName: "示例用户"},
+		Categories:    []string{"学习交流"},
+		Note:          "示例举报说明：疑似广告引流。",
+		CreatedAt:     now.Format(time.RFC3339),
+		ModerationURL: "/moderation?tab=reports",
+	}}
+	sample.Approval.Actions = []ApprovalAction{
+		{Action: ApprovalActionBan, URL: sample.Approval.ModerationURL},
+		{Action: ApprovalActionDismiss, URL: sample.Approval.ModerationURL},
+	}
+	return sample
+}
+
+func feishuBody(endpoint pageConfig.HttpNotifyEndpoint, card map[string]any, now time.Time) ([]byte, error) {
+	body := map[string]any{
+		"msg_type": "interactive",
+		"card":     card,
+	}
+	// 开启飞书“签名校验”时，请求体携带 timestamp 与 sign（飞书要求一小时内）。
+	if endpoint.Secret != "" {
+		timestamp := strconv.FormatInt(now.Unix(), 10)
+		body["timestamp"] = timestamp
+		body["sign"] = feishuSign(timestamp, endpoint.Secret)
+	}
+	return json.Marshal(body)
+}
+
+func (feishuChannel) buildRequest(endpoint pageConfig.HttpNotifyEndpoint, _ string, _ string, timestamp int64, body []byte) (*http.Request, error) {
+	// Retry bodies may outlive Feishu's one-hour signing window or a secret
+	// rotation. Sign each HTTP attempt with its current endpoint configuration.
+	var payload map[string]json.RawMessage
+	if err := json.Unmarshal(body, &payload); err != nil {
+		return nil, err
+	}
+	delete(payload, "timestamp")
+	delete(payload, "sign")
+	if endpoint.Secret != "" {
+		value := strconv.FormatInt(timestamp, 10)
+		encodedTimestamp, err := json.Marshal(value)
+		if err != nil {
+			return nil, err
+		}
+		encodedSign, err := json.Marshal(feishuSign(value, endpoint.Secret))
+		if err != nil {
+			return nil, err
+		}
+		payload["timestamp"], payload["sign"] = encodedTimestamp, encodedSign
+	}
+	body, err := json.Marshal(payload)
+	if err != nil {
+		return nil, err
+	}
+	return newJSONPost(endpoint, body)
+}
+
+// checkResponse 飞书常以 HTTP 200 返回业务失败（签名错误、频控、关键词不匹配等），
+// 必须解析 body：code（或旧版 StatusCode）非 0、或返回体无法识别都计为失败。
+func (feishuChannel) checkResponse(resp *http.Response) error {
+	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
+		return errors.New(resp.Status)
+	}
+	raw, err := io.ReadAll(io.LimitReader(resp.Body, 64<<10))
+	if err != nil {
+		return fmt.Errorf("feishu response read failed: %w", err)
+	}
+	var result struct {
+		Code          *int   `json:"code"`
+		Msg           string `json:"msg"`
+		StatusCode    *int   `json:"StatusCode"`
+		StatusMessage string `json:"StatusMessage"`
+	}
+	if err := json.Unmarshal(raw, &result); err != nil {
+		return errors.New("feishu response is not JSON")
+	}
+	switch {
+	case result.Code != nil && *result.Code != 0:
+		return fmt.Errorf("feishu code %d: %s", *result.Code, SafeText(result.Msg, 120))
+	case result.Code != nil:
+		return nil
+	case result.StatusCode != nil && *result.StatusCode != 0:
+		return fmt.Errorf("feishu code %d: %s", *result.StatusCode, SafeText(result.StatusMessage, 120))
+	case result.StatusCode != nil:
+		return nil
+	default:
+		return errors.New("feishu response missing code")
+	}
+}
+
+// feishuSign 飞书自定义机器人签名：以 timestamp+"\n"+secret 为 HMAC-SHA256 密钥、
+// 空串为消息，结果 base64。
+func feishuSign(timestamp string, secret string) string {
+	mac := hmac.New(sha256.New, []byte(timestamp+"\n"+secret))
+	return base64.StdEncoding.EncodeToString(mac.Sum(nil))
+}
+
+// approvalTargetLabels / approvalReasonLabels / approvalActionLabels 审批摘要的中文文案，
+// 飞书卡片与 AstrBot 文本共用。
+var approvalTargetLabels = map[string]string{
+	"topic":         "话题",
+	"post":          "回复",
+	"chat_message":  "私信",
+	"course_review": "课程评价",
+}
+
+var approvalReasonLabels = map[string]string{
+	"spam":           "垃圾广告",
+	"abuse":          "辱骂/人身攻击",
+	"illegal":        "违法违规",
+	"irrelevant":     "无关内容",
+	"other":          "其他",
+	"sensitive_word": "命中敏感词",
+	"ai":             "AI 审核存疑",
+}
+
+var approvalActionLabels = map[string]string{
+	ApprovalActionApprove: "通过并公开",
+	ApprovalActionReject:  "拒绝",
+	ApprovalActionBan:     "封禁并结案",
+	ApprovalActionHide:    "隐藏评价并结案",
+	ApprovalActionDismiss: "驳回举报",
+}
+
+// feishuActionStyle 快捷按钮的样式与图标（文案见 approvalActionLabels）。图标 token 均取自飞书卡片图标库
+// （https://open.feishu.cn/document/feishu-cards/enumerations-for-icons），
+// 写错的 token 在客户端静默不显示，新增时须逐个核对。
+type feishuActionStyle struct {
+	buttonType string
+	icon       string
+}
+
+var feishuActionStyles = map[string]feishuActionStyle{
+	ApprovalActionApprove: {"primary_filled", "yes_outlined"},
+	ApprovalActionReject:  {"danger", "no_outlined"},
+	ApprovalActionBan:     {"danger", "ban_outlined"},
+	ApprovalActionHide:    {"danger", "invisible_outlined"},
+	ApprovalActionDismiss: {"default", "close_outlined"},
+}
+
+// feishuCard 渲染 schema 2.0 卡片：标题栏（图标、编号、最多 3 个标签）→ 内容标题 →
+// 灰底摘要 → 两栏元信息 → 操作按钮 → 灰色说明。用户可控文本一律走 plain_text
+// （不解析 Markdown、链接与 <at> 提及），避免恶意内容破坏卡片或 @ 全员。test 为管理端
+// 「测试发送」的示例卡片：样式与真实卡片一致，按钮只打开版主工作台。
+func feishuCard(payload ApprovalPayload, test bool) map[string]any {
+	a := payload.Approval
+	target := approvalTargetLabels[a.TargetType]
+	if target == "" {
+		target = SafeText(a.TargetType, 20)
+	}
+	title, template, headerIcon, reasonColor := "待人工审核 · "+target, "orange", "approval_outlined", "orange"
+	if a.Kind == ApprovalKindReport {
+		title, template, headerIcon, reasonColor = "新举报 · "+target, "red", "report_outlined", "red"
+	} else if a.Kind == ApprovalKindAppeal {
+		title, template, headerIcon = "新申诉 · "+target, "blue", "feedback_outlined"
+	}
+	reason := approvalReasonLabels[a.Reason]
+	if reason == "" {
+		reason = SafeText(a.Reason, 20)
+	}
+
+	tags := make([]map[string]any, 0, 3)
+	addTag := func(text, color string) {
+		if text != "" && len(tags) < 3 {
+			tags = append(tags, map[string]any{"tag": "text_tag", "text": feishuPlain(text), "color": color})
+		}
+	}
+	if test {
+		addTag("测试", "blue")
+	}
+	addTag(reason, reasonColor)
+	if a.Edited {
+		addTag("编辑后", "wathet")
+	}
+	if a.Anonymous {
+		addTag("匿名", "neutral")
+	}
+
+	subtitle := approvalSubject(a, target)
+	header := map[string]any{
+		"template": template,
+		"title":    feishuPlain(title),
+		"subtitle": feishuPlain(subtitle),
+		"icon":     feishuIcon(headerIcon, template),
+	}
+	if len(tags) > 0 {
+		header["text_tag_list"] = tags
+	}
+
+	elements := make([]map[string]any, 0, 8)
+	if heading := SafeText(a.Title, 100); heading != "" {
+		elements = append(elements, map[string]any{
+			"tag":  "div",
+			"text": map[string]any{"tag": "plain_text", "content": heading, "text_size": "heading", "lines": 2},
+		})
+	}
+	if excerpt := SafeText(a.Excerpt, 200); excerpt != "" {
+		elements = append(elements, map[string]any{
+			"tag":              "column_set",
+			"background_style": "grey-50",
+			"columns": []map[string]any{{
+				"tag": "column", "width": "weighted", "weight": 1, "padding": "8px 12px 8px 12px",
+				"elements": []map[string]any{{
+					"tag":  "div",
+					"text": map[string]any{"tag": "plain_text", "content": excerpt, "lines": 4},
+				}},
+			}},
+		})
+	}
+
+	author := ""
+	switch {
+	case a.Anonymous:
+		author = "匿名（不披露身份）"
+	case a.Author != nil:
+		author = SafeText(a.Author.DisplayName, 40)
+	}
+	fields := make([]map[string]any, 0, 3)
+	if author != "" {
+		fields = append(fields, feishuField("member_outlined", "作者", author))
+	}
+	if len(a.Categories) > 0 {
+		fields = append(fields, feishuField("tag_outlined", "分类", SafeText(strings.Join(a.Categories, "、"), 40)))
+	}
+	if created := approvalTime(a.CreatedAt); created != "" {
+		fields = append(fields, feishuField("time_outlined", "时间", created))
+	}
+	if len(fields) == 1 {
+		elements = append(elements, fields[0])
+	} else if len(fields) > 1 {
+		// 两栏交替排布元信息；bisect 在窄屏仍保持两栏等分。
+		var left, right []map[string]any
+		for i, field := range fields {
+			if i%2 == 0 {
+				left = append(left, field)
+			} else {
+				right = append(right, field)
+			}
+		}
+		elements = append(elements, map[string]any{
+			"tag":                "column_set",
+			"flex_mode":          "bisect",
+			"horizontal_spacing": "12px",
+			"columns": []map[string]any{
+				{"tag": "column", "width": "weighted", "weight": 1, "elements": left},
+				{"tag": "column", "width": "weighted", "weight": 1, "elements": right},
+			},
+		})
+	}
+	if note := SafeText(a.Note, 300); note != "" {
+		elements = append(elements, feishuField("chat_outlined", "举报说明", note))
+	}
+	if a.TargetType == "chat_message" {
+		elements = append(elements, feishuNote("lock_outlined", "私信内容不会发到外部群，请在版主工作台查看证据并处理。"))
+	}
+	if a.Kind == ApprovalKindAppeal {
+		elements = append(elements, feishuNote("lock_outlined", appealPrivacyNote))
+	}
+
+	base := strings.TrimRight(payload.BaseURI, "/")
+	if base == "" {
+		elements = append(elements, feishuNote("warning_outlined", "站点地址未配置，无法生成处理链接，请在版主工作台处理。"))
+	} else {
+		buttons := make([]map[string]any, 0, len(a.Actions)+1)
+		for _, action := range a.Actions {
+			style, ok := feishuActionStyles[action.Action]
+			if !ok || action.URL == "" {
+				continue
+			}
+			buttons = append(buttons, feishuButton(approvalActionLabel(a.Kind, action.Action), style.buttonType, style.icon, base+action.URL))
+		}
+		if a.ModerationURL != "" {
+			buttons = append(buttons, feishuButton("打开版主工作台", "default", "admin_outlined", base+a.ModerationURL))
+		}
+		if len(buttons) > 0 {
+			columns := make([]map[string]any, 0, len(buttons))
+			for _, button := range buttons {
+				columns = append(columns, map[string]any{"tag": "column", "width": "auto", "elements": []map[string]any{button}})
+			}
+			// flow：窄屏（手机）放不下时按钮自动换行，而不是被压缩。
+			elements = append(elements, map[string]any{
+				"tag": "column_set", "flex_mode": "flow", "horizontal_spacing": "8px", "columns": columns,
+			})
+		}
+		switch {
+		case test:
+			elements = append(elements, feishuNote("info_outlined", "这是一条测试消息，内容仅为示例；按钮只会打开版主工作台。"))
+		case len(a.Actions) > 0:
+			elements = append(elements, feishuNote("safe_outlined", "按钮会先打开本站确认页，登录且有审核权限才能处理。"))
+		}
+	}
+
+	summary := title
+	if a.Title != "" {
+		summary += "：" + SafeText(a.Title, 40)
+	}
+	return map[string]any{
+		"schema": "2.0",
+		"config": map[string]any{
+			"update_multi": true,
+			"summary":      map[string]any{"content": summary},
+		},
+		"header": header,
+		"body": map[string]any{
+			"direction": "vertical",
+			"elements":  elements,
+		},
+	}
+}
+
+// approvalLocation 审批消息显示时间用的时区。站点没有时区设置，服务器（容器）常是 UTC，
+// 而版主都在上海，与 campusservice 一样固定为 UTC+8。
+var approvalLocation = time.FixedZone("Asia/Shanghai", 8*3600)
+
+// approvalTime 把 RFC3339 时间转为 UTC+8 的「2006-01-02 15:04」，无法解析时原样截断。
+func approvalTime(value string) string {
+	if value == "" {
+		return ""
+	}
+	if parsed, err := time.Parse(time.RFC3339, value); err == nil {
+		return parsed.In(approvalLocation).Format("2006-01-02 15:04")
+	}
+	return SafeText(value, 40)
+}
+
+func feishuPlain(content string) map[string]any {
+	return map[string]any{"tag": "plain_text", "content": content}
+}
+
+// feishuIcon 图标库图标；color 为空时继承所在组件（如按钮文字）的颜色。
+func feishuIcon(token, color string) map[string]any {
+	icon := map[string]any{"tag": "standard_icon", "token": token}
+	if color != "" {
+		icon["color"] = color
+	}
+	return icon
+}
+
+// feishuField 带图标的「标签：值」一行。
+func feishuField(icon, label, value string) map[string]any {
+	return map[string]any{
+		"tag":  "div",
+		"icon": feishuIcon(icon, "grey"),
+		"text": map[string]any{"tag": "plain_text", "content": label + "：" + value, "lines": 3},
+	}
+}
+
+// feishuNote 灰色小字说明（2.0 移除了 note 组件，官方建议用 notation 字号的文本代替）。
+func feishuNote(icon, content string) map[string]any {
+	return map[string]any{
+		"tag":  "div",
+		"icon": feishuIcon(icon, "grey"),
+		"text": map[string]any{"tag": "plain_text", "content": content, "text_size": "notation", "text_color": "grey"},
+	}
+}
+
+func feishuButton(label, buttonType, icon, url string) map[string]any {
+	return map[string]any{
+		"tag":       "button",
+		"type":      buttonType,
+		"size":      "medium",
+		"text":      feishuPlain(label),
+		"icon":      feishuIcon(icon, ""),
