+	// Check that mention links were generated properly for all 3 posts
+	if !strings.Contains(p1.RenderedHTML, `/u/`+fmt.Sprint(u1.Id)) {
+		t.Fatalf("p1 missing mention link: %s", p1.RenderedHTML)
+	}
+	if !strings.Contains(p2.RenderedHTML, `/u/`+fmt.Sprint(u1.Id)) || !strings.Contains(p2.RenderedHTML, `/u/`+fmt.Sprint(u2.Id)) {
+		t.Fatalf("p2 missing mention link: %s", p2.RenderedHTML)
+	}
+	if !strings.Contains(p3.RenderedHTML, `/u/`+fmt.Sprint(u2.Id)) {
+		t.Fatalf("p3 missing mention link: %s", p3.RenderedHTML)
+	}
+
+	// With batch resolution, exactly 1 query is executed instead of 3
+	if userQueryCount > 1 {
+		t.Fatalf("expected at most 1 user query for batch mention resolution, got %d", userQueryCount)
+	}
+}

diff --git a/apps/gooseforum/app/service/profileprivacyservice/profileprivacyservice.go b/apps/gooseforum/app/service/profileprivacyservice/profileprivacyservice.go
new file mode 100644
index 000000000..c9ef29296
--- /dev/null
+++ b/apps/gooseforum/app/service/profileprivacyservice/profileprivacyservice.go
@@ -0,0 +1,153 @@
+// Package profileprivacyservice decides which profile aggregates a viewer may
+// see. It hides profile summaries only: topics, replies and relationships stay
+// reachable through their ordinary forum routes.
+package profileprivacyservice
+
+import (
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/userActivities"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/userFollow"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/users"
+)
+
+// Profile sections, named after their settings keys.
+const (
+	SectionTopics    = "profileTopics"
+	SectionActivity  = "profileActivity"
+	SectionLikes     = "profileLikes"
+	SectionFollowing = "followingList"
+	SectionFollowers = "followersList"
+)
+
+// Reasons tell a viewer what would reveal a hidden section. Blocks and storage
+// failures use the generic private reason so neither is disclosed.
+const (
+	ReasonSignIn    = "signin"
+	ReasonFollowers = "followers"
+	ReasonMutual    = "mutual"
+	ReasonPrivate   = "private"
+)
+
+type Decision struct {
+	Visible bool
+	// Reason is set only when the section is hidden.
+	Reason string
+	// Audience is the configured audience, exposed to the owner only.
+	Audience string
+}
+
+type View struct {
+	decisions map[string]Decision
+}
+
+func (v View) Section(section string) Decision { return v.decisions[section] }
+func (v View) Visible(section string) bool     { return v.decisions[section].Visible }
+
+// TimelineActions lists the activity types this viewer may see. Posts, likes
+// and follows each also obey their own section so the timeline cannot reveal
+// a hidden list indirectly.
+func (v View) TimelineActions() []int {
+	if !v.Visible(SectionActivity) {
+		return nil
+	}
+	actions := []int{int(userActivities.ActionSignUp), int(userActivities.ActionComment)}
+	if v.Visible(SectionTopics) {
+		actions = append(actions, int(userActivities.ActionPost))
+	}
+	if v.Visible(SectionLikes) {
+		actions = append(actions, int(userActivities.ActionLike))
+	}
+	if v.Visible(SectionFollowing) {
+		actions = append(actions, int(userActivities.ActionFollow))
+	}
+	return actions
+}
+
+var sections = []string{SectionTopics, SectionActivity, SectionLikes, SectionFollowing, SectionFollowers}
+
+func audienceOf(settings users.PrivacySettingsEntity, section string) string {
+	switch section {
+	case SectionTopics:
+		return settings.ProfileTopics
+	case SectionActivity:
+		return settings.ProfileActivity
+	case SectionLikes:
+		return settings.ProfileLikes
+	case SectionFollowing:
+		return settings.FollowingList
+	default:
+		return settings.FollowersList
+	}
+}
+
+// Evaluate resolves every section for one viewer before any profile query
+// runs. The owner always sees everything; read failures hide every section.
+func Evaluate(ownerID, viewerID uint64) View {
+	view := View{decisions: make(map[string]Decision, len(sections))}
+	settings, err := users.GetPrivacySettings(ownerID)
+	if viewerID != 0 && viewerID == ownerID {
+		for _, section := range sections {
+			decision := Decision{Visible: true}
+			if err == nil {
+				decision.Audience = audienceOf(settings, section)
+			}
+			view.decisions[section] = decision
+		}
+		return view
+	}
+	if err != nil {
+		for _, section := range sections {
+			view.decisions[section] = Decision{Reason: ReasonPrivate}
+		}
+		return view
+	}
+	restricted := false
+	for _, section := range sections {
+		restricted = restricted || audienceOf(settings, section) != users.AudienceEveryone
+	}
+	var blocked, viewerFollows, ownerFollows bool
+	if restricted && viewerID != 0 {
+		var blockErr, followErr error
+		blocked, blockErr = users.InteractionBlocked(viewerID, ownerID)
+		viewerFollows, ownerFollows, followErr = userFollow.MutualState(viewerID, ownerID)
+		// Fail closed: an unknown relationship never grants follower access.
+		blocked = blocked || blockErr != nil || followErr != nil
+	}
+	for _, section := range sections {
+		view.decisions[section] = decide(audienceOf(settings, section), viewerID != 0, blocked, viewerFollows, ownerFollows)
+	}
+	return view
+}
+
+func decide(audience string, signedIn, blocked, viewerFollows, ownerFollows bool) Decision {
+	switch {
+	case audience == users.AudienceEveryone:
+		return Decision{Visible: true}
+	case blocked || audience == users.AudienceSelf:
+		return Decision{Reason: ReasonPrivate}
+	case audience == users.AudienceMembers:
+		if signedIn {
+			return Decision{Visible: true}
+		}
+		return Decision{Reason: ReasonSignIn}
+	case audience == users.AudienceFollowers:
+		if viewerFollows {
+			return Decision{Visible: true}
+		}
+		return Decision{Reason: ReasonFollowers}
+	case audience == users.AudienceMutual:
+		if viewerFollows && ownerFollows {
+			return Decision{Visible: true}
+		}
+		return Decision{Reason: ReasonMutual}
+	}
+	// Unknown stored values fail closed.
+	return Decision{Reason: ReasonPrivate}
+}
+
+func Get(userID uint64) (users.PrivacySettingsEntity, error) {
+	return users.GetPrivacySettings(userID)
+}
+
+func Update(userID uint64, update users.PrivacySettingsUpdate) (users.PrivacySettingsEntity, error) {
+	return users.UpdatePrivacySettings(userID, update)
+}

diff --git a/apps/gooseforum/app/service/profileprivacyservice/profileprivacyservice_test.go b/apps/gooseforum/app/service/profileprivacyservice/profileprivacyservice_test.go
new file mode 100644
index 000000000..29fc08394
--- /dev/null
+++ b/apps/gooseforum/app/service/profileprivacyservice/profileprivacyservice_test.go
@@ -0,0 +1,73 @@
+package profileprivacyservice
+
+import (
+	"slices"
+	"testing"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/userActivities"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/users"
+)
+
+func TestDecideAudienceMatrix(t *testing.T) {
+	type viewer struct{ signedIn, blocked, follows, followedBack bool }
+	guest := viewer{}
+	stranger := viewer{signedIn: true}
+	follower := viewer{signedIn: true, follows: true}
+	followedOnly := viewer{signedIn: true, followedBack: true}
+	mutual := viewer{signedIn: true, follows: true, followedBack: true}
+	blockedMutual := viewer{signedIn: true, blocked: true, follows: true, followedBack: true}
+	cases := []struct {
+		audience string
+		viewer   viewer
+		visible  bool
+		reason   string
+	}{
+		{users.AudienceEveryone, guest, true, ""},
+		{users.AudienceEveryone, blockedMutual, true, ""},
+		{users.AudienceMembers, guest, false, ReasonSignIn},
+		{users.AudienceMembers, stranger, true, ""},
+		{users.AudienceMembers, blockedMutual, false, ReasonPrivate},
+		{users.AudienceFollowers, guest, false, ReasonFollowers},
+		{users.AudienceFollowers, stranger, false, ReasonFollowers},
+		{users.AudienceFollowers, followedOnly, false, ReasonFollowers},
+		{users.AudienceFollowers, follower, true, ""},
+		{users.AudienceFollowers, blockedMutual, false, ReasonPrivate},
+		{users.AudienceMutual, follower, false, ReasonMutual},
+		{users.AudienceMutual, followedOnly, false, ReasonMutual},
+		{users.AudienceMutual, mutual, true, ""},
+		{users.AudienceMutual, blockedMutual, false, ReasonPrivate},
+		{users.AudienceSelf, mutual, false, ReasonPrivate},
+		{"unknown", mutual, false, ReasonPrivate},
+	}
+	for _, tc := range cases {
+		got := decide(tc.audience, tc.viewer.signedIn, tc.viewer.blocked, tc.viewer.follows, tc.viewer.followedBack)
+		if got.Visible != tc.visible || got.Reason != tc.reason || got.Audience != "" {
+			t.Errorf("decide(%s, %+v) = %+v, want visible=%v reason=%q", tc.audience, tc.viewer, got, tc.visible, tc.reason)
+		}
+	}
+}
+
+func TestTimelineActionsFollowEachSection(t *testing.T) {
+	view := func(hidden ...string) View {
+		v := View{decisions: map[string]Decision{}}
+		for _, section := range sections {
+			v.decisions[section] = Decision{Visible: !slices.Contains(hidden, section)}
+		}
+		return v
+	}
+	post, like, follow := int(userActivities.ActionPost), int(userActivities.ActionLike), int(userActivities.ActionFollow)
+	if got := view(SectionActivity).TimelineActions(); len(got) != 0 {
+		t.Fatalf("hidden activity still lists %v", got)
+	}
+	all := view().TimelineActions()
+	for _, action := range []int{post, like, follow, int(userActivities.ActionComment), int(userActivities.ActionSignUp)} {
+		if !slices.Contains(all, action) {
+			t.Fatalf("public timeline misses action %d", action)
+		}
+	}
+	for section, action := range map[string]int{SectionTopics: post, SectionLikes: like, SectionFollowing: follow} {
+		if slices.Contains(view(section).TimelineActions(), action) {
+			t.Fatalf("hidden %s still lists action %d", section, action)
+		}
+	}
+}

