+package publicationservice
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"strings"
+	"time"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/markdown2html"
+	identity "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/anonymousIdentity"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/eventNotification"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/moderationAppeals"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/moderationDecision"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/postRevisions"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/posts"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/taskQueue"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topicCategoryIndex"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/userActivities"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/userStatistics"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/users"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/hotdataserve"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/agentcommentservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/agenteventservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/botcontentservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/fileusageservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/llmsservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/moderationservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/postservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/realtimeservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/searchservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/topicpolicyservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/unreadservice"
+	"gorm.io/gorm"
+	"gorm.io/gorm/clause"
+)
+
+// RunReviewTask is restart-safe. The task carries only a revision ID, so deleting
+// retained content also removes the text an unprocessed job could otherwise use.
+func RunReviewTask(ctx context.Context, task *taskQueue.Entity) error {
+	var payload Task
+	if err := json.Unmarshal([]byte(task.TaskJson), &payload); err != nil {
+		return err
+	}
+	var revision postRevisions.Entity
+	conn := db.ConnectContext(ctx)
+	if err := conn.First(&revision, payload.RevisionId).Error; errors.Is(err, gorm.ErrRecordNotFound) {
+		return nil
+	} else if err != nil {
+		return err
+	}
+	var post posts.Entity
+	if err := conn.First(&post, revision.PostId).Error; errors.Is(err, gorm.ErrRecordNotFound) {
+		return nil
+	} else if err != nil {
+		return err
+	}
+	var topic topics.Entity
+	if err := conn.First(&topic, post.TopicId).Error; errors.Is(err, gorm.ErrRecordNotFound) {
+		return nil
+	} else if err != nil {
+		return err
+	}
+	if post.LatestRevisionId != revision.Id || revision.ProcessStatus != posts.ProcessStatusPending || revision.ReviewedAt != nil || !available(topic, post) {
+		return nil
+	}
+	subject, id := moderationDecision.SubjectPost, post.Id
+	if post.PostNo == 1 {
+		subject, id = moderationDecision.SubjectTopic, topic.Id
+	}
+	action, reason := moderationDecision.ActionAllow, ""
+	cfg := hotdataserve.GetSecuritySettingsConfigCache()
+	text := revision.Title + "\n" + revision.Content
+	if words := moderationservice.FindSensitiveWordsInTextsWithConfig([]string{text, markdown2html.ExtractVisibleText(text)}, cfg); len(words) > 0 {
+		action, reason = moderationDecision.ActionBlock, "内容包含不符合发布规则的词语，请修改后重新提交。"
+		if cfg.SensitiveAction == "review" {
+			action, reason = moderationDecision.ActionReview, "等待人工审核"
+		}
+	} else if decision := moderationservice.EvaluateSubmission(ctx, moderationservice.AIContentInput{AuthorID: post.UserId, SubjectType: subject, SubjectID: id, Title: revision.Title, Content: revision.Content, Gallery: revision.ImageUrls}); decision != nil {
+		decision.RevisionId = revision.Id
+		decision.AppliedAction = moderationDecision.ActionReview
+		if err := moderationDecision.Create(decision); err != nil {
+			return err
+		}
+		action = decision.FinalAction
+		if action == moderationDecision.ActionBlock {
+			reason = "内容不符合本站发布规则，请修改后重新提交。"
+		}
+		if decision.ErrorKind == "external_image_blocked" {
+			reason = "请将站外图片上传到本站后重新提交。"
+		}
+		if action == moderationDecision.ActionReview {
+			reason = "等待人工审核"
+		}
+	}
+	if ctx.Err() != nil {
+		return ctx.Err()
+	}
+	err := Review(ctx, revision.Id, action, reason, 0)
+	if errors.Is(err, ErrUnavailable) {
+		return nil
+	}
+	return err
+}
+
+func available(topic topics.Entity, post posts.Entity) bool {
+	return topic.Id != 0 && post.Id != 0 && topic.Status == 1 && topic.VisibilityStatus == topics.VisibilityActive && post.VisibilityStatus == posts.VisibilityActive && !topic.DeletedAt.Valid && !post.DeletedAt.Valid && (topic.TopicType != topics.TopicTypeWiki || post.PostNo > 1)
+}
+
+// Review compares the exact revision under the post lock. Human decisions and
+// worker retries share this path; a terminal decision has exactly one notice.
+func Review(ctx context.Context, revisionID uint64, action, reason string, actorID uint64) error {
+	return review(ctx, revisionID, action, reason, actorID, 0)
+}
+
+func review(ctx context.Context, revisionID uint64, action, reason string, actorID, appealID uint64) error {
+	var stale bool
+	var topic topics.Entity
+	var post posts.Entity
+	var oldCategories []uint64
+	// Rendering can resolve stickers/mentions via the DB; do it before locking.
+	// This also avoids publishing an HTML cache produced by an older renderer.
+	var approvedHTML string
+	if action == moderationDecision.ActionAllow {
+		var candidate postRevisions.Entity
+		if err := db.ConnectContext(ctx).First(&candidate, revisionID).Error; err != nil {
+			return err
+		}
+		approvedHTML = postservice.RenderPostHTML(candidate.Content)
+	}
+	err := db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		var revision postRevisions.Entity
+		if err := tx.First(&revision, revisionID).Error; err != nil {
+			return err
+		}
+		if err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).First(&post, revision.PostId).Error; err != nil {
+			return err
+		}
+		if err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).First(&topic, post.TopicId).Error; err != nil {
+			return err
+		}
+		// Source-linked Agent writes acquire content before participant rows.
+		// Persona governance must follow the same order, including delayed approval.
+		if action == moderationDecision.ActionAllow {
+			if err := identity.ValidateWriterTx(tx, post.UserId, post.PersonaUID); err != nil {
+				return err
+			}
+		}
+		oldCategories = append(oldCategories, topic.CategoryIds...)
+		// Re-read the revision after acquiring the post lock.
+		if err := tx.First(&revision, revisionID).Error; err != nil {
+			return err
+		}
+		if appealID != 0 {
+			var appeal moderationAppeals.Entity
+			if err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).First(&appeal, appealID).Error; err != nil {
+				return err
+			}
+			if appeal.PostId != post.Id || appeal.RevisionId != revisionID || appeal.Status != moderationAppeals.Pending {
+				return ErrAppealProcessed
+			}
+			allowed, err := canReviewAppealTx(tx, actorID, topic, post, revision)
+			if err != nil {
+				return err
+			}
+			if !allowed {
+				return ErrAppealPermission
+			}
+			parentAvailable := true
+			if post.PostNo > 1 {
+				if err := appealParentPublicTx(tx, topic); errors.Is(err, ErrUnavailable) || errors.Is(err, gorm.ErrRecordNotFound) {
+					parentAvailable = false
+				} else if err != nil {
+					return err
+				}
+			}
+			if !appealable(topic, post, revision) || !parentAvailable {
+				stale = true
+				if err := tx.Model(&appeal).Updates(map[string]any{"status": moderationAppeals.Stale, "reviewed_at": time.Now(), "review_actor_id": actorID}).Error; err != nil {
+					return err
+				}
+				// 作者仍需得知结论：失效的申诉同样发一条结果通知（独立模板，不与“被驳回”混淆）。
+				return enqueueReviewNotice(tx, revision, topic, post, eventNotification.EventTypeReviewRejected, eventNotification.TemplateAppealStale, Effect{RevisionId: revisionID, NotificationOnly: true})
+			}
+			if action == moderationDecision.ActionAllow {
+				author, err := users.GetInteractionUserTx(tx, post.UserId)
+				if err != nil {
+					return err
+				}
+				if author.IsFrozen == users.StatusFrozen {
+					return ErrAppealAuthorFrozen
+				}
+			}
+			if action == moderationDecision.ActionBlock {
+				if err := decideAppealTx(tx, appealID, actorID, false, reason); err != nil {
+					return err
+				}
+				return enqueueReviewNotice(tx, revision, topic, post, eventNotification.EventTypeReviewRejected, eventNotification.TemplateAppealRejected, Effect{RevisionId: revisionID, NotificationOnly: true})
+			}
+		}
+		expectedStatus := posts.ProcessStatusPending
+		if appealID != 0 {
+			expectedStatus = posts.ProcessStatusBlocked
+		}
+		if post.LatestRevisionId != revisionID || revision.ProcessStatus != expectedStatus || !available(topic, post) {
+			return ErrUnavailable
+		}
+		if appealID == 0 && (post.ProcessStatus == posts.ProcessStatusBlocked || topic.ProcessStatus == topics.ProcessStatusBlocked) {
+			return ErrUnavailable
+		}
+		if post.PostNo > 1 && topic.ProcessStatus != topics.ProcessStatusNormal {
+			return ErrUnavailable
+		}
+		if action == moderationDecision.ActionReview {
+			// A pending revision with ReviewedAt has already been routed to a human.
+			// The timestamp and notification commit together under the post lock.
+			if revision.ReviewedAt != nil {
+				return nil
+			}
+			if strings.TrimSpace(reason) == "" {
+				reason = "等待人工审核"
+			}
+			if err := tx.Model(&revision).Updates(map[string]any{"review_reason": reason, "reviewed_at": time.Now()}).Error; err != nil {
+				return err
+			}
+			return enqueueReviewNotice(tx, revision, topic, post, eventNotification.EventTypeReviewPending, "", Effect{RevisionId: revisionID, NotificationOnly: true, ReviewRequested: true})
+		}
+		if actorID == 0 && revision.ReviewedAt != nil {
+			return ErrUnavailable
+		}
+		if action != moderationDecision.ActionAllow && action != moderationDecision.ActionBlock {
+			return errors.New("invalid review action")
+		}
+		var capturePlan *agenteventservice.WriteCapturePlan
+		if action == moderationDecision.ActionAllow && revision.EditorId != 0 && revision.EditorId != post.UserId {
+			author, err := users.GetInteractionUserTx(tx, post.UserId)
+			if err != nil {
+				return err
+			}
+			if author.IsBot() {
+				capturePlan, err = botcontentservice.CheckPublicationTx(tx, revision.EditorId, post, topic)
+				if errors.Is(err, botcontentservice.ErrUnavailable) || errors.Is(err, agenteventservice.ErrInaccessible) {
+					action, reason = moderationDecision.ActionBlock, "Agent 维护权限已失效，请恢复权限后重新提交。"
+				} else if err != nil {
+					return err
+				}
+			}
+		}
+		// Submission may precede an operator ban. Recheck only first publication
+		// of bot replies; an existing public reply remains editable.
+		if action == moderationDecision.ActionAllow && post.PostNo > 1 && post.PublishedRevisionId == 0 && post.ProcessStatus != posts.ProcessStatusNormal {
+			author, err := users.GetInteractionUserTx(tx, post.UserId)
+			if err != nil {
+				return err
+			}
+			if author.IsBot() {
+				// Match Agent writes: content -> participants -> global policy.
+				// Holding policy before capture could deadlock a concurrent write
+				// on another topic that already holds this bot's participant rows.
+				capturePlan, err = agenteventservice.PrepareWriteCaptureTx(tx, post.UserId, topic.Id, "")
+				if err != nil {
+					return err
+				}
+				if err := agentcommentservice.CheckNewCommentTx(tx, topic.Id); errors.Is(err, agentcommentservice.ErrAgentCommentDisabled) {
+					action, reason = moderationDecision.ActionBlock, "该话题或站点已禁止机器人回复。"
+				} else if err != nil {
+					return err
+				}
+			}
+		}
+		// Newly submitted replies must still be allowed when they become public.
+		// Keep existing public replies editable; turn a revoked publication into
+		// a recorded terminal rejection rather than an endlessly retried job.
+		if action == moderationDecision.ActionAllow && post.PostNo > 1 && post.PublishedRevisionId == 0 && post.ProcessStatus != posts.ProcessStatusNormal {
+			if err := topicpolicyservice.CheckReplyTx(tx, topic, post.UserId); errors.Is(err, topicpolicyservice.ErrAgentRepliesDisabled) {
+				action, reason = moderationDecision.ActionBlock, "话题作者已禁止机器人回复。"
+			} else if err != nil {
+				return err
+			}
+		}
+		status := posts.ProcessStatusBlocked
+		if action == moderationDecision.ActionAllow {
+			status = posts.ProcessStatusNormal
+		}
+		if action == moderationDecision.ActionBlock && strings.TrimSpace(reason) == "" {
+			reason = "内容未通过审核，请修改后重新提交。"
+		}
+		now := time.Now()
+		if err := tx.Model(&revision).Updates(map[string]any{"process_status": status, "review_reason": reason, "review_actor_id": actorID, "reviewed_at": now}).Error; err != nil {
+			return err
+		}
+		previous := post.PublishedRevisionId
+		wasPublic := post.ProcessStatus == posts.ProcessStatusNormal && topic.ProcessStatus == topics.ProcessStatusNormal
+		if action == moderationDecision.ActionAllow {
+			revision.ProcessStatus = status
+			revision.RenderedHTML = approvedHTML
+			firstPublication := stampFirstPublic(&post, now, wasPublic)
+			ApplySnapshot(&topic, &post, revision)
+			if post.PostNo == 1 && topic.FirstPublicAt == nil {
+				at := *post.FirstPublicAt
+				topic.FirstPublicAt = &at
+				topic.FirstPublicEstimated = post.FirstPublicEstimated
+				if err := tx.Model(&topics.Entity{}).Where("id = ? AND first_public_at IS NULL", topic.Id).UpdateColumns(map[string]any{"first_public_at": at, "first_public_estimated": topic.FirstPublicEstimated}).Error; err != nil {
+					return err
+				}
+			}
+			if firstPublication {
+				kind := "public_reply"
+				if post.PostNo == 1 {
+					kind = "public_topic"
+				}
+				if err := capturePublicContributionTx(tx, post.UserId, topic.Id, post.Id, kind); err != nil {
+					return err
+				}
+			}
+			post.PublishedRevisionId = revision.Id
+			if err := posts.SaveTx(tx, &post); err != nil {
+				return err
+			}
+			if post.PostNo == 1 {
+				if err := topics.UpdateTopicEditableTx(tx, &topic); err != nil {
+					return err
+				}
+				if err := topicCategoryIndex.ReplaceTopicCategoriesTx(tx, topic.Id, topic.CategoryIds); err != nil {
+					return err
+				}
+			}
+			if err := fileusageservice.PublishRevisionImagesTx(tx, revision.Id, topic.Id, post.Id, post.PostNo == 1); err != nil {
+				return err
+			}
+			// The public projection and durable Agent intent commit together. Effects
+			// may run later or retry without losing or recapturing the publication.
+			if err := agenteventservice.CapturePublicTx(tx, &post, capturePlan); err != nil {
+				return err
+			}
+		} else if !wasPublic {
+			if err := posts.UpdateProcessStatusTx(tx, post.Id, status); err != nil {
+				return err
+			}
+			if post.PostNo == 1 {
+				if err := topics.UpdateProcessStatusTx(tx, topic.Id, status); err != nil {
+					return err
+				}
+			}
+		}
+		if action == moderationDecision.ActionAllow && previous == 0 {
+			activity, subject := userActivities.ActionComment, userActivities.SubjectPost
+			id := post.Id
+			if post.PostNo == 1 {
+				activity, subject, id = userActivities.ActionPost, userActivities.SubjectTopic, topic.Id
+			}
+			recorded, err := userActivities.HasRecordTx(tx, activity, subject, id)
+			if err != nil {
+				return err
+			}
+			if !recorded {
+				if err := userStatistics.RecordPublicationTx(tx, post.UserId, post.PostNo == 1); err != nil {
+					return err
+				}
+			}
+		}
+		if appealID != 0 {
+			if err := decideAppealTx(tx, appealID, actorID, action == moderationDecision.ActionAllow, reason); err != nil {
+				return err
+			}
+		}
+		if actorID == 0 {
+			if err := tx.Model(&moderationDecision.Entity{}).Where("revision_id = ?", revisionID).Update("applied_action", action).Error; err != nil {
+				return err
+			}
+		}
+
+		if err := postservice.RebuildTopicPostStatsTx(tx, topic); err != nil {
+			return err
+		}
+		if err := searchservice.EnqueueTopicSearchTask(tx, topic.Id); err != nil {
+			return err
+		}
+		effect := Effect{RevisionId: revisionID, PreviousRevisionId: previous}
+		if actorID != 0 {
+			human := moderationDecision.HumanRejected
+			if action == moderationDecision.ActionAllow {
+				human = moderationDecision.HumanApproved
+			}
+			if err := tx.Model(&moderationDecision.Entity{}).Where("revision_id = ?", revisionID).Updates(map[string]any{"human_action": human, "human_actor_id": actorID, "human_at": now}).Error; err != nil {
+				return err
+			}
+		}
+		if action == moderationDecision.ActionBlock {
+			effect.NotificationOnly = true
+			return enqueueReviewNotice(tx, revision, topic, post, eventNotification.EventTypeReviewRejected, "", effect)
+		}
+		if actorID != 0 {
+			template := ""
+			if appealID != 0 {
+				template = eventNotification.TemplateAppealApproved
+			}
+			return enqueueReviewNotice(tx, revision, topic, post, eventNotification.EventTypeReviewApproved, template, effect)
+		}
+		return enqueueEffect(tx, effect)
+	})
+	if err == nil && !stale {
+		unreadservice.Invalidate(post.UserId)
+		hotdataserve.InvalidateTopicListCacheForCategories(append(oldCategories, topic.CategoryIds...)...)
+		llmsservice.ClearCache()
+		realtimeservice.DefaultHub.Publish(post.UserId, realtimeservice.Event{Type: realtimeservice.EventContentChanged})
+		realtimeservice.DefaultHub.Publish(post.UserId, realtimeservice.Event{Type: realtimeservice.EventNotificationsChanged})
+	}
+	if stale && err == nil {
+		return ErrAppealStale
+	}
+	return err
+}
+
+// Notifications contain a safe subject snapshot; rejection reasons and full
+// candidates remain in content management, not notification or push payloads.
+// enqueueReviewNotice writes one review result notice; a non-empty template
+// overrides the default copy (appeal outcomes) without adding event types.
+func enqueueReviewNotice(tx *gorm.DB, revision postRevisions.Entity, topic topics.Entity, post posts.Entity, eventType, templateKey string, effect Effect) error {
+	template := eventNotification.TemplateReviewPending
+	if eventType == eventNotification.EventTypeReviewApproved {
+		template = eventNotification.TemplateReviewApproved
+	}
+	subject := strings.TrimSpace(revision.Title)
+	if subject == "" {
+		subject = revision.Content
+	}
+	subject = markdown2html.ExtractVisibleText(subject)
+	if chars := []rune(subject); eventType != eventNotification.EventTypeReviewRejected && len(chars) > 60 {
+		subject = string(chars[:60]) + "…"
+	}
+	payload := eventNotification.NotificationPayload{TemplateKey: template, TopicTitle: subject, TopicId: topic.Id, PostId: post.Id, PostNo: post.PostNo}
+	if eventType == eventNotification.EventTypeReviewRejected {
+		payload.TemplateKey = eventNotification.TemplateReviewRejected
+		payload = eventNotification.RedactReviewRejectedPayload(payload)
+	}
+	if templateKey != "" {
+		payload.TemplateKey = templateKey
+	}
+	notice := eventNotification.Entity{UserId: post.UserId, TopicID: topic.Id, EventType: eventType, Payload: payload}
+	if err := tx.Create(&notice).Error; err != nil {
+		return err
+	}
+	effect.NotificationId = notice.Id
+	return enqueueEffect(tx, effect)
+}
+
+func enqueueEffect(tx *gorm.DB, effect Effect) error {
+	raw, err := json.Marshal(effect)
+	if err != nil {
+		return err
+	}
+	return taskQueue.CreateTx(tx, &taskQueue.Entity{Type: EffectTaskType, TaskJson: string(raw)})
+}
+
+// A legacy public projection has an estimated clock; every genuinely pending
+// first publication starts its clock at approval, and restore never resets it.
+func stampFirstPublic(post *posts.Entity, now time.Time, wasPublic bool) bool {
+	if post.FirstPublicAt != nil {
+		return false
+	}
+	at := now
+	if wasPublic {
+		at = post.CreatedAt
+		post.FirstPublicEstimated = true
+	}
+	post.FirstPublicAt = &at
+	return !wasPublic
+}

diff --git a/apps/gooseforum/app/service/publicationservice/submission.go b/apps/gooseforum/app/service/publicationservice/submission.go
new file mode 100644
index 000000000..9a5881823
--- /dev/null
+++ b/apps/gooseforum/app/service/publicationservice/submission.go
@@ -0,0 +1,211 @@
+// Package publicationservice owns versioned forum submissions and their review.
+// Public rows remain the approved projection; post_revisions owns candidate content.
+package publicationservice
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"time"
+
+	db "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/connect/dbconnect"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/bundles/markdown2html"
+	identity "github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/anonymousIdentity"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/feed"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/postRevisions"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/posts"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/taskQueue"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topicCategoryIndex"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/agenteventservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/fileusageservice"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/service/topicpolicyservice"
+	"gorm.io/gorm"
+	"gorm.io/gorm/clause"
+)
+
+const TaskType = "content-review"
+
+var ErrUnavailable = errors.New("content is no longer available for review")
+
+type Task struct {
+	RevisionId uint64 `json:"revisionId"`
+}
+
+// Submit commits the immutable submission, private attachments and durable job
+// together. An approved public version is never overwritten by a candidate.
+// topic contains proposed metadata for a first post, existing metadata for replies.
+func Submit(ctx context.Context, topic *topics.Entity, post *posts.Entity) error {
+	return SubmitWithHooks(ctx, topic, post, nil, nil)
+}
+
+// SubmitWithHooks keeps Agent credential/policy authorization, idempotency and
+// causal metadata in the same transaction as the pending revision and review
+// task. The before hook runs before any insertion; either hook can roll back all
+// submission effects. Model evaluation remains exclusively in the worker.
+func SubmitWithHooks(ctx context.Context, topic *topics.Entity, post *posts.Entity, before, after func(*gorm.DB) error) error {
+	return SubmitWithEditorHooks(ctx, topic, post, post.UserId, before, after)
+}
+
+// SubmitWithEditorHooks preserves authorship while attributing an authorized maintenance revision.
+func SubmitWithEditorHooks(ctx context.Context, topic *topics.Entity, post *posts.Entity, editorID uint64, before, after func(*gorm.DB) error) error {
+	return db.ConnectContext(ctx).Transaction(func(tx *gorm.DB) error {
+		if before != nil {
+			if err := before(tx); err != nil {
+				return err
+			}
+		}
+		if topic.Id == 0 {
+			topic.ProcessStatus = topics.ProcessStatusPending
+			topic.PostSeq, topic.PostCount = 1, 0
+			if err := topics.CreateTx(tx, topic); err != nil {
+				return err
+			}
+			post.TopicId, post.PostNo = topic.Id, 1
+		}
+		var live posts.Entity
+		if post.Id != 0 {
+			if err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).First(&live, post.Id).Error; err != nil {
+				return err
+			}
+			if live.UserId != post.UserId || live.VisibilityStatus != posts.VisibilityActive {
+				return ErrUnavailable
+			}
+		}
+		var liveTopic topics.Entity
+		if err := tx.Clauses(clause.Locking{Strength: "UPDATE"}).First(&liveTopic, topic.Id).Error; err != nil {
+			return err
+		}
+		if err := identity.ValidateWriterTx(tx, post.UserId, post.PersonaUID); err != nil {
+			return err
+		}
+		if liveTopic.VisibilityStatus != topics.VisibilityActive {
+			return ErrUnavailable
+		}
+		if post.PostNo != 1 && (liveTopic.Status != 1 || liveTopic.ProcessStatus != topics.ProcessStatusNormal) {
+			return ErrUnavailable
+		}
+		if post.Id == 0 {
+			if post.PostNo != 1 {
+				if err := topicpolicyservice.CheckReplyTx(tx, liveTopic, post.UserId); err != nil {
+					return err
+				}
+				no, err := topics.ReservePostSequenceTx(tx, topic.Id)
+				if err != nil {
+					return err
+				}
+				post.PostNo = no
+			}
+			post.ProcessStatus = posts.ProcessStatusPending
+			if err := posts.CreateTx(tx, post); err != nil {
+				return err
+			}
+			live = *post
+			if post.PostNo == 1 {
+				topic.FirstPostId = post.Id
+				if err := topics.SaveTx(tx, topic); err != nil {
+					return err
+				}
+			}
+		} else if live.LatestRevisionId == 0 {
+			// Lazy baseline uses the current row, never MAX(version): legacy history may
+			// contain rejected bodies and does not have complete topic metadata.
+			baseline := snapshot(&liveTopic, &live)
+			baseline.Version = postRevisions.NextVersionTx(tx, post.Id)
+			if err := postRevisions.CreateTx(tx, &baseline); err != nil {
+				return err
+			}
+			live.LatestRevisionId = baseline.Id
+			if live.ProcessStatus == posts.ProcessStatusNormal && liveTopic.Status == 1 && liveTopic.ProcessStatus == topics.ProcessStatusNormal {
+				live.PublishedRevisionId = baseline.Id
+			}
+		}
+		// Establish a legacy event baseline while the previous projection is still
+		// provably public. A draft can have normal revisions but has never produced
+		// a public occurrence. Do not infer a baseline later from revision status.
+		if live.PublishedRevisionId != 0 {
+			if _, _, err := agenteventservice.PublicSourceTx(tx, live.Id); err == nil {
+				var published postRevisions.Entity
+				if err := tx.Where("id = ? AND post_id = ?", live.PublishedRevisionId, live.Id).Take(&published).Error; err != nil {
+					return err
+				}
+				if err := agenteventservice.BaselineTx(tx, live.Id, published.Version); err != nil {
+					return err
+				}
+			} else if !errors.Is(err, agenteventservice.ErrInaccessible) && !errors.Is(err, gorm.ErrRecordNotFound) {
+				return err
+			}
+		}
+		preserveLive := live.ProcessStatus == posts.ProcessStatusNormal && liveTopic.Status == 1 && liveTopic.ProcessStatus == topics.ProcessStatusNormal
+
+		revision := snapshot(topic, post)
+		revision.EditorId = editorID
+		revision.Version = postRevisions.NextVersionTx(tx, post.Id)
+		revision.ProcessStatus = posts.ProcessStatusPending
+		if err := postRevisions.CreateTx(tx, &revision); err != nil {
+			return err
+		}
+		now := time.Now()
+		changes := map[string]any{"latest_revision_id": revision.Id, "published_revision_id": live.PublishedRevisionId, "last_editor_id": editorID, "last_edited_at": now}
+		if !preserveLive {
+			if err := fileusageservice.PrivatizeUnpublishedImagesTx(tx, topic.Id, post.Id, post.PostNo == 1); err != nil {
+				return err
+			}
+			changes["content"], changes["rendered_html"], changes["rendered_version"], changes["content_type"], changes["process_status"] = post.Content, post.RenderedHTML, post.RenderedVersion, post.ContentType, posts.ProcessStatusPending
+			if post.PostNo == 1 {
+				topic.ProcessStatus = topics.ProcessStatusPending
+				if err := topics.UpdateTopicEditableTx(tx, topic); err != nil {
+					return err
+				}
+				if err := topicCategoryIndex.ReplaceTopicCategoriesTx(tx, topic.Id, topic.CategoryIds); err != nil {
+					return err
+				}
+			}
+		}
+		if err := tx.Model(&posts.Entity{}).Where("id = ?", post.Id).Updates(changes).Error; err != nil {
+			return err
+		}
+		if err := fileusageservice.RegisterRevisionImagesTx(tx, revision.Id, post.UserId, post.Content, revision.ImageUrls); err != nil {
+			return err
+		}
+		payload, err := json.Marshal(Task{RevisionId: revision.Id})
+		if err != nil {
+			return err
+		}
+		if err := taskQueue.CreateTx(tx, &taskQueue.Entity{Type: TaskType, TaskJson: string(payload)}); err != nil {
+			return err
+		}
+		post.LatestRevisionId, post.PublishedRevisionId, post.ProcessStatus = revision.Id, live.PublishedRevisionId, posts.ProcessStatusPending
+		post.LastEditorId, post.LastEditedAt = editorID, &now
+		if live.PublishedRevisionId == 0 {
+			if err := feed.EventTx(tx, post.UserId, topic.Id, post.Id, "intent", true); err != nil {
+				return err
+			}
+		}
+		if after != nil {
+			return after(tx)
+		}
+		return nil
+	})
+}
+
+func snapshot(topic *topics.Entity, post *posts.Entity) postRevisions.Entity {
+	r := postRevisions.Entity{PostId: post.Id, Version: 1, EditorId: post.UserId, Content: post.Content, RenderedHTML: post.RenderedHTML, ProcessStatus: post.ProcessStatus, ContentType: post.ContentType}
+	if post.PostNo == 1 {
+		r.Title, r.CategoryIds, r.ImageUrls = topic.Title, topic.CategoryIds, topic.ImageUrls
+	}
+	return r
+}
+
+// ApplySnapshot only mutates caller-owned copies (including cached list entries).
+func ApplySnapshot(topic *topics.Entity, post *posts.Entity, revision postRevisions.Entity) {
+	post.Content, post.RenderedHTML, post.RenderedVersion, post.ContentType, post.ProcessStatus = revision.Content, revision.RenderedHTML, markdown2html.GetPostVersion(), revision.ContentType, revision.ProcessStatus
+	if post.PostNo == 1 {
+		topic.Title, topic.CategoryIds, topic.ImageUrls, topic.ProcessStatus = revision.Title, revision.CategoryIds, revision.ImageUrls, revision.ProcessStatus
+		topic.Excerpt = markdown2html.ExtractDescription(revision.Content, 200)
+		topic.FirstImageURL = markdown2html.ExtractFirstImageURL(revision.Content)
+		if topic.FirstImageURL == "" && len(topic.ImageUrls) > 0 {
+			topic.FirstImageURL = topic.ImageUrls[0]
+		}
+	}
+}

diff --git a/apps/gooseforum/app/service/publicationservice/time_test.go b/apps/gooseforum/app/service/publicationservice/time_test.go
new file mode 100644
index 000000000..52da4b64a
--- /dev/null
+++ b/apps/gooseforum/app/service/publicationservice/time_test.go
@@ -0,0 +1,23 @@
+package publicationservice
+
+import (
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/posts"
+	"testing"
+	"time"
+)
+
+func TestFirstPublicStartsAtApprovalAndSurvivesRestore(t *testing.T) {
+	created := time.Date(2026, 8, 1, 0, 0, 0, 0, time.UTC)
+	approved := created.Add(30 * 24 * time.Hour)
+	post := posts.Entity{CreatedAt: created}
+	if !stampFirstPublic(&post, approved, false) || !post.FirstPublicAt.Equal(approved) || post.FirstPublicEstimated {
+		t.Fatalf("approval clock %+v", post)
+	}
+	if stampFirstPublic(&post, approved.Add(24*time.Hour), false) || !post.FirstPublicAt.Equal(approved) {
+		t.Fatal("restored/edited publication reset clock")
+	}
+	legacy := posts.Entity{CreatedAt: created}
+	if stampFirstPublic(&legacy, approved, true) || !legacy.FirstPublicEstimated || !legacy.FirstPublicAt.Equal(created) {
+		t.Fatal("legacy time claimed exact approval")
+	}
+}

diff --git a/apps/gooseforum/app/service/pushpolicy/policy.go b/apps/gooseforum/app/service/pushpolicy/policy.go
new file mode 100644
index 000000000..3597f7cb0
--- /dev/null
+++ b/apps/gooseforum/app/service/pushpolicy/policy.go
@@ -0,0 +1,250 @@
+package pushpolicy
+
+import (
+	"encoding/json"
+	"errors"
+	"fmt"
+	"log/slog"
+	"time"
+
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/chat/imUserChatConfigs"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/chat/messages"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/eventNotification"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/posts"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/taskQueue"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/topics"
+	"github.com/YourTongji/YourTJ-Hub/apps/gooseforum/app/models/forum/users"
+	"gorm.io/gorm"
+)
+
+const Notification = "notification"
+const ChatMessage = "chat_message"
+
+type Preferences struct {
+	SystemDefaultOnly  bool `json:"systemDefaultOnly"`
+	Chat               bool `json:"chat"`
+	MentionsAndReplies bool `json:"mentionsAndReplies"`
+	Activity           bool `json:"activity"`
+	Following          bool `json:"following"`
+	System             bool `json:"system"`
+}
+type Changes struct {
+	Chat               *bool `json:"chat"`
+	MentionsAndReplies *bool `json:"mentionsAndReplies"`
+	Activity           *bool `json:"activity"`
+	Following          *bool `json:"following"`
+	System             *bool `json:"system"`
+}
+
+func Defaults() Preferences {
+	return Preferences{Chat: true, MentionsAndReplies: true, System: true, SystemDefaultOnly: true}
+}
+func load(userID uint64) (Preferences, map[string]bool, error) {
+	overrides, err := users.GetPushPreferences(userID)
+	if err != nil {
+		return Preferences{}, nil, err
+	}
+	result := Defaults()
+	_, explicit := overrides["system"]
+	result.SystemDefaultOnly = !explicit
+	raw, err := json.Marshal(overrides)
+	if err != nil {
+		return Preferences{}, nil, err
+	}
+	if err := json.Unmarshal(raw, &result); err != nil {
+		return Preferences{}, nil, err
+	}
+	return result, overrides, nil
+}
+func Get(userID uint64) (Preferences, error) { p, _, err := load(userID); return p, err }
+func Update(userID uint64, changes Changes) (Preferences, error) {
+	err := users.PatchPushPreferences(userID, map[string]*bool{"chat": changes.Chat, "mentionsAndReplies": changes.MentionsAndReplies, "activity": changes.Activity, "following": changes.Following, "system": changes.System})
+	if err != nil {
+		return Preferences{}, err
+	}
+	return Get(userID)
+}
+func Group(eventType string) string {
+	switch eventType {
+	case "inboxmail.delivery":
+		return "inboxmail"
+	case "chat_message":
+		return "chat"
+	case "mention", "post_reply", "comment":
+		return "mentionsAndReplies"
+	case "like":
+		return "activity"
+	case "follow", "topic_post", "wiki_updated":
+		return "following"
+	case "system", "badge", "review_pending", "review_approved", "review_rejected":
+		return "system"
+	default:
+		return "unknown"
+	}
+}
+func Allowed(userID uint64, eventType string) (bool, error) {
+	p, overrides, err := load(userID)
+	if err != nil {
+		return false, err
+	}
+	switch Group(eventType) {
+	case "inboxmail", "unknown":
+		return false, nil
+	case "chat":
+		return p.Chat, nil
+	case "mentionsAndReplies":
+		return p.MentionsAndReplies, nil
+	case "activity":
+		return p.Activity, nil
+	case "following":
+		return p.Following, nil
+	default:
+		if _, explicit := overrides["system"]; !explicit {
+			return eventType == "review_approved" || eventType == "review_rejected", nil
+		}
+		return p.System, nil
+	}
+}
+
+type Task struct {
+	UserId         uint64 `json:"userId"`
+	NotificationId uint64 `json:"notificationId,omitempty"`
+	SourceKind     string `json:"sourceKind,omitempty"`
+	SourceId       uint64 `json:"sourceId,omitempty"`
+}
+
+func (t Task) Source() (string, uint64) {
+	if t.SourceKind == "" {
+		return Notification, t.NotificationId
+	}
+	return t.SourceKind, t.SourceId
+}
+func Enqueue(tx *gorm.DB, channel string, userID, id uint64, kind string) error {
+	if userID == 0 || id == 0 {
+		return nil
+	}
+	data := Task{UserId: userID, SourceKind: kind, SourceId: id}
+	if kind == Notification {
+		data.NotificationId = id
+	}
+	raw, err := json.Marshal(data)
+	if err != nil {
+		return err
+	}
+	key := fmt.Sprintf("%s:%s:%d:%d", channel, kind, id, userID)
+	// type 用任务族常量即可：行级身份由 dedup_key/task_json 承载，查询侧
+	// 通过 taskQueue 的族谓词兼容历史「族 + id」行。
+	staged, err := taskQueue.CreateDeduplicatedTx(tx, &taskQueue.Entity{Type: channel, TaskJson: string(raw), DedupKey: &key})
+	if err == nil && staged {
+		Trace(channel, "outbox_staged", data)
+	}
+	return err
+}
+func Resolve(t Task) (eventNotification.Entity, *messages.Entity, error) {
+	kind, id := t.Source()
+	if t.UserId == 0 || id == 0 || users.IsAccountClosed(t.UserId) {
+		return eventNotification.Entity{}, nil, nil
+	}
+	if kind == ChatMessage {
+		msg, err := messages.GetPushSource(id)
+		if errors.Is(err, gorm.ErrRecordNotFound) {
+			return eventNotification.Entity{}, nil, nil
+		}
+		if err != nil {
+			return eventNotification.Entity{}, nil, err
+		}
+		member, err := imUserChatConfigs.PushRecipientAllowed(t.UserId, msg.SenderId, msg.ConvId)
+		if err != nil {
+			return eventNotification.Entity{}, nil, err
+		}
+		if !member || msg.IsRead != 0 || msg.SenderId == t.UserId {
+			return eventNotification.Entity{}, nil, nil
+		}
+		allowed, err := Allowed(t.UserId, ChatMessage)
+		if errors.Is(err, gorm.ErrRecordNotFound) {
+			return eventNotification.Entity{}, nil, nil
+		}
+		if !allowed && err == nil {
+			Trace("policy", "user_disabled", t)
+		}
+		if err != nil || !allowed {
+			return eventNotification.Entity{}, nil, err
+		}
+		blocked, err := users.InteractionBlocked(t.UserId, msg.SenderId)
+		if err != nil || blocked {
+			return eventNotification.Entity{}, nil, err
+		}
+		return eventNotification.Entity{}, &msg, nil
+	}
+	if kind != Notification {
+		return eventNotification.Entity{}, nil, nil
+	}
+	n := eventNotification.GetByID(id)
+	if n.Id == 0 || n.UserId != t.UserId || n.IsRead {
+		return eventNotification.Entity{}, nil, nil
+	}
+	// Only publicly visible topic/post names can enter third-party payloads.
+	if n.Payload.TopicId != 0 && n.EventType != "review_pending" && n.EventType != "review_rejected" {
+		topic, err := topics.GetPushSource(n.Payload.TopicId)
+		if errors.Is(err, gorm.ErrRecordNotFound) {
+			return eventNotification.Entity{}, nil, nil
+		}
+		if err != nil {
+			return eventNotification.Entity{}, nil, err
+		}
+		n.Payload.TopicTitle = topic.Title
+		if n.Payload.PostId != 0 {
+			visible, err := posts.PushSourceVisible(n.Payload.PostId, n.Payload.TopicId)
+			if !visible && err == nil {
+				return eventNotification.Entity{}, nil, nil
+			}
+			if err != nil {
+				return eventNotification.Entity{}, nil, err
+			}
+		}
+	}
+
+	actor := n.PrivateActorID
+	if actor == 0 {
+		actor = n.Payload.ActorId
+	}
+	blocked, err := users.InteractionBlocked(t.UserId, actor)
+	if err != nil || blocked {
+		return eventNotification.Entity{}, nil, err
+	}
+	allowed, err := Allowed(t.UserId, n.EventType)
+	if errors.Is(err, gorm.ErrRecordNotFound) {
+		return eventNotification.Entity{}, nil, nil
+	}
+	if !allowed && err == nil {
+		Trace("policy", "user_disabled", t)
+	}
+	if err != nil || !allowed {
+		return eventNotification.Entity{}, nil, err
+	}
+	return n, nil, nil
+}
+func Trace(channel, reason string, t Task) {
+	kind, id := t.Source()
+	slog.Debug("push delivery", "channel", channel, "reason", reason, "sourceKind", kind, "sourceId", id, "recipientId", t.UserId)
+}
+
+// Throttle only low-value hints; persisted notifications and chat are untouched.
+func Throttle(task *taskQueue.Entity, t Task, n eventNotification.Entity, channel string) (bool, error) {
+	if n.EventType != "like" && n.EventType != "topic_post" && n.EventType != "wiki_updated" && n.EventType != "follow" {
+		return false, nil
+	}
+	target := n.Payload.TopicId
+	if target == 0 {
+		target = n.Payload.ActorId
+	}
+	if target == 0 {
+		target = n.Payload.PostId
+	}
+	key := fmt.Sprintf("%s:%d:%s:%d", channel, t.UserId, n.EventType, target)
+	blocked, err := taskQueue.ThrottlePush(task.Id, taskQueue.TypePrefix(task.Type), key, time.Now().Add(-30*time.Second))
+	if blocked {
+		Trace(channel, "throttled", t)
+	}
+	return blocked, err
+}

