+	expired, err := ParseModerationAction(token, now.Add(ModerationActionTTL+time.Second))
+	if !errors.Is(err, ErrModerationActionExpired) || expired.ID != 7 {
+		t.Fatalf("expired: claims=%+v err=%v", expired, err)
+	}
