+
+function patchFor(context: Context) {
+  let patch = patches.get(context.trace)
+  if (!patch) {
+    if (patches.size >= 50) return undefined
+    patch = { trace: context.trace, visibleMask: 0, dwell: {} }
+    patches.set(context.trace, patch)
+  }
+  return patch
+}
+
+function startTimer() {
+  if (timer) return
+  timer = setInterval(() => {
+    updateDwell()
+    void flushFeedEvents()
+  }, 5000)
